import scala.annotation.tailrec

/**
 * Created by akito on 6/5/16.
 */
object Main {
  def main(args: Array[String]): Unit = {
    val n = io.StdIn.readLine().toInt

    def calc(p: ((Double, Double), (Double, Double))) = {
      val (p1, p2) = (p._1, p._2)
      val d = ((p2._1 - p1._1) / 3, (p2._2 - p1._2) / 2)
      val (s, t) = ((p1._1 + d._1, p1._2 + d._2), (p2._1 - d._1, p2._2 - d._2))
      val u = (s._1 + (t._1 - s._1) * Math.cos(Math.toRadians(60)) - (t._2 - s._2) * Math.sin(Math.toRadians(60)),
        s._2 + (t._1 - s._1) * Math.sin(Math.toRadians(60)) + (t._2 - s._2) * Math.cos(Math.toRadians(60)))
      Seq((p1, s),(s, u), (u, t), (t, p2))
    }

    @tailrec
    def kochCurve(n: Int, acc: Seq[((Double, Double), (Double, Double))]): Unit = {
      n match {
        case 0 =>
          acc.map(p => Seq(p._1, p._2)).flatten.distinct.foreach(t => println(s"${t._1} ${t._2}"))
        case _ =>
          kochCurve(n - 1, acc.map(calc).flatten)
      }
    }
    kochCurve(n, Seq(((0.0, 0.0), (100.0, 0.0))))
  }
}

import scala.io.StdIn.readInt
import scala.collection.mutable.ArrayBuffer

object Main {
  val c = Math.cos(Math.PI/3)
  val s = Math.sin(Math.PI/3)

  def getPoints(list:Array[(Double,Double)],i:Int):Array[(Double,Double)]  =
    if(i==0) list
    else {
      val b = new ArrayBuffer[(Double,Double)]
      for( k<-0 until list.length-1) {
        val i = list(k); val j = list(k+1)
        val p1 = ((i._1*2+j._1)/3,(i._2*2+j._2)/3)
        val p2 = ((i._1+j._1*2)/3,(i._2+j._2*2)/3)
        val (dx,dy) = (p2._1-p1._1,p2._2-p1._2)
        if(k==0) b+=i
        b+=(p1,(dx*c-dy*s+p1._1,dx*s+dy*c+p1._2),p2,j)
      }
      getPoints(b.toArray,i-1)
    }

