Point rotation60(Point p0, Point p1)
{
  /*
  R = (cos  -sin) (s)
      (sin   cos) (t)
  */
  float s = p1.x_ - p0.x_;
  float t = p1.y_ - p0.y_;

  float Rx = cos(60.f * PI / 180.f) * s - sin(60.f * PI / 180.f) * t + p0.x_;
  float Ry = sin(60.f * PI / 180.f) * s + cos(60.f * PI / 180.f) * t + p0.y_;

  return Point(Rx, Ry);
}


void kochCurve(int n, Point p0, Point p1)
{
