  float vx = p1.x_ - p0.x_;
  float vy = p1.y_ - p0.y_;

  Point s(p0.x_ + vx * (1.f/3.f), p0.y_ + vy * (1.f/3.f));
  Point t(p0.x_ + vx * (2.f/3.f), p0.y_ + vy * (2.f/3.f));
  Point u = rotation60(s, t);

#if DEBUG
