int koch(point start, point end, int n, int depth) {
  if (n == depth) {
    cout << start.x << " " << start.y << endl;

    return 0;
  }

  point s, t, u;
  if ((start.y == end.y) && (start.x < end.x)) {
    double lx = (end.x - start.x) / 3;

    s.x = start.x + lx;
    s.y = start.y;

    t.x = start.x + 2 * lx;
    t.y = start.y;

    u.x = start.x + 1.5 * lx;
    u.y = (u.x - s.x) * sqrt(3.0) + start.y;
  }
  else if ((start.x < end.x) && (start.y > end.y)) {
    double lx = (end.x - start.x) / 3;
    double ly = (start.y - end.y) / 3;

    s.x = start.x + lx;
    s.y = start.y - ly;

    t.x = start.x + 2 * lx;
    t.y = start.y - 2 * ly;

    u.x = end.x;
    u.y = s.y;
  }
  else if ((start.x > end.x) && (start.y > end.y)) {
    double lx = (start.x - end.x) / 3;
    double ly = (start.y - end.y) / 3;

    s.x = start.x - lx;
    s.y = start.y - ly;

    t.x = start.x - 2 * lx;
    t.y = start.y - 2 * ly;

    u.x = start.x;
    u.y = t.y;
  }
  else if ((start.y == end.y) && (start.x > end.x)) {
    double lx = (start.x - end.x) / 3;

    s.x = start.x - lx;
    s.y = start.y;

    t.x = start.x - 2 * lx;
    t.y = start.y;

    u.x = start.x - 1.5 * lx;
    u.y = start.y - (s.x - u.x) * sqrt(3.0);
  }
  else if ((start.x > end.x) && (start.y < end.y)) {
    double lx = (start.x - end.x) / 3;
    double ly = (end.y - start.y) / 3;

    s.x = start.x - lx;
    s.y = start.y + ly;

    t.x = start.x - 2 * lx;
    t.y = start.y + 2 * ly;

    u.x = end.x;
    u.y = start.y + ly;
  }
  else if ((start.x < end.x) && (start.y < end.y)) {
    double lx = (end.x - start.x) / 3;
    double ly = (end.y - start.y) / 3;

    s.x = start.x + lx;
    s.y = start.y + ly;

    t.x = start.x + 2 * lx;
    t.y = start.y + 2 * ly;

    u.x = start.x;
    u.y = start.y + 2 * ly;
  }

  koch(start, s, n + 1, depth);
  koch(s, u, n + 1, depth);
  koch(u, t, n + 1, depth);
  koch(t, end, n + 1, depth);

  return 0;
}

