double RADIAN = (M_PI / 3);
double COS = cos(RADIAN);
double SIN = sin(RADIAN);

pair<double, double> get_koch_point(pair<double, double>  b, pair<double, double> e) {
  pair<double, double> oe = make_pair(e.first - b.first, e.second  - b.second);

  double x = (oe.first * COS) - (oe.second * SIN);
  double y = (oe.first * SIN) + (oe.second * COS);

  return make_pair(b.first + x, b.second + y);
}

void koch(int i, int n, pair<double, double>  b, pair<double, double> e) {
  if (i >= n) {
    return;
  }
  pair<double, double> l = make_pair(b.first + ((e.first - b.first) / 3), b.second + ((e.second- b.second) / 3));
  pair<double, double> r = make_pair(b.first + 2 * ((e.first - b.first) / 3), b.second + 2 * ((e.second- b.second) / 3));
  pair<double, double> k = get_koch_point(l, r);

  koch(i+1, n, b, l);
  cout << l.first << " " << l.second << endl;
