  Point u{s.x + (v.x - sqrt(3) * v.y) / 2.0, s.y + (sqrt(3) * v.x + v.y) / 2.0};

  koch(p1, s, n, cnt);
  koch(s, u, n, cnt);
  koch(u, t, n, cnt);
  koch(t, p2, n, cnt);
}

