void fractale(){
    pair<long double, long double> l, r, temp;
    do {
        l = p.front(); p.pop();
        r = p.front(); p.pop();
        long double theta = atan2(r.second-l.second, r.first-l.first);
        long double leng = sqrt((r.second-l.second)*(r.second-l.second)+(r.first-l.first)*(r.first-l.first));
