        p.push(temp);
        p.push(temp);
        temp = make_pair(l.first+2*(r.first-l.first)/3.0, l.second+2*(r.second-l.second)/3.0);
        p.push(temp);
        p.push(temp);
        p.push(r);
    } while (r.first != 100);
}

