void	koch(unsigned int	n,
			 Point			P1,
			 Point			P2)
{
	if(n == 0){
		return;
	}

	// P1, P2からs, t, uを計算
	Point	s;
	Point	t;
	Point	u;

	s.X	= (2 * P1.X + P2.X) / 3;
	s.Y	= (2 * P1.Y + P2.Y) / 3;
	t.X	= (P1.X + 2 * P2.X) / 3;
	t.Y	= (P1.Y + 2 * P2.Y) / 3;

	u.X	= (t.X - s.X) * std::cos(M_PI / 3) - (t.Y - s.Y) * std::sin(M_PI / 3) + s.X;
	u.Y = (t.X - s.X) * std::sin(M_PI / 3) + (t.Y - s.Y) * std::cos(M_PI / 3) + s.Y;

	koch(n - 1, P1, s);
	s.print();

	koch(n - 1, s, u);
	u.print();

	koch(n - 1, u, t);
	t.print();

	koch(n - 1, t, P2);
}

