double pi = acos(-1);   //cos(pi)=-1

void Koch( int n, double x1, double y1, double x2, double y2, list<double>& x, list<double>& y )
{
    if( n == 1 )
    {
        for( list<double>::iterator itr1 = x.begin(), itr2 = y.begin(); itr1 != x.end(); itr1++, itr2++ )
        {
            if( *itr1 == x2 && *itr2 == y2 )
            {
                x.insert(itr1,x1+(x2-x1)/3);                                                      //sx
                y.insert(itr2,y1+(y2-y1)/3);                                                      //sy
                x.insert(itr1,(x1+(x2-x1)*2/3-(x1+(x2-x1)/3))*cos(60*pi/180)-((y1+(y2-y1)*2/3)-(y1+(y2-y1)/3))*sin(60*pi/180)+x1+(x2-x1)/3);    //ux
                y.insert(itr2,((x1+(x2-x1)*2/3)-(x1+(x2-x1)/3))*sin(60*pi/180)+((y1+(y2-y1)*2/3)-(y1+(y2-y1)/3))*cos(60*pi/180)+y1+(y2-y1)/3);  //uy
                x.insert(itr1,x1+(x2-x1)*2/3);                                                         //tx
                y.insert(itr2,y1+(y2-y1)*2/3);                                                         //ty
            }
        }
        //top[i++] = x1 + ( x2 - x1 ) / 3;                                                
        //top[i++] = y1 + ( y2 - y1 ) / 3;                                                
        //top[i++] = (tx - sx) * cos(60*pi/180) - (ty - sy) * sin(60*pi/180) + sx;        //ux 正規化+元の座標に戻す処理
        //top[i++] = (tx - sx) * sin(60*pi/180) + (ty - sy) * cos(60*pi/180) + sy;        //uy
        //top[i++] = x1 + ( x2 - x1 ) * 2 / 3;                                            
        //top[i++] = y1 + ( y2 - y1 ) * 2 / 3;                                            
        return;
    }

    Koch( n - 1, x1, y1, x2, y2, x, y );

    for( list<double>::iterator itr1 = x.begin(), itr2 = y.begin(); itr1 != x.end(); )    //n-1のコッホ曲線を作ることが出来たら、残りの処理を行う
    {
        double a = *itr1;                                                                 //listで管理してるので、値保持する必要がある
        double b = *itr2;
        itr1++;
        itr2++;
        Koch( n - ( n - 1 ), a, b, *itr1, *itr2, x, y );                                  //最後の処理なので、第一引数に与える数は常に1になるように設定
    }
    return;
}

