	void KochCurve(int level, const Point& p1, const Point& p2)
	{
		if (0 == level)
		{
			return;
		}

		Point s = { (2 * p1.x + p2.x) / 3, (2 * p1.y + p2.y) / 3 };
		Point t = { (p1.x + 2 * p2.x) / 3, (p1.y + 2 * p2.y) / 3 };
		double diff_x = t.x - s.x;
		double diff_y = t.y - s.y;
		double theta = 60.0 / 180 * M_PI;
		Point u = {
			std::cos(theta) * diff_x - std::sin(theta) * diff_y + s.x,
			std::sin(theta) * diff_x + std::cos(theta) * diff_y + s.y
		};

		KochCurve(level - 1, p1, s);
		std::cout << s.x << ' ' << s.y << '\n';
		KochCurve(level - 1, s, u);
		std::cout << u.x << ' ' << u.y << '\n';
		KochCurve(level - 1, u, t);
		std::cout << t.x << ' ' << t.y << '\n';
		KochCurve(level - 1, t, p2);
	}
