	double ty = (1 * p1y + 2 * p2y) / 3;
	double ux = (tx - sx) * cos(M_PI* 60.0 / 180.0) - (ty - sy) * sin(M_PI * 60.0 / 180.0) + sx;
	double uy = (tx - sx) * sin(M_PI * 60.0 / 180.0) + (ty - sy) * cos(M_PI * 60.0 / 180.0) + sy;
