#include<bits/stdc++.h>
using namespace std;

int N;
float pi = 3.1415926535897;


int co(float l[2], float r[2], int i, float radian, float lo) {
	if (i == N) {
		cout << l[0] << " " << l[1] << endl;
		return 0;
	}
	lo /= 3;
	float nl[2], nr[2], nt[2];
	nl[0] = l[0] * 2 / 3 + r[0] / 3;
	nl[1] = l[1] * 2 / 3 + r[1] / 3;
	nr[0] = r[0] * 2 / 3 + l[0] / 3;
	nr[1] = r[1] * 2 / 3 + l[1] / 3;
	nt[0] = (l[0] + r[0]) / 2;
	nt[1] = (l[1] + r[1]) / 2;
	nt[0] += lo * sqrt(3) / 2 * cos(radian + pi / 2);
	nt[1] += lo * sqrt(3) / 2 * sin(radian + pi / 2);
	i++;
	co(l, nl, i, radian,lo);
	co(nl, nt, i, radian+pi/3,lo);
	co(nt, nr, i, radian-pi/3,lo);
	co(nr, r, i, radian,lo);
	return 0;
}

int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);

	cin >> N;
	float l[2], r[2];
	l[0] = 0;
	l[1] = 0;
	r[0] = 100;
	r[1] = 0;
	co(l, r, 0, 0,100);
	cout << r[0] << " " << r[1] << endl;
}

