const double perTwoRootThree = 0.28867513459481287;

struct pos {
    double x;
    double y;

    void print() {
        printf("%f %f\n", x, y);
    }
};

pos getS(pos &p1, pos &p2) {
    return pos{(p1.x * 2 + p2.x) / 3, (p1.y * 2 + p2.y) / 3};
}

pos getU(pos &p1, pos &p2) {
    return pos{(p1.x + p2.x) / 2 + (p1.y - p2.y) * perTwoRootThree,
               (p1.y + p2.y) / 2 - (p1.x - p2.x) * perTwoRootThree};
}

pos getT(pos &p1, pos &p2) {
    return getS(p2, p1);
}

void kock(pos p1, pos p2, int depth) {
    if (depth-- == 0) p2.print();
    else {
        pos
                s = pos{(p1.x * 2 + p2.x) / 3, (p1.y * 2 + p2.y) / 3},
                u = pos{(p1.x + p2.x) / 2 + (p1.y - p2.y) * perTwoRootThree,
                        (p1.y + p2.y) / 2 - (p1.x - p2.x) * perTwoRootThree},
                t = pos{(p1.x + p2.x * 2) / 3, (p1.y + p2.y * 2) / 3};
        kock(p1, s, depth);
        kock(s, u, depth);
        kock(u, t, depth);
        kock(t, p2, depth);
    }
}

