using namespace std;

bool CanMakeNum(vector<int> &vNum, int index, int checkNum)
{
	if (checkNum == 0)
	{
		return true;
	}
	else if (checkNum < 0)
	{
		return false;
	}
	if (index >= vNum.size())
	{
		return false;
	}
	bool result = CanMakeNum(vNum, index + 1, checkNum - vNum[index]) || CanMakeNum(vNum, index + 1, checkNum);
	return result;
}

struct POINT
{
