	double y;
};

double rad = M_PI * 60.0 / 180.0;

void koch(int depth, POINT start, POINT end)
{
	if (depth == 0)
	{
		return;
	}

	//3分割
	POINT s;
	s.x = (start.x * 2.0 + end.x) / 3.0;
	s.y = (start.y * 2.0 + end.y) / 3.0;

	POINT t;
	t.x = (end.x * 2.0 + start.x) / 3.0;
	t.y = (end.y * 2.0 + start.y) / 3.0;

	POINT u;
	u.x = (t.x - s.x) * cosf(rad) - (t.y - s.y) * sinf(rad) + s.x;
	u.y = (t.x - s.x) * sinf(rad) + (t.y - s.y) * cosf(rad) + s.y;

	--depth;

	if (depth != 0)
	{
		koch(depth, start, s);
	}
	printf("%.8f %.8f\n", s.x, s.y);
	if (depth != 0)
	{
		koch(depth, s, u);
	}
	printf("%.8f %.8f\n", u.x, u.y);
	if (depth != 0)
	{
		koch(depth, u, t);
	}
	printf("%.8f %.8f\n", t.x, t.y);
	if (depth != 0)
	{
		koch(depth, t, end);
	}
}


