class point {
public:
  double x, y;
  point(double x0, double y0) {
    x = x0, y = y0;
  }
};

void kock(int d, point p1, point p2) {
  if (d == 0) return;

  double x0, y0, x1, y1, x2, y2;
  x0 = p1.x + (p2.x - p1.x) / 3;
  y0 = p1.y + (p2.y - p1.y) / 3;
  x2 = p2.x + (p1.x - p2.x) / 3;
  y2 = p2.y + (p1.y - p2.y) / 3;

  x1 = x0 + (x2 - x0) / 2 - (y2 - y0) / 2 * sqrt(3);
  y1 = y0 + (y2 - y0) / 2 + (x2 - x0) / 2 * sqrt(3);

  kock(d - 1, p1, point(x0, y0));
  fcout << x0 << SP << y0 << BR;

  kock(d - 1, point(x0, y0), point(x1, y1));
  fcout << x1 << SP << y1 << BR;

  kock(d - 1, point(x1, y1), point(x2, y2));
  fcout << x2 << SP << y2 << BR;

  kock(d - 1, point(x2, y2), p2);
}

int main() {

  int N; cin >> N;
  cout << "0 0" << BR;
  kock(N, point(0, 0), point(100, 0));
  cout << "100 0" << BR;
  return 0;
}

