point point::rot(point p, double theta){
    point tmp;
    tmp.x = p.x + cos(theta) * (x - p.x) - sin(theta) * (y - p.y);
    tmp.y = p.y + sin(theta) * (x - p.x) + cos(theta) * (y - p.y);
    return tmp;
}

void recursion(double n, point p, point q){
    if(n==0)return;
    point r, s, t;

