    Point np;
    np.first = p.first * cos - p.second * sin;
    np.second = p.first * sin + p.second * cos;
    return np;
}
void operate(int i, int n, Line line){
    if(i == n){
        std::printf("%0.8f %0.8f\n", line.first.first, line.first.second);
        return;
    }
    Point newPoint[3];
    std::pair<float, float> vec1;
    vec1.first = (line.second.first - line.first.first) / 3.f;
    vec1.second = (line.second.second - line.first.second) / 3.f;
    newPoint[0] = add(line.first, vec1);
    newPoint[1] = add(newPoint[0], rotate60FromOrign(vec1));
    newPoint[2] = add(newPoint[0], vec1);

    Line newLine[4];
    newLine[0].first = line.first;
    newLine[0].second = newPoint[0];
    newLine[1].first = newPoint[0];
    newLine[1].second = newPoint[1];
    newLine[2].first = newPoint[1];
    newLine[2].second = newPoint[2];
    newLine[3].first = newPoint[2];
    newLine[3].second = line.second;

    operate(i+1, n, newLine[0]);
    operate(i+1, n, newLine[1]);
    operate(i+1, n, newLine[2]);
    operate(i+1, n, newLine[3]);
}

