    int n;
    std::scanf("%d", &n);
    Line line;
    line.first.first = 0.0f;
    line.first.second = 0.0f;
    line.second.first = 100.0f;
    line.second.second = 0.0f;
    operate(0, n, line);
    printf("%0.8f %0.8f\n", line.second.first, line.second.second);
    return 0;
}

