	for (int i = 0; i < n; ++i) {
		lim += 3*(lim-1);
	}
	vector< pair<double,double> > p(lim,{-1,-1});
	p[0] = {0,0};
	p[lim-1] = {100,0};
	for (int count = 0; count < n; ++count) {
		int ind = 0;
		while (ind < lim-1) {
			if (p[ind].first >= 0) {
				int next = ind+1;
				while (p[next].first < 0) {
					++next;
				}
				int mid = (next+ind)/2;
				int left = (ind+mid)/2;
				int right = (next+mid)/2;
				p[left] = {(2*p[ind].first+p[next].first)/3,(2*p[ind].second+p[next].second)/3};
				p[right] = {(p[ind].first+2*p[next].first)/3,(p[ind].second+2*p[next].second)/3};
				int neg = 1;
				if (p[ind].first > p[left].first) {
					neg = -1;
				}
				double dis = sqrt(pow((p[right].first-p[left].first),2)+pow(p[right].second-p[left].second,2));
				double rad = atan((p[left].second-p[ind].second)/(p[left].first-p[ind].first));
				p[mid] = {p[left].first-(neg*dis*cos(pi-(rad+(pi/3)))),p[left].second+(neg*dis*sin(pi-(rad+(pi/3))))};
				ind = next-1;
			}
			++ind;
		}
	}
