    double dy=(p2.y-p1.y)/3;
    s.x=p1.x+dx;
    s.y=p1.y+dy;
    t.x=p2.x-dx;
    t.y=p2.y-dy;
    if(s.x<t.x)
    {
        if(s.y<t.y)
        {
            u.x=t.x-2*dx;
            u.y=t.y;
        }
        else if(s.y==t.y)
        {
            u.x=s.x+dx/2;
            u.y=s.y+(dx*sqrt(3))/2;
        }
        else{
            u.x=s.x+2*dx;
            u.y=s.y;
        }
    }
    else{
        if(s.y<t.y)
        {
            u.x=s.x+2*dx;
            u.y=s.y;
        }
        else if(s.y==t.y){
            u.x=s.x+dx/2;
            u.y=t.y+(dx*sqrt(3))/2;
