}

void rot60(double ret[2], double x[2]) {
  double tmp[2] = {x[0], x[1]};
  ret[0] = COS60 * tmp[0] - SIN60 * tmp[1];
  ret[1] = SIN60 * tmp[0] + COS60 * tmp[1];
}

