void solve(int n,point left,point right){
  if(n==0) return ;
  double t=M_PI/3;
  point midleft; midleft.x=(right.x+left.x*2)/3; midleft.y=(right.y+left.y*2)/3;
  point midright; midright.x=(right.x*2+left.x)/3; midright.y=(right.y*2+left.y)/3;
  point mid;
  mid.x=(midright.x-midleft.x)*cos(t)-(midright.y-midleft.y)*sin(t)+midleft.x;
  mid.y=(midright.x-midleft.x)*sin(t)+(midright.y-midleft.y)*cos(t)+midleft.y;
  solve(n-1,left,midleft);
  printf("%.6f %.6f\n",midleft.x,midleft.y);
  solve(n-1,midleft,mid);
  printf("%.6f %.6f\n",mid.x,mid.y);
  solve(n-1,mid,midright);
  printf("%.6f %.6f\n",midright.x,midright.y);
  solve(n-1,midright,right);
}
