    t = {(p1[0] + 2.0 * p2[0]) / 3, (p1[1] + 2.0 * p2[1]) / 3};
    u = {R[0][0] * (t[0] - s[0]) + R[0][1] * (t[1] - s[1]) + s[0],
         R[1][0] * (t[0] - s[0]) + R[1][1] * (t[1] - s[1]) + s[1]};

