    VP a;
    a.emplace_back(make_pair(0.0, 0.0));
    a.emplace_back(make_pair(100.0, 0.0));
    a = f(n, a);
    for (P p : a) {
        printf("%.9lf %.9lf\n", p.first, p.second);
    }
