#define Pi 3.1415926535

typedef struct Point
{
	double x;
	double y;
};

Point rotate(Point center,Point target,double angle)
{
	double ans_x;
	double ans_y;
	ans_x = (target.x - center.x)*cos(angle) - (target.y - center.y)*sin(angle) + center.x;
	ans_y = (target.x - center.x)*sin(angle) + (target.y - center.y)*cos(angle) + center.y;
	Point P = { ans_x,ans_y };
	return P;
}

void func(Point previous, Point next,int n)
{
	if (n <= 0);
	else
	{
		double x1 = previous.x;
		double y1 = previous.y;
		double x2 = next.x;
		double y2 = next.y;
		double lx = abs(x2 - x1);
		double ly = abs(y2 - y1);
		Point P1 = { x1 + lx / 3,y1 + ly / 3 };
		Point P2;
		Point P3 = { x1 + lx / 3 * 2,y1 + ly / 3 * 2 };
		P2 = rotate(P1, P3, Pi / 3);
		func(previous, P1, n - 1);
		printf("%.8lf %.8lf\n", P1.x, P1.y);
		func(P1, P2, n - 1);
		printf("%.8lf %.8lf\n", P2.x, P2.y);
		func(P2, P3, n - 1);
		printf("%.8lf %.8lf\n", P3.x, P3.y);
		func(P3, next, n - 1);
	}
}

