vector <pair<double,double>> x;
double degree30=atan(1)*2/3;
void fractals(){
	int len=(x.size()-1)*4;
	double x1,y1,x2,y2,x3,y3,a,a1,b1,a2,b2;
	for (int i=1;i<len;i+=4){
		x1=x[i-1].first;
		y1=x[i-1].second;
		x2=x[i].first;
		y2=x[i].second;
		x.insert(x.begin()+i,make_pair((x1*2+x2)/3,(y1*2+y2)/3));
		x.insert(x.begin()+i+1,make_pair((x1+x2*2)/3,(y1+y2*2)/3));
		a=(y2-y1)/(x2-x1);
		a1=tan(atan(a)+degree30);
		b1=y1-x1*a1;
		a2=tan(atan(a)-degree30);
		b2=y2-x2*a2;
		x3=(b2-b1)/(a1-a2);
		y3=(abs(a1)<100)?x3*a1+b1:x3*a2+b2;
		x.insert(x.begin()+i+1,make_pair(x3,y3));
	}
}
