		double x2 = next.x;
		double y2 = next.y;
		double lx = abs(x2 - x1);
		double ly = abs(y2 - y1);
		Point P1 = { x1 + lx / 3,y1 + ly / 3 };
		Point P2;
		Point P3 = { x1 + lx / 3 * 2,y1 + ly / 3 * 2 };
		P2 = rotate(P1, P3, Pi / 3);
