static void CreateTriangle(const Point& p1, const Point& p2, int i, int n, int r) {
  if (i == n)
    return;

  const int degree = 60 * r;
  const double kCos = cos(degree * M_PI / 180.0);
  const double kSin = sin(degree * M_PI / 180.0);

  const double dx = (p2.x - p1.x) / 3.f;
  const double dy = (p2.y - p1.y) / 3.f;
  const double d = sqrt(dx * dx + dy * dy);

  Point ps;
  ps.x = p1.x + dx;
  ps.y = p1.y + dy;

  Point pt;
  pt.x = p2.x - dx;
  pt.y = p2.y - dy;

  Point pu;
  pu.x = ps.x + d * kCos;
  pu.y = ps.y + d * kSin;

  CreateTriangle(p1, ps, i + 1, n, 1);
  printf("%f %f\n", ps.x, ps.y);
  CreateTriangle(ps, pu, i + 1, n, 2);
  printf("%f %f\n", pu.x, pu.y);
  CreateTriangle(pu, pt, i + 1, n, 6);
  printf("%f %f\n", pt.x, pt.y);
  CreateTriangle(pt, p2, i + 1, n, 1);
}

