void KochCurve(int n, Point p1, Point p2)
{
    if (n == 0)
    {
        return;
    }

    // p1とp2を三分割する
    double sx = (p2.x - p1.x) / 3 + p1.x;
    double sy = (p2.y - p1.y) / 3 + p1.y;
    Point s = {sx, sy};

    double tx = (p2.x - p1.x) * 2 / 3 + p1.x;
    double ty = (p2.y - p1.y) * 2 / 3 + p1.y;
    Point t = {tx, ty};

    // 分割点から正三角形を作る
    double rad = M_PI * 60 / 180;
    double ux = (tx - sx) * cos(rad) - (ty - sy) * sin(rad) + sx;
    double uy = (tx - sx) * sin(rad) + (ty - sy) * cos(rad) + sy;
    Point u = {ux, uy};

    KochCurve(n - 1, p1, s);
