{
	int Count = 0;
	std::cin >> Count;

	TPoints Points;
	Points.push_back(std::make_pair(0.,0.));
	Points.push_back(std::make_pair(100.,0.));

	TPoints::iterator It = Points.end();
	It--;
	Insert(Points,It,Count);

	while(!Points.empty())
	{
		std::cout << Points.front().first << " " << Points.front().second << std::endl;
		Points.pop_front();
	}
	return 0;
}

