    vector<pair<double, double> > v[7];
    v[0].push_back(make_pair(0.0, 0.0));
    v[0].push_back(make_pair(100.0, 0.0));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < v[i].size() - 1; j++) {
            double x1 = v[i][j].first, y1 = v[i][j].second;
            double x2 = v[i][j + 1].first, y2 = v[i][j + 1].second;
            double p = x2 - x1, d = (y2 - y1) / (x2 - x1);
            double l = sqrt((x2 - x1) * (x2 - x1) + (y2 - y1) * (y2 - y1)) / 6.0;
            v[i + 1].push_back(make_pair(x1, y1));
            v[i + 1].push_back(make_pair(x1 + (x2 - x1) / 3.0, y1 + (y2 - y1) / 3.0));
            if (d == 0) v[i + 1].push_back(make_pair((x1 + x2) / 2.0, (y1 + y2) / 2.0 + sqrt(3) * (x2 - x1) / 6.0));
            else if (p == 0) {
                if (x1 < x2) v[i + 1].push_back(make_pair((x1 + x2) / 2.0 + sqrt(3) * (y2 - y1) / 6.0, (y1 + y2) / 2.0));
                else v[i + 1].push_back(make_pair((x1 + x2) / 2.0 - sqrt(3) * (y2 - y1) / 6.0, (y1 + y2) / 2.0));
            }
            else {
                if (d > 0 && x1 < x2) v[i + 1].push_back(make_pair((x1 + x2) / 2.0 - l * d * sqrt(3.0 / (d*d + 1)), (y1 + y2) / 2.0 + l * sqrt(3.0 / (d*d + 1))));
                else if (d > 0) v[i + 1].push_back(make_pair((x1 + x2) / 2.0 + l * d * sqrt(3.0 / (d*d + 1)), (y1 + y2) / 2.0 - l * sqrt(3.0 / (d*d + 1))));
                else if (x1 < x2) v[i + 1].push_back(make_pair((x1 + x2) / 2.0 - l * d * sqrt(3.0 / (d*d + 1)), (y1 + y2) / 2.0 + l * sqrt(3.0 / (d*d + 1))));
                else v[i + 1].push_back(make_pair((x1 + x2) / 2.0 + l * d * sqrt(3.0 / (d*d + 1)), (y1 + y2) / 2.0 - l * sqrt(3.0 / (d*d + 1))));
            }
            v[i + 1].push_back(make_pair(x1 + 2.0 * (x2 - x1) / 3.0, y1 + 2.0 * (y2 - y1) / 3.0));

        }
        v[i + 1].push_back(make_pair(100.0, 0.0));
    }

    for (int i = 0; i < v[n].size(); i++) {
        cout << setprecision(10) << v[n][i].first << " " << v[n][i].second << endl;
    }

}

