struct P {
    double x, y;
    P() { x = 0.0, y = 0.0; }
    P(double x, double y) : x(x), y(y) {}
};
P operator+(const P &p1, const P &p2) {
    return P(p1.x + p2.x, p1.y + p2.y);
}
P operator-(const P &p1, const P &p2) {
    return P(p1.x - p2.x, p1.y - p2.y);
}
P operator*(double k, const P &p) {
    return P(k * p.x, k * p.y);
}
P operator*(const P &p, double k) {
    return k * p;
}

//       p5
//       /\
// p1___/ \___p2
//    p3  p4
void KochCurve(P p1, P p2, int n)
{
    P p3 = 1.0 / 3.0 * (p2 - p1);
    P p4 = 2.0 / 3.0 * (p2 - p1);
    P tmp = p4 - p3;
    P p5;

    double theta = M_PI / 3.0;
    p5.x = cos(theta) * tmp.x - sin(theta) * tmp.y + p3.x;
    p5.y = sin(theta) * tmp.x + sin(theta) * tmp.y + p3.y;

    if (n == 1) {
        printf("%.8f %.8f\n", p1.x, p1.y);
        printf("%.8f %.8f\n", p3.x, p3.y);
        printf("%.8f %.8f\n", p5.x, p5.y);
        printf("%.8f %.8f\n", p4.x, p4.y);
        printf("%.8f %.8f\n", p2.x, p2.y);
    }
    else {
        KochCurve(p1, p3, n - 1);
        KochCurve(p3, p5, n - 1);
        KochCurve(p5, p4, n - 1);
        KochCurve(p4, p2, n - 1);
    }
}

