void Koch(Vector p1, Vector p2, int i) {
	if (i < 1)return;
	Vector s, t, u;
	s.x = (2 * p1.x + p2.x) / 3;
	s.y = (2 * p1.y + p2.y) / 3;

	u.x = (p1.x + 2 * p2.x) / 3;
	u.y = (p1.y + 2 * p2.y) / 3;

	const double root3 = sqrt(3);
	t.x = (u.x - s.x) / 2 - (u.y - s.y) * root3 / 2;
	t.x += s.x;
	t.y = (u.x - s.x) * root3 / 2 + (u.y - s.y) / 2;
	t.y += s.y;

	Koch(p1, s, i - 1);
	printf("%.8f %.8f\n", s.x, s.y);

	Koch(s, t, i - 1);
	printf("%.8f %.8f\n", t.x, t.y);

	Koch(t, u, i - 1);
	printf("%.8f %.8f\n", u.x, u.y);

	Koch(u, p2, i - 1);
}

