const double pi = 3.14159265359;

struct vec {
	double x;
	double y;
	const vec operator +(const vec &r) const{
		vec t;
		t.x = this->x + r.x;
		t.y = this->y + r.y;
		return t;
	}
	const vec operator -(const vec &r)const {
		vec t;
		t.x = this->x - r.x;
		t.y = this->y - r.y;
		return t;
	}
};

vec shift(vec o, vec p) {
	return  o - p;
}

vec rotate(vec v, double alpha) {
	using namespace std;
	vec t;
	t.x = cos(alpha) * v.x - sin(alpha) * v.y;
	t.y = sin(alpha) * v.x + cos(alpha) * v.y;
	return t;
}

vec LfG(vec o, double a, vec G) {
	vec L;
	L = shift(o, G);
	L = rotate(L, a);
	return L;
}

vec GfL(vec o, double a, vec L) {
	vec G;
	G = rotate(L, -a);
	G = shift(o, G);
	return G;
}


vec get_s(vec p1, vec p2) {
	vec s;
	s.x = p1.x * 2 / 3 + p2.x * 1 / 3;
	s.y = p1.y * 2 / 3 + p2.y * 1 / 3;
	return s;
}

vec get_t(vec p1, vec p2) {
	vec t;
	t.x = p1.x * 1 / 3 + p2.x * 2 / 3;
	t.y = p1.y * 1 / 3 + p2.y * 2 / 3;
	return t;
}

double get_alpha(vec v1, vec v2) {
	double l_v1 = std::sqrt(v1.x * v1.x + v1.y * v1.y);
	double l_v2 = std::sqrt(v2.x * v2.x + v2.y * v2.y);
	return std::acos((v1.x*v2.x + v1.y*v2.y) / (l_v1 * l_v2));
}

void print(vec v) {
	std::cout << v.x << " " << v.y << std::endl;
}


void koch(vec p1,vec p2, int c) {
	if (c == 0)
		return;
	c--;

	vec s = get_s(p1, p2);
	vec t = get_t(p1, p2);

	double a = get_alpha(s, t);
	vec ls = LfG(s, a, s);
	vec lt = LfG(s, a, t);
	vec lu = rotate(lt, pi / 3);
	vec u = GfL(s, a, lu);

	koch(p1, s, c);
	print(s);
	koch(s, u, c);
	print(u);
	koch(u, t, c);
	print(t);
	koch(t, p2, c);
}



