void spr(double x1,double y1,double x2,double y2,int d){
  assert(d>=0);  
  double sx,sy,ux,uy,tx,ty;

  if(d==0){
    cout << fixed << x1 << ' ' << y1 << endl;
  }else{
    sx=(2.0*x1+x2)/3.0;
    sy=(2.0*y1+y2)/3.0;
    tx=(x1+2.0*x2)/3.0;
    ty=(y1+2.0*y2)/3.0;

    //u-s=(s-p1)*exp(i??/3)
    //u=(s-p1)*(1/2+i???3/2)+s
    ux=(sx-x1)*(1.0/2.0)-(sy-y1)*(sqrt(3.0)/2.0)+sx;
    uy=(sx-x1)*(sqrt(3.0)/2.0)+(sy-y1)*(1.0/2.0)+sy;

    spr(x1,y1,sx,sy,d-1);
    spr(sx,sy,ux,uy,d-1);
    spr(ux,uy,tx,ty,d-1);
    spr(tx,ty,x2,y2,d-1);
  }  
}

