	function<bool(const vector<int>& v, const int index, const int num)> canGenerateNumImpl = [&](const vector<int>& v, const int index, const int num) {
		if (num == 0)return true;
		if (num < 0 || index == v.size())return false;
		return canGenerateNumImpl(v, index + 1, num) || canGenerateNumImpl(v, index + 1, num - v.at(index));
	};
	return canGenerateNumImpl(vec, 0, number);
}

struct Point{
	Point(const double x = 0.0, const double y = 0.0) :x(x), y(y) {}
	Point operator+(const Point& rhs)const {
		return Point(x + rhs.x, y + rhs.y);
	}
	Point operator-(const Point& rhs)const {
		return Point(x - rhs.x, y - rhs.y);
	}
	Point operator*(const double num) const {
		return Point(x*num, y*num);
	}
	Point operator/(const double num) const {
		return Point(x/num, y/num);
	}
	double x, y;
};

ostream& operator<<(ostream& os, const Point& p){
	os << p.x << " " << p.y;
	return os;
}


//2次元で点を左回りに回転する
Point rotatePoint(const Point& rotationCenter, const Point& rotationTarget){
	static const double sixtyDegreeInRadian = M_PI / 3.0;
	static const double  cosine60 = cos(sixtyDegreeInRadian);
	static const double  sine60 = sin(sixtyDegreeInRadian);
	const Point v(rotationTarget - rotationCenter);
	const Point rotatedV(v.x*cosine60 - v.y*sine60, v.x*sine60 + v.y*cosine60);
	return rotationCenter + rotatedV;
}

void printKoch(const Point& p1, const Point& p2, const int n) {
	const function<void(const Point& p1, const Point& p2, const int depth)> printKochImpl
		= [&](const Point& p1_, const Point& p2_, const int depth_) {
		if (depth_ >= n) return;
		const Point& vec = (p2_ - p1_)/3.0;
		const Point p1_1 = p1_ + vec;
		const Point p1_3 = p1_ + vec * 2.0;
		const Point p1_2 = rotatePoint(p1_1, p1_3);


		printKochImpl(p1_, p1_1, depth_ + 1);
		cout << fixed << setprecision(5) << p1_1 << endl;
		printKochImpl(p1_1, p1_2, depth_ + 1);
		cout << fixed << setprecision(5) << p1_2 << endl;
		printKochImpl(p1_2, p1_3, depth_ + 1);
		cout << fixed << setprecision(5) << p1_3 << endl;
		printKochImpl(p1_3, p2_, depth_ + 1);

	};
	if (n < 0)return;
	cout << fixed << setprecision(5) << p1 << endl;
	printKochImpl(p1, p2, 0);
	cout << fixed << setprecision(5) << p2 << endl;
}

