constexpr double sqrt3 = 1.73205080757;

struct Vec2
{
    double x, y;

    Vec2() : x(0.0), y(0.0) {}
    Vec2(double x_, double y_) : x(x_), y(y_) {}

    Vec2 operator-() const { return {x * -1, y * -1};}
    Vec2 operator+(const Vec2& rhs) const { return {x + rhs.x, y + rhs.y}; }
    Vec2 operator-(const Vec2& rhs) const { return {x - rhs.x, y - rhs.y}; }
    Vec2 operator*(double d) const { return {x * d, y * d}; }
    Vec2 operator/(double d) const { return {x / d, y / d}; }

    Vec2 operator+=(const Vec2& rhs) { x += rhs.x; y += rhs.y; return *this; }
    Vec2 operator-=(const Vec2& rhs) { x -= rhs.x; y -= rhs.y; return *this; }
    Vec2 operator*=(const Vec2& rhs) { x *= rhs.x; y *= rhs.y; return *this; }
    Vec2 operator/=(const Vec2& rhs) { x /= rhs.x; y /= rhs.y; return *this; }
};

Vec2 operator*(double d, const Vec2& rhs) { return {rhs*d}; }

void Koch(list<Vec2>& vertices, int n)
{
    if (n == 0)
        return;

    auto end = vertices.end();
    for (auto r = ++vertices.begin(); r != end; ++r)
    {
        auto l = r;
        --l;

        const Vec2 lr = *r - *l;

        list<Vec2> li = {
            {*l + lr / 3},
            {(*l + *r) / 2 + Vec2(-lr.y, lr.x) / 6 * sqrt3},
            {*r - lr / 3}        
        };

        vertices.insert(r, li.begin(), li.end());
    }

    Koch(vertices, --n);
}

