void rc(int left, int right, int direct, int depth)
{
	if (depth == n + 1)
		return;
	int mid, midl, midr;
	double length = 100;
	mid = (left + right) / 2;
	midl = (left + mid) / 2;
	midr = (mid + right) / 2;
	for (int i = 0; i < depth; i++)
		length /= 3;
	p[midl].x = (p[left].x * 2 + p[right].x) / 3;
	p[midr].x = (p[right].x * 2 + p[left].x) / 3;
	p[midl].y = (p[left].y * 2 + p[right].y) / 3;
	p[midr].y = (p[right].y * 2 + p[left].y) / 3;

	p[mid].x = p[midl].x + cos((direct + 1) * M_PI / 3) * length;
	p[mid].y = p[midl].y + sin((direct + 1) * M_PI / 3) * length;

	rc(left, midl, direct, depth + 1);
	rc(midl, mid, direct + 1, depth + 1);
	rc(mid, midr, direct - 1, depth + 1);
	rc(midr, right, direct, depth + 1);
	return;
}

