#define PI 3.14159265

struct Matrix
{
	Matrix(float angle)
	{
		float radian = (float)(angle / 180.0f * PI);
		m11 = cos(radian);
		m12 = -sin(radian);
		m21 = sin(radian);
		m22 = cos(radian);
	}

	float m11, m12, m21, m22;
};

struct Vector
{
	Vector() {}
	Vector(float x, float y) :x(x), y(y) {}

	friend ostream& operator<<(ostream& os, const Vector& vector)
	{
		os << vector.x << " " << vector.y << endl;
		return os;
	}

	friend Vector operator+(const Vector& left, const Vector& right)
	{
		Vector result;
		result.x = left.x + right.x;
		result.y = left.y + right.y;
		return result;
	}

	friend Vector operator-(const Vector& left, const Vector& right)
	{
		Vector result;
		result.x = left.x - right.x;
		result.y = left.y - right.y;
		return result;
	}

	friend Vector operator*(const Vector& left, float right)
	{
		Vector result;
		result.x = left.x * right;
		result.y = left.y * right;
		return result;
	}

	friend Vector operator/(const Vector& left, float right)
	{
		Vector result;
		result.x = left.x / right;
		result.y = left.y / right;
		return result;
	}

	friend Vector operator*(const Vector& left, const Matrix& right)
	{
		Vector result;
		result.x = left.x * right.m11 + left.y * right.m12;
		result.y = left.x * right.m21 + left.y * right.m22;
		return result;
	}

	float x, y;
};

Matrix g_m(60);
void KochCurve(int n, const Vector& head, const Vector& tail)
{
	if (0 == n)
	{
		//cout << tail.x << " " << tail.y << endl;
		cout << tail;
		return;
	}

	Vector s = (tail - head) / 3.0f + head;
	Vector t = tail - (tail - head) / 3.0f;
	Vector u = (t - s) * g_m + s;

	KochCurve(n - 1, head, s);
	KochCurve(n - 1, s, u);
	KochCurve(n - 1, u, t);
	KochCurve(n - 1, t, tail);
}

void KochCurve(int n, float p1x, float p1y, float p2x, float p2y)
{
	if (0 == n)
	{
		//cout << p1x << " " << p1y << endl;
		cout << p2x << " " << p2y << endl;
		return;
	}

	float sx = (p2x - p1x) / 3.0f + p1x;
	float sy = (p2y - p1y) / 3.0f + p1y;
	float tx = (p2x - p1x) / 3.0f * 2 + p1x;
	float ty = (p2y - p1y) / 3.0f * 2 + p1y;

	float radian = (float)(60.0f / 180.0f * PI);
	float ux = (tx - sx) * cos(radian) - (ty - sy) * sin(radian) + sx;
	float uy = (tx - sx) * sin(radian) + (ty - sy) * cos(radian) + sy;

	KochCurve(n - 1, p1x, p1y, sx, sy);
	KochCurve(n - 1, sx, sy, ux, uy);
	KochCurve(n - 1, ux, uy, tx, ty);
	KochCurve(n - 1, tx, ty, p2x, p2y);
}

