    c1[0] = x0/3*2 + x1/3; c1[1] = y0/3*2 + y1/3;
    c2[0] = (x0+x1)/2 + (-1)*(y1-y0)/3 * sin(pi/3);
    c2[1] = (y0+y1)/2 + (x1-x0)/3 * sin(pi/3);
    c3[0] = x0/3 + x1/3*2; c3[1] = y0/3 + y1/3*2;
    koch_curve(x0, y0, c1[0], c1[1], n-1);
    koch_curve(c1[0], c1[1], c2[0], c2[1], n-1);
    koch_curve(c2[0], c2[1], c3[0], c3[1], n-1);
    koch_curve(c3[0], c3[1], x1, y1, n-1);
  }
}

