pair< double, double > polarToCartesian(pair< double, double > origin, double row, double theta) {
  return pair< double, double > (origin.first + row * cos(theta), origin.second + row * sin(theta));
}

void kochCurve(pair< double, double > origin, double row, double theta, int n) {
  if (n == 0) {
    pair< double, double > holder = polarToCartesian(origin, row, theta);
    cout << abs(holder.first) << ' ' << abs(holder.second) << endl;
    return;
  }
  kochCurve(origin, row/3, theta, n-1);
  kochCurve(polarToCartesian(origin, row/3, theta), row/3, theta+M_PI/3, n-1);
  kochCurve(polarToCartesian(origin, row/(sqrt(3)), theta+M_PI/6), row/3, theta-M_PI/3, n-1);
  kochCurve(polarToCartesian(origin, 2*row/3, theta), row/3, theta, n-1);
  return;
}

