    }
    //aはπ/3だけ回転させる複素数
    //u,s,tは問題文のものに対応
    P s, t, u, a;
    s = lp + (rp - lp) / 3.;
    t = lp + (rp - lp) * 2. / 3.;
    a = polar(abs(rp-lp)/3, arg(rp-lp) + PI/3.);
    u = s + a;
    rec(lp, s, n-1);
    rec(s, u, n-1);
    rec(u, t, n-1);
    rec(t, rp, n-1);
}

void solve(void){
    cin >> N;

    P p1(0., 0.);
    P p2(L, 0.);

    rec(p1, p2, N);

    //右端の点は格納されないので最後に追加
    ans.pb(p2);

    for (auto p : ans) {
        printf("%.6lf %.6lf\n", p.real(), p.imag());
    }

}

int main(void){
  solve();
  //cout << "yui(*-v・)yui" << endl;
  return 0;
}

