	rec(depth+1,bx,by,mx,my);
	printf("%.10f %.10f\n",mx,my);
	rec(depth+1,mx,my,cx,cy);
	printf("%.10f %.10f\n",cx,cy);
	rec(depth+1,cx,cy,dx,dy);

}

