void calcKoch(int n, Point p1, Point p2){
  Point n1;			// p1,p2を1:2で内分した点
  Point n2;			// p1,p2を2:1で内分した点
  Point t;			// n1,n2からなされる正三角形の頂点
  if (n == 0) {
    return;
  }
  n1.x = (p1.x*2 + p2.x*1)/(1+2);
  n1.y = (p1.y*2 + p2.y*1)/(1+2);
  n2.x = (p2.x*2 + p1.x*1)/(1+2);
  n2.y = (p2.y*2 + p1.y*1)/(1+2);

  t.x = (n2.x - n1.x)*cos((M_PI*1)/3) - (n2.y-n1.y)*sin((M_PI*1)/3) + n1.x;
  t.y = (n2.x - n1.x)*sin((M_PI*1)/3) + (n2.y-n1.y)*cos((M_PI*1)/3) + n1.y;

  calcKoch(n-1, p1, n1);
  cout << n1.x << " " << n1.y << "\n";
  calcKoch(n-1, n1, t);
  cout << t.x << " " << t.y << "\n";
  calcKoch(n-1, t, n2);
  cout << n2.x << " " << n2.y << "\n";
  calcKoch(n-1, n2, p2);



}

