void fractal(vertex* v1, vertex* v2, vertex* v3, vertex* left, vertex* right){
	double x1;
	double x2;
	double y1;
	double y2;
	x1 = left->x;
	y1 = left->y;
	x2 = right->x;
	y2 = right->y;

	v1->x = x1*2/3 + x2/3;
	v1->y = y1*2/3 + y2/3;

	v3->x = x1/3 + x2*2/3;
	v3->y = y1/3 + y2*2/3;

	v2->x = (x1+x2)/2 + sqrt(3)/6 * (y1-y2);
	v2->y = (y1+y2)/2 + sqrt(3)/6 * (x2-x1);
}

