typedef long long int ll;

void dfs(ll n, pair<double,double> p1, pair<double,double> p2)
{

    if(n == 0){
        return;
    }

    pair<double,double> s;
    pair<double,double> t;
    pair<double,double> u;

    s.first = (p2.first + 2 * p1.first) / 3;
    s.second = (p2.second + 2 * p1.second) / 3;
    t.first = (2 * p2.first +  p1.first) / 3;
    t.second = (2 * p2.second + p1.second) / 3;
    u.first = s.first + (t.first - s.first) * cos(M_PI / 3) - (t.second - s.second) * sin(M_PI / 3);
    u.second = s.second + (t.first - s.first) * sin(M_PI / 3) + (t.second - s.second) * cos(M_PI / 3);

    dfs(n - 1, p1, s);
    cout << setprecision(10) << s.first << " " << setprecision(10) << s.second  << "\n";
    dfs(n - 1, s, u);
    cout << setprecision(10) << u.first << " " << setprecision(10) << u.second  << "\n";
    dfs(n - 1, u, t);
    cout << setprecision(10) << t.first << " " << setprecision(10) << t.second  << "\n";
    dfs(n - 1, t, p2);
}

