void solve(int i, Point a, Point b){
    if(i == 0) return;
    Point s, u, t;
    s.x = a.x + (b.x - a.x) / 3;
    s.y = a.y + (b.y - a.y) / 3;
    t.x = a.x + (b.x - a.x) / 3 * 2;
    t.y = a.y + (b.y - a.y) / 3 * 2;
    double rad = 60.0 / 180 * M_PI;
    u.x = (t.x - s.x) * cos(rad) - (t.y - s.y) * sin(rad) + s.x;
    u.y = (t.x - s.x) * sin(rad) + (t.y - s.y) * cos(rad) + s.y;
    solve(i - 1, a, s);
