    vector<Point> points;
    Point p1(0, 0), p2(100, 0);

    points.push_back(p1);
    koch(depth, points, p1, p2);
    points.push_back(p2);

    for (int i = 0; i < points.size(); i++) {
        Point& p = points[i];
        printf("%.8f %.8f\n", p.x, p.y);
    }

    return 0;
}

