//centerを中心にpをtheta回転する(左回りが正)
pair<double, double> rotate(pair<double, double> center, pair<double, double> p, double theta) {
    double new_x = (p.first  - center.first ) * cos(theta) - (p.second - center.second) * sin(theta) + center.first;
    double new_y = (p.second - center.second) * cos(theta) + (p.first   - center.first) * sin(theta) + center.second;

    return make_pair(new_x, new_y);
}


int n;
vector<pair<double, double>> ans;

void kochCurve(int i, pair<double, double> p1, pair<double, double> p2) {
    //曲線を描き終わったとき
    if(i > n) {
        return;
    }

    //p1とp2の距離を1/3にしたもの
    double dist_x = (p2.first  - p1.first ) / 3;
    double dist_y = (p2.second - p1.second) / 3;

    //左側の座標(p1とp2を3等分する点の左側)
    double left_x = p1.first + dist_x;
    double left_y = p1.second + dist_y;
    pair<double, double> left(left_x, left_y);

    //右側の座標(p1とp2を3等分する点の右側)
    double right_x = left_x + dist_x;
    double right_y = left_y + dist_y;
    pair<double, double> right(right_x, right_y);

    //正三角形の頂点座標
    //    左側の座標を中心に右側の座標を左回転させる(左回転が正。　※座標回転の公式を参照)
    pair<double, double> vertex = rotate(left, right, M_PI/3); 

    //再帰
    kochCurve(i + 1, p1    , left);
    ans.push_back(left);

    kochCurve(i + 1, left  , vertex);
    ans.push_back(vertex);
    kochCurve(i + 1, vertex, right);

    ans.push_back(right);
    kochCurve(i + 1, right , p2);
}


int main() {
    cin >> n;

    pair<double, double> p1(0  , 0);
    pair<double, double> p2(100, 0);

    ans.push_back(p1);
    kochCurve(1, p1, p2);
    ans.push_back(p2);

    for (int i = 0; i < (int)ans.size(); ++i)
    {
        printf("%.8lf %.8lf\n", ans[i].first, ans[i].second);
    }

    return 0;
}

