double dit(pair<double,double>x, pair<double,double> y){
    return sqrt(pow(x.first - y.first, 2) + pow(x.second - y.second, 2));
}

void koch(int cnt, pair<double,double>a, pair<double,double> b){
    if(n == cnt) return;

    pair<double,double> s,t,u;

    if(a.first < b.first && a.second == b.second){
        s = make_pair(a.first+((b.first-a.first)/3), a.second);
        u = make_pair(b.first-((b.first-a.first)/3),b.second);
        double l = dit(s,u);
        t = make_pair(s.first+(l/2),s.second+l*sin(M_PI/3));
    }
    else if(a.first < b.first && a.second < b.second){
        s = make_pair(a.first+((b.first-a.first)/3), a.second+((b.second-a.second)/3));
        u = make_pair(b.first-((b.first-a.first)/3),b.second-((b.second-a.second)/3));
        t = make_pair(u.first-dit(s,u),u.second);
    }
    else if(a.first > b.first && a.second < b.second){
        s = make_pair(a.first-((a.first-b.first)/3), a.second+((b.second-a.second)/3));
        u = make_pair(b.first+((a.first-b.first)/3),b.second-((b.second-a.second)/3));
        t = make_pair(s.first - dit(s,u),s.second);
    }
    else if(a.first > b.first && a.second == b.second){
        s = make_pair(a.first-((a.first-b.first)/3), a.second);
        u = make_pair(b.first+((a.first-b.first)/3),b.second);
        double l  = dit(s,u);
        t = make_pair(s.first - (l/2),s.second-(l*sin(M_PI/3)));
        }
    else if(a.first > b.first && a.second > b.second){
        s = make_pair(a.first-((a.first-b.first)/3), a.second-((a.second-b.second)/3));
        u = make_pair(b.first+((a.first-b.first)/3),b.second+((a.second-b.second)/3));
        t = make_pair(u.first + dit(s,u),u.second);
    }
    else{
        s = make_pair(a.first+((b.first-a.first)/3), a.second-((a.second-b.second)/3));
        u = make_pair(b.first-((b.first-a.first)/3),b.second+((a.second-b.second)/3));
        t = make_pair(s.first + dit(s,u),s.second);
    }

    koch(cnt+1,a,s);
    // cout << fixed << setprecision(8)<< s.first << " " << s.second << endl;
    cout << s.first << " " << s.second << endl;
    koch(cnt+1,s,t);
