//function kochCurve
void kochCurve(XY p1,XY p2,int n){
  XY s,u,t;
  double xlen;

  xlen=p2.x-p1.x;

  s.x=xlen/3;
  s.y=p1.y;
  t.x=2*xlen/3;
  t.y=p2.y;
  u.x=p2.x*cos(M_PI/3)-p2.y*sin(M_PI/3);
  u.y=s.x*sin(M_PI/3)+s.y*cos(M_PI/3);

  //print
  cout <<p1.x<<" "<<p1.y<<endl;
  cout <<s.x<<" "<<s.y<<endl;
  cout <<u.x<<" "<<u.y<<endl;
