vector<pair<double, double> > v;

void makeCoch(int n, pair<double, double> a, pair<double, double> b)
{	
	if (n == 0) return;

	pair<double, double> p1, p2, p3;

	p1.first = (2 * a.first + b.first) / 3.0; p1.second = (2 * a.second + b.second) / 3.0;
	p2.first = (2 * b.first + a.first) / 3.0; p2.second = (2 * b.second + a.second) / 3.0;

	double d = sqrt((p1.first - p2.first) * (p1.first - p2.first) + (p2.second - p1.second) * (p2.second - p1.second));

	p3.first = p1.first + d * cos(M_PI / 3.0);
	p3.second = p1.second + d * sin(M_PI / 3.0);

	v.push_back(p1); v.push_back(p2); v.push_back(p3);

	makeCoch(n - 1, a, p1);
	makeCoch(n - 1, p1, p3);
	makeCoch(n - 1, p3, p2);
	makeCoch(n - 1, p2, b);
}

