class Point {
public:
  double x;
  double y;

  Point(double x=0.0, double y=0.0):
    x(x),
    y(y)
  {
  }

};

void showPoint(Point point) {
  std::cout << point.x << " " << point.y << std::endl;
}

void koch(int n, int k, Point left, Point right) {

  if (k > n) {
    return;
  }

  Point s, t, u;

  Point left_to_right(right.x - left.x, right.y - left.y);

  s.x = left.x + left_to_right.x / 3.0;
  s.y = left.y + left_to_right.y / 3.0;

  u.x = left.x + left_to_right.x * 2.0 / 3.0;
  u.y = left.y + left_to_right.y * 2.0 / 3.0;

  Point s_to_u(u.x - s.x, u.y - s.y);

  t.x = s.x + cos(M_PI/3) * s_to_u.x - sin(M_PI/3) * s_to_u.y;
  t.y = s.y + sin(M_PI/3) * s_to_u.x + cos(M_PI/3) * s_to_u.y;

  koch(n, k+1, left, s);
  showPoint(s);
  koch(n, k+1, s, t);
  showPoint(t);
  koch(n, k+1, t, u);
  showPoint(u);
  koch(n, k+1, u, right);

}

int main() {

  int n;
  std::cin >> n;

  Point left(0.0, 0.0), right(100.0, 0.0);
  showPoint(left);
  koch(n, 1, left, right);
  showPoint(right);

  return 0;
}

