using point_t = std::tuple<double, double>;
using pointList = std::list<point_t>;
using pointItr = pointList::iterator;

template <typename T>
class Vector {

public:
   Vector(T x = T{}, T y = T{}) {
      vector = std::tie(x, y);
   }

   Vector(point_t to, point_t from = point_t{}) :
      Vector(std::get<0>(to) - std::get<0>(from),
            std::get<1>(to) - std::get<1>(from)) {
   }

   T getRadius() {
      return hypot(std::get<0>(vector), std::get<0>(vector));
   }

   void setRadius(T radius) {
      auto power = getRadius();

      std::get<0>(vector) *= radius / power;
      std::get<1>(vector) *= radius / power;
   }

   static Vector<T> rotate(Vector<T> base, double angle) {
      auto x = std::get<0>(base.vector) * std::cos(angle) - std::get<1>(base.vector) * std::sin(angle);
      auto y = std::get<1>(base.vector) * std::cos(angle) + std::get<0>(base.vector) * std::sin(angle);

      return { x, y };
   }

   point_t getTarget(point_t from) {
      auto x = std::get<0>(from) + std::get<0>(vector);
      auto y = std::get<1>(from) + std::get<1>(vector);

      return std::make_tuple(x, y);
   }

private:
   std::tuple<T, T> vector;

};

point_t operator +(point_t from, Vector<double> direction) {
   return direction.getTarget(from);
}

point_t operator +(Vector<double> direction, point_t from) {
   return from + direction;
}

void _getKochCurve(pointList & list, pointItr begin, pointItr end, int count) {
   if (count <= 0)  { return; }

   auto start = begin;
   auto next = std::next(start);
   while (start != end) {
      auto s_to_t = Vector<double>{ *next, *start };
      s_to_t.setRadius(s_to_t.getRadius() / 3);
      auto s = *start + s_to_t;
      auto t = s + s_to_t;

      auto s_to_u = Vector<double>::rotate(s_to_t, M_PI / 3);
      auto u = s + s_to_u;

      list.insert(next, { s, u, t });

      start = next;
      ++next;
   }

   return _getKochCurve(list, begin, end, count - 1);
}

pointList getKochCurve(point_t begin, point_t end, int count) {
   pointList list = { begin, end };
   _getKochCurve(list, list.begin(), std::next(list.begin()), count);

   return list;
}

int main() {

   int n;
   std::cin >> n;
   auto list = getKochCurve(point_t{ 0, 0 }, point_t{ 100, 0 }, n);

   for (auto && point : list) {
      std::cout << std::fixed << std::setprecision(8) << std::get<0>(point) << " " << std::get<1>(point) << std::endl;
   }

   return 0;

}

