    double tx = (ax + 2 * bx) / 3;
    double ty = (ay + 2 * by) / 3;
    double ux = ccw60x(sx, sy, tx, ty);
    double uy = ccw60y(sx, sy, tx, ty);
    koch(n - 1, sx, sy, ux, uy);
    cout << ux << ' ' << uy << endl;
    koch(n -1, ux, uy, tx, ty);
    cout << tx << ' ' << ty << endl;
    koch(n -1, tx, ty, bx, by);
}

