void solve(int n,P p1,P  p2){
    if(n==0)
        return;
    P s;
    s.x = (p2.x-p1.x)/3.0;
    s.y = (p2.y-p1.y)/3.0;
    P t;
    t.x = s.x*2.0;
    t.y = s.y*2.0;
    P u;
    double theta = atan((s.y-t.y)/(s.x-t.x));
    rotate(-theta,&s);
    rotate(-theta,&t);
    u.x = (t.x+s.x)/2.0;
    u.y = (t.x-s.x)*(sqrt(3)/2.0);
    rotate(theta,&s);
    rotate(theta,&t);
