	double ti = M_PI / 3.0;
	P s, u, t;
	t.dX = (pRight.dX + 2 * pLeft.dX) / 3;
	t.dY = (pRight.dY + 2 * pLeft.dY) / 3;
	u.dX = (2 * pRight.dX + pLeft.dX) / 3;
	u.dY = (2 * pRight.dY + pLeft.dY) / 3;
	s.dX = (u.dX - t.dX)*cos(ti) - (u.dY - t.dY)*sin(ti) + t.dX;
	s.dY = (u.dX - t.dX)*sin(ti) + (u.dY - t.dY)*cos(ti) + t.dY;

