	Koch(n - 1, t, s);
	cout << setiosflags(ios::fixed) << setprecision(8) << s.dX << " " << s.dY << endl;
	Koch(n - 1, s, u);
	cout << setiosflags(ios::fixed) << setprecision(8) << u.dX << " " << u.dY << endl;
	Koch(n - 1, u, pRight);
}


