{
    // read input
    int depth;
    cin >> depth;

    // initialize res
    res.clear();

    // get curve
    Point strt(0,0);
    Point end(100, 0);
    kochCurve(depth, strt, end);
    res.push_back(end);

    // print out
    for (auto point: res)
        printf("%f %f\n", point.x, point.y);
    return 0;
}

