using namespace std;
void make_fractal(int n, int dep, double a, double b, double x, double y){
    double c = (2*a+x)/3;
    double d = (2*b+y)/3;
    double e = (a+2*x)/3;
    double f = (b+2*y)/3;
    //回転
    double neox = (1/2.0)*(e-c)-(sqrt(3.0)/2)*(f-d)+c;
    double neoy = (sqrt(3.0)/2)*(e-c)+(1/2.0)*(y-d)+d;
    //頂点の配列
    double newx[] = {a, c, neox, e, x};
    double newy[] = {b, d, neoy, f, y};

    if(n == 1){
        for(int i=0; i<5; i++){
            printf("%f %f\n", newx[i], newy[i]);
        }
        return;
    }
    for(int i=0; i<dep; i++){
        make_fractal(n-1, 4*dep, newx[i], newy[i], newx[i+1], newy[i+1]);
    }
}

