Point computeTriangleTop(const Point s,const Point t){
	Point a = t - s;
	const double pi = 3.14159265359879;
	const double cos60 = cos(pi / 3);
	const double sin60 = sin(pi / 3);
	return	s + 
		Point(cos60*a.x - sin60*a.y,
				sin60*a.x + cos60*a.y);
}
