typedef pair<double,double> P;

list<P> li;

list<P>::iterator genTri(list<P>::iterator itr){
	P p1 = *itr;
	itr++;
	if(itr == li.end()){
		return itr;
	}
	P p2 = *itr;
	P s = make_pair((p1.first * (2.0/3.0) + p2.first / 3.0),(p1.second * (2.0/3.0) + p2.second / 3.0));
	P t = make_pair((p1.first / 3.0 + p2.first * (2.0/3.0)),(p1.second / 3.0 + p2.second * (2.0/3.0)));
	P center = make_pair((p1.first + p2.first) / 2.0,(p1.second + p2.second) / 2.0);
	double r = sqrt(3) / 2.0;
	double y = t.first - s.first;
	double x = -(t.second - s.second);
	P u = make_pair(center.first + r*x,center.second + r*y);

	itr = li.insert(itr,t);
	itr = li.insert(itr,u);
	itr = li.insert(itr,s);
	itr++; itr++; itr++; // itr = p2
	return itr;
}

void printList(){
	for(list<P>::iterator itr = li.begin(); itr != li.end(); itr++){
		P p = *itr;
		printf("%.8f %.8f\n",p.first,p.second);
	}
}

