struct Point { double x, y; };

void koch(int n, Point a, Point b) {
	if (n == 0) { return; }

	Point s, t, u;
	double roll = M_PI*(60 / 180);

	s.x = (2.0*a.x + b.x) / 3.0;
	s.y = (2.0*a.y + b.y) / 3.0;
	t.x = (a.x + 2.0*b.x) / 3.0;
	t.y = (a.y + 2.0*b.y) / 3.0;
	u.x = ((t.x - s.x)*cos(roll) - (t.y - s.y)*sin(roll) + s.x);
	u.y = ((t.x - s.x)*sin(roll) + (t.y - s.y)*cos(roll) + s.y);

	koch(n - 1, a, s);
	printf("%.8f %.8f\n", s.x, s.y);
	koch(n - 1, s, u);
	printf("%.8f %.8f\n", u.x, u.y);
	koch(n - 1, u, t);
	printf("%.8f %.8f\n", t.x, t.y);
	koch(n - 1, t, b);
}

