// コッホ曲線を作成する関数
void Koch_curve(st_Coordinate p1, st_Coordinate p2, int n)
{
    double split_x, split_y, tmp_x, tmp_y;
    st_Coordinate s, t, u;

    if( n == 0 )
    {
        return;
    }

    split_x = ( p2.x - p1.x ) / 3.0;
    split_y = ( p2.y - p1.y ) / 3.0;

    // 左端の座標
    s.x = p1.x + split_x;
    s.y = p1.y + split_y;
    // 右端の座標
    t.x = p2.x - split_x;
    t.y = p2.y - split_y;

    // 正三角形の頂点の座標
    u.x = ( p2.x - p1.x ) / 2.0;

    tmp_x = u.x - s.x;
    tmp_y = ( p2.y - p1.y ) / 2.0;
    u.y = tmp_y + ( tmp_x * tan( M_PI / 3.0 ) );

    // n の減算
    n--;

    if( n > 0 )
    {
        Koch_curve(p1, s, n);
        Koch_curve(s, u, n);
        Koch_curve(u, t, n);
        Koch_curve(t, p2, n);
    }
    else
    {
        // 座標の表示
        printf("%lf %lf\n", p1.x, p1.y);
        printf("%lf %lf\n", s.x, s.y);
        printf("%lf %lf\n", u.x, u.y);
        printf("%lf %lf\n", t.x, t.y);
        printf("%lf %lf\n", p2.x, p2.y);
    }

    return;
}

