	pair<double, double> a{ax, ay};
	pair<double, double> c{cx, cy};
	pair<double, double> b{(cx - ax) / 2 - (cy - ay) * sin60 + ax, (cx - ax) * sin60 + (cy - ay) / 2 + ay};


