	fcout << a.first << " " << a.second << endl;
	solve(n - 1, a, b);
	fcout << b.first << " " << b.second << endl;
	solve(n - 1, b, c);
	fcout << c.first << " " << c.second << endl;
	solve(n - 1, c, y);

}

