struct Pt {
  double x;
  double y;

  Pt operator+(const Pt& other) { return {x + other.x, y + other.y}; }
  Pt operator-(const Pt& other) { return {x - other.x, y - other.y}; }
  Pt operator/(double n) { return {x / n, y / n}; }
  Pt rotate60() { return {.5 * x - sin60 * y, sin60 * x + .5 * y}; }
};

void koch(vector<Pt>& pts, Pt src, Pt dst, int i) {
  pts.push_back(src);
  if (i) {
    auto step = (dst - src) / 3;
    auto p1 = src + step;
    auto p2 = p1 + step.rotate60();
    auto p3 = p1 + step;
    koch(pts, p1, p2, i - 1);
    koch(pts, p2, p3, i - 1);
  }
  pts.push_back(dst);
}

