struct Coodinate {
    double x;
    double y;
    Coodinate* next;
};
Coodinate* initCoodinate()
{
    Coodinate* c = (Coodinate*)malloc(sizeof(Coodinate));
    c->x = -1;
    c->y = -1;
    c->next = c;
    return c;
}

void kochCurve(Coodinate* start, Coodinate* end, int n)
{
    if (n == 0) {
	return;
    }
    Coodinate* s = initCoodinate();
    Coodinate* t = initCoodinate();
    Coodinate* u = initCoodinate();
    start->next = s;
    s->x = (end->x - start->x) / 3;
    s->y = (end->y - start->y) / 3;
    s->next = t;
    u->x = 2 * ((end->x - start->x) / 3);
    u->y = 2 * ((end->y - start->y) / 3);
    u->next = end;
    double th = M_PI * 60.0 / 180.0;
    t->x = (u->x - s->x) * cos(th) - (u->y - s->y) * sin(th) + s->x;
    t->y = (u->x - s->x) * sin(th) + (u->y - s->y) * cos(th) + s->y;
    t->next = u;
    n--;
    kochCurve(start, s, n);
    kochCurve(s, t, n);
    kochCurve(t, u, n);
    kochCurve(u, end, n);
}
