    std::cin >> n;
    List list;
    Point alpha = {  0, 0};
    Point omega = {100, 0};
    list.push_back(alpha);
    list.push_back(omega);
    InsertKochCurve(list, list.begin(), --list.end(), n);
    Output(list);
    return 0;
}

