using namespace std;

struct P{
    double x, y;
    P(){}
    P(double x,double y):x(x),y(y){}
};


void rotate(double theta,P *p){
    double x = (*p).x*cos(theta)-(*p).y*sin(theta);
    double y = (*p).x*sin(theta)+(*p).y*cos(theta);
    (*p).x = x;
    (*p).y = y; 
}                   

void print(P p){
    printf("%.8lf %.8lf\n",p.x,p.y);
}

void solve(int n,P p1,P  p2){
    if(n==0)
        return;
    P s;
    s.x = (p2.x-p1.x)/3.0;
    s.y = (p2.y-p1.y)/3.0;
    P t;
    t.x = s.x*2.0;
    t.y = s.y*2.0;
    P u;
    double theta = atan((s.y-t.y)/(s.x-t.x));
    rotate(-theta,&s);
    rotate(-theta,&t);
    u.x = (t.x+s.x)/2.0;
    u.y = abs(t.x-s.x)*(sqrt(3)/2.0);
    rotate(theta,&s);
    rotate(theta,&t);
    rotate(theta,&u);

    solve(n-1,p1,s);
    print(s);
    solve(n-1,s,u);
    print(u);
    solve(n-1,u,t);
    print(t);
    solve(n-1,t,p2);
}

