		cout<<setprecision(6)<<fixed<<p.X<<" "<<p.Y<<endl;
		return;
	}
	vec v=(q-p)/(point)3;
	point r=p+v;
	point s=r+rotate(v,PI/3);
	point t=q-v;
	f(n,p,r);
	f(n,r,s);
	f(n,s,t);
	f(n,t,q);
	return;
}

int main(){
	int n;
	cin>>n;
	f(n,(point)0,(point)(100));
	cout<<100<<" "<<0<<endl;
}

