void mk3(double *L, double *R, int remain) {
    cout << fixed << setprecision(5);
    /*cout << "\t~~~~~~~~~~~~~~~~~~~~" << endl;
    cout << "\tremain: " << remain << endl;*/
    if (remain >= 1) {
        double L2[2] = {(L[0]*2+R[0])/3, (L[1]*2+R[1])/3};
        double R2[2] = {(L[0]+R[0]*2)/3, (L[1]+R[1]*2)/3};
        double C[2];
        double xl = L2[0];
        double yl = L2[1];
        double xr = R2[0];
        double yr = R2[1];
        C[0] = (xr+xl)/2 - sqrt(3) * (yr-yl)/2;
        C[1] = sqrt(3) * (xr-xl)/2 + (yr+yl)/2;
        // test v
        /*cout << "\tl : " << L[0] << " | " << L[1] << endl;
        cout << "\tl2: " << L2[0] << " | " << L2[1] << endl;
        cout << "\tc : " << C[0] << " | " << C[1] << endl;
        cout << "\tr2: " << R2[0] << " | " << R2[1] << endl;
        cout << "\tr : " << R[0] << " | " << R[1] << endl;*/
        // test ^
        mk3(L, L2, remain-1);
        mk3(L2, C, remain-1);
        mk3(C, R2, remain-1);
        mk3(R2, R, remain-1);
    } else cout << L[0] << ' ' << L[1] << endl;
}
