void growKochCurve(vector<pair<double, double>> &, int);

int main(int argc, char const *argv[])
{
    vector<pair<double, double>> vertices{make_pair(0.0, 0.0), make_pair(100.0, 0.0)};

    int n = 0;
    cin >> n;

    growKochCurve(vertices, n);

    for (auto it = vertices.begin(); it != vertices.end(); ++it)
    {
        cout << fixed << setprecision(8) << abs((*it).first) << " " << abs((*it).second) << endl;
    }

    return 0;
}

void growKochCurve(vector<pair<double, double>> &vertices, int depth)
{
    pair<double, double> s(make_pair(0.0, 0.0)), t(make_pair(0.0, 0.0)), u(make_pair(0.0, 0.0));

    for (int j = 0; j < depth; ++j)
    {
        auto it = vertices.begin(); 
        for (int i = 0; i < pow(4, j); ++i)
        {
            s.first = (2.0 * (*it).first + (*(it + 1)).first) / 3.0;
            s.second = (2.0 * (*it).second + (*(it + 1)).second) / 3.0;
            t.first = ((*it).first + 2.0 * (*(it + 1)).first) / 3.0;
            t.second = ((*it).second + 2.0 * (*(it + 1)).second) / 3.0;
            // cout << "s = (" << s.first << ", " << s.second << ")" << endl;
            // cout << "t = (" << t.first << ", " << t.second << ")" << endl;

            u.first = s.first + 0.5 * (t.first - s.first) + 0.5 * sqrt(3.0) * (t.second - s.second);
            u.second = s.second + 0.5 * (t.second - s.second) - 0.5 * sqrt(3.0) * (t.first - s.first);            
            // cout << "u = (" << u.first << ", " << u.second << ")" << endl;

            it++;
            it = vertices.insert(it, s);
            it++;
            it = vertices.insert(it, u);
            it++;
            it = vertices.insert(it, t);
            it++;
        }
    }
}

