        v.eb(make_pair(a.F, a.S));
        return;
    }
    double sx = a.F + (b.F - a.F) / 3;
    double sy = a.S + (b.S - a.S) / 3;
    double tx = b.F - (b.F - a.F) / 3;
    double ty = b.S - (b.S - a.S) / 3;
    double theta = M_PI / 3;
    double s = tx - sx;
    double t = ty - sy;
    // https://www.buildinsider.net/small/bookkinectv2/0803
    double ux = sx + s * cos(theta) - t * sin(theta);
    double uy = sy + s * sin(theta) + t * cos(theta);
    koch(n + 1, {a.F, a.S}, {sx, sy});
    koch(n + 1, {sx, sy}, {ux, uy});
    koch(n + 1, {ux, uy}, {tx, ty});
    koch(n + 1, {tx, ty}, {b.F, b.S});
}
