pdd rot(pdd p, double rad = PI * 60.0 / 180.0) {
	return pdd(cos(rad) * p.first - sin(rad) * p.second, sin(rad) * p.first + cos(rad) * p.second);
}

void rec(pdd p1, pdd p2, int depth) {
	if (depth == 0) {
		printf("%.10f %.10f\n", p1.first, p1.second);
		return;
	}

	pdd s((2 * p1.first + p2.first) / 3, (2 * p1.second + p2.second) / 3);
	pdd t((p1.first + 2 * p2.first) / 3, (p1.second + 2 * p2.second) / 3);
	pdd r = rot(pdd(t.first - s.first, t.second - s.second));
	pdd u(s.first + r.first, s.second + r.second);

	vector<pdd> pts;
	pts.push_back(p1);
	pts.push_back(s);
	pts.push_back(u);
	pts.push_back(t);
	pts.push_back(p2);
	for (int i = 0; i < 4; i++)
		rec(pts[i], pts[i + 1], depth - 1);
}

