const double r60 = M_PI / 3;

pair<double,double> rotate60(pair<double, double> set)
{
    return {set.first * cos(r60) - set.second * sin(r60),set.first*sin(r60) + set.second*cos(r60)};
}

pair<double, double> tri(pair<double, double> p1, pair<double, double> p2)
{
    if(p1.first - p2.first > -0.00001 && p1.first - p2.second < 0.00001)
        return {p1.first - fabs(p1.second - p2.second)* sqrt(3) / 2,(p1.second + p2.second) / 2};
    double a = (p1.second - p2.second)/(p1.first - p2.first);
    if(a > -0.00001 && a < 0.00001)
        return {(p1.first + p2.first) / 2, fabs(p2.first - p1.first) * sqrt(3) / 2};
    pair<double,double> rem = {p2.first-p1.first,p2.second-p1.second};
    rem = rotate60(rem);
    return {p1.first + rem.first, p1.second + rem.second};
}

void koch(vector<pair<double, double> > &v, int depth, int start)
{
    if(depth >= 1)
    {
        v.insert(v.begin()+ start + 1
                 ,{{(v[start].first* 2 + v[start+1].first) / 3,(v[start].second* 2 + v[start+1].second) / 3}
                     ,{(v[start].first + v[start+1].first*2)/3,(v[start].second + v[start+1].second*2)/3}});
        v.insert(v.begin()+start+2,tri(v[start+1],v[start+2]));
        if(depth > 1)
        {
            for(int i = start + 3; i >= start; i--)
            {
                koch(v, depth-1, i);
            }
        }
    }

}


