using namespace std;
using P = pair<double, double>;

P operator -(P a, P b){
    return make_pair(a.first - b.first, a.second - b.second);
}
P operator +(P a, P b){
    return make_pair(a.first + b.first, a.second + b.second);
}
P operator *(double a, P b){
    return make_pair(a*b.first, a*b.second);
}
P operator /(P a, double b){
    return make_pair(a.first/b, a.second/b);
}

void koch_curve(vector<P>& pnt, P p1, P p2, int n){
    if(!n) return;
    P dp = p2 - p1;
    P dv = dp/3;
    P s = p1 + dv, t = p1 + 2*dv;
    P u = p1 + dp/2 + 0.5*sqrt(3)*make_pair(-dv.second, dv.first);
    koch_curve(pnt, p1, s, --n);
    pnt.push_back(s);
    koch_curve(pnt, s, u, n);
    pnt.push_back(u);
    koch_curve(pnt, u, t, n);
    pnt.push_back(t);
    koch_curve(pnt, t, p2, n);
    return;
}

int main(){
    int n; cin >> n;
    vector<P> pnt;

    P p1 = make_pair(0.0, 0.0); pnt.push_back(p1);
    P p2 = make_pair(100.0, 0.0);
    koch_curve(pnt, p1, p2, n);
    pnt.push_back(p2);

    for(P p : pnt) cout << p.first << ' ' << p.second << endl;
    return 0;
}

