typedef std::pair<double, double> P;

void koch(P st, P vec, long depth){
	if(depth == 0){
		printf("%lf %lf\n", st.first + vec.first, st.second + vec.second);
	}else{
		koch(st, std::make_pair(vec.first / 3, vec.second/3), depth-1);
		st.first += vec.first / 3;
		st.second += vec.second / 3;

		koch(st, std::make_pair((vec.first / 2 - vec.second * sqrt3_2)/3, (vec.second / 2 + vec.first * sqrt3_2)/3), depth-1);
		st.first += (vec.first / 2 - vec.second * sqrt3_2)/3;
		st.second += (vec.second / 2 + vec.first * sqrt3_2)/3;

		koch(st, std::make_pair((vec.first / 2 + vec.second * sqrt3_2) / 3, (vec.second / 2 - vec.first * sqrt3_2) / 3), depth-1);
		st.first += (vec.first / 2 + vec.second * sqrt3_2) / 3;
		st.second += (vec.second / 2 - vec.first * sqrt3_2) / 3;

		koch(st, std::make_pair(vec.first / 3, vec.second/3), depth-1);
	}
}

