typedef pair<double,double> Pd;

int n;

Pd solve(Pd a, Pd b){
  // a, bを1辺とする正三角形のもう一つの頂点が求めるやつ
  // ただし案時計回りにa, b, cとする
  double a1,a2,b1,b2;
  a1 = a.first; a2 = a.second; b1 = b.first; b2 = b.second;
  Pd c;
  if (a2 == b2){
    // a, b が水平の場合
    c.first = (a1 + b1) / 2;
    c.second = a2;
    double dy = b1 - a1;
    c.second += dy * (double)sqrt(3.0) / 2;
  }else if (a1 < b1){
    c.second = max(a2, b2);
    double dx = (b1 - a1) * 2;
    if (a2 < b2) c.first = b1 - dx;
    else c.first = a1 + dx;
  }else if (a1 > b1){
    c.second = min(a2, b2);
    double dx = abs(b1-a1);
    if (a2 < b2) c.first = b1-dx;
    else c.first = a1+dx;
  }
  return c;
}

void dfs(Pd a, Pd b, int depth){
  // 引数a,bがn=depthのときの始点と終点。
  if (n == depth){
    // 被りを防ぐために始点のみ出力すう
    cout <<fixed <<setprecision(12) <<a.first <<" " <<a.second <<endl;
    return;
  }
  // a, b は4つの領域に分けられる
  Pd a1;
  a1.first = (a.first * 2 + b.first) / 3;
  a1.second= (a.second* 2 + b.second)/ 3;
  Pd a3;
  a3.first = (a.first + b.first * 2) / 3;
  a3.second = (a.second + b.second * 2) / 3;
  Pd a2 = solve(a1, a3);
  dfs(a, a1, depth+1);
  dfs(a1, a2, depth+1);
  dfs(a2, a3, depth+1);
  dfs(a3, b, depth+1);
}

