		lx = p2x - p1x;
		sx = p1x + lx/3;
		tx = p1x + 2*lx/3;
		if (p1y > p2y)
		{
			ly = p1y - p2y;
			ty = p2y + ly/3;
			sy = p2y + 2*ly/3;
			ux = (tx - sx)*cos(pi/3) - (sy - ty)*sin(pi/3) + sx;
			uy = (tx - sx)*sin(pi/3) - (sy - ty)*cos(pi/3) + sy;
