struct vec2d
{
	double x, y;
	vec2d(double x_, double y_) :x(x_), y(y_) {}
	vec2d operator+(const vec2d&v) { return vec2d(x + v.x, y + v.y); }
	vec2d operator-(const vec2d&v) { return vec2d(x - v.x, y - v.y); }
	vec2d operator*(double k) { return vec2d(x * k, y * k); }
	vec2d operator/(double k) { return vec2d(x / k, y / k); }
	double norm() { return hypot(x, y); }
};
list<vec2d>vertex{ vec2d(0, 0),vec2d(100, 0) };
void Koch_curve(const list<vec2d>::iterator&p1, const list<vec2d>::iterator&p2, const int depth_max)
{
	const static double sqrt_3 = sqrt(3);
	static int depth = 0;
	if (++depth <= depth_max)
	{
		const auto s = vertex.insert(next(p1), (*p1 * 2 + *p2) / 3);
		const auto u = vertex.insert(next(s),
			abs(p1->y - p2->y) < 0.00000001  ? vec2d((p1->x + p2->x) / 2, p1->y + (p2->x - p1->x) / 2 / sqrt_3)
			: p1->x < p2->x && p1->y < p2->y ? vec2d(p1->x, p1->y + (*p2 - *p1).norm() / sqrt_3)
			: p1->x < p2->x && p1->y > p2->y ? vec2d(p2->x, p2->y + (*p2 - *p1).norm() / sqrt_3)
			: p1->x > p2->x && p1->y < p2->y ? vec2d(p2->x, p2->y - (*p2 - *p1).norm() / sqrt_3)
			:                                  vec2d(p1->x, p1->y - (*p2 - *p1).norm() / sqrt_3)
		);
		const auto t = vertex.insert(next(u), (*p1 + *p2 * 2) / 3);
		Koch_curve(p1, s, depth_max);
		Koch_curve(s, u, depth_max);
		Koch_curve(u, t, depth_max);
		Koch_curve(t, p2, depth_max);
	}
	--depth;
}
