		ux = (tx - sx) * cos(_rag(60.0)) - (ty - sy) * sin(_rag(60.0)) + sx;
		uy = (tx - sx) * sin(_rag(60.0)) + (ty - sy) * cos(_rag(60.0)) + sy;

		fractale(n - 1, p1x, p1y, sx, sy);//1
		fractale(n - 1, sx, sy, ux, uy);//2
		fractale(n - 1, ux, uy, tx, ty);//3
