using P = pair<double, double>;
vector<P> res;
const double pi = 3.14159265358979323846;
void go(int n, P start, double length, double angle) {
  if (n == 0) res.push_back({start.first + length * cos(angle),
                             start.second + length * sin(angle)});
  else {
    double l = length / 3;
    P v = {l * cos(angle), l * sin(angle)},
      s = {start.first + v.first, start.second + v.second},
      t = {s.first + v.first, s.second + v.second},
      u = {s.first + l * cos(angle + pi / 3), s.second + l * sin(angle + pi / 3)};
    go(n-1, start, l, angle);
    go(n-1, s, l, angle + pi / 3);
    go(n-1, u, l, angle - pi / 3);
    go(n-1, t, l, angle);
  }
}

