// 内分点
Point div_point(Point p1, Point p2, double a, double b) {
  return Point(
    (b * p1.x + a * p2.x) / (a + b),
    (b * p1.y + a * p2.y) / (a + b)
  );
}

// 回転行列
Point rot_point(Point p1, Point p2, double theta) {
  return p1 + Point(
    (p2.x - p1.x) * cos(theta) - (p2.y - p1.y) * sin(theta),
    (p2.x - p1.x) * sin(theta) + (p2.y - p1.y) * cos(theta)
  );
}

