	double sine = sin( 60 * 3.141592653589793 / 180 );

	pt s = { (2*p1.first + p2.first) / 3.0, (2*p1.second + p2.second) / 3.0 };
	pt t = { (p1.first + 2*p2.first) / 3.0, (p1.second + 2*p2.second) / 3.0 };
