  double x2 = cos(d60)*(x3-x1) - sin(d60)*(y3-y1) + x1;
  double y2 = sin(d60)*(x3-x1) + cos(d60)*(y3-y1) + y1;

  koch(lx, ly, x1, y1, n-1);
  koch(x1, y1, x2, y2, n-1);
  koch(x2, y2, x3, y3, n-1);
  koch(x3, y3, rx, ry, n-1);

  return 0;
}

