int getChar(char ch){
    if( ch == 'A' ) return 1;
    else if (ch == 'C') return 2;
    else if (ch == 'G') return 3;
    else if (ch == 'T') return 4;
    else return 0;
}

// 文字列から数値へ変換してkeyを生成する
ll getKey(char str[]){
    ll sum = 0, p = 1;
    rep(i,strlen(str)){
        sum += p*(getChar(str[i]));
        p *= 5;
    }
    return sum;
}

int h1(int key){ return key % M; }
int h2(int key){ return 1 + (key % (M-1)); }

int find(char str[]){
    ll key,i,h;
    key = getKey(str); // 文字列を数値に変換
    for(i = 0;; i++){
        h = (h1(key) + i * h2(key)) % M;
        if(strcmp(H[h],str) == 0) return 1;
        else if (strlen(H[h]) == 0) return 0;
    }
    return 0;
}

int insert(char str[]){
    ll key,i,h;
    key = getKey(str); // 文字列を数値に変換
    for(i = 0;; i++){
        h = (h1(key) + i * h2(key)) % M;
        if(strcmp(H[h],str) == 0) return 1;
        else if (strlen(H[h]) == 0){
            strcpy(H[h], str);
            return 0;   
        }
    }
    return 0;
}

