    // 正三角形の計算めんどいしたかだか6方向なのでハードコードする
    switch(angle){
      case 0: x2 = (sx+dx)/2; y2 = sy + (x1-sx)*RT3/2; break;
      case 1: x2 = sx; y2 = y3; break;
      case 2: x2 = dx; y2 = y1; break;
      case 3: x2 = (sx+dx)/2; y2 = sy + (x1-sx)*RT3/2; break;
      case 4: x2 = sx; y2 = y3; break;
      case 5: x2 = dx; y2 = y1; break;
    }
    koch(dim-1,sx,sy,x1,y1,angle);
    koch(dim-1,x1,y1,x2,y2,(angle+1)%6);
    koch(dim-1,x2,y2,x3,y3,(angle+5)%6);
    koch(dim-1,x3,y3,dx,dy,angle);
  }
}

