void Koch(int n, point A, point B) {
	if (n == 0) {
		cout << A.x << " " << A.y << endl;
		return;
	}
	n--;
	point C, D, E;
	double temp1 = 1.0 / 3.0, temp2 = 2.0 / 3.0;
	C.x = temp2 * A.x + temp1 * B.x;
	C.y = temp2 * A.y + temp1 * B.y;
	E.x = temp1 * A.x + temp2 * B.x;
	E.y = temp1 * A.y + temp2 * B.y;
	// D has six special situation
	if (A.y - B.y < 0.000001 && A.y - B.y > -0.000001) {
		D.x = 1 / 2.0 * (A.x + B.x);
		D.y = sqrt(3) / 6.0 * (B.x - A.x) + A.y;
	} else if (B.y > A.y) {
		D.x = min(A.x, B.x);
		if (A.x < B.x) {
			D.y = temp1 * A.y + temp2 * B.y;
		} else {
			D.y = temp2 * A.y + temp1 * B.y;
		}
	} else {
		D.x = max(A.x, B.x);
		if (A.x > B.x) {
			D.y = temp1 * A.y + temp2 * B.y;
		} else {
			D.y = temp2 * A.y + temp1 * B.y;
		}
	}

	Koch(n, A, C);
	Koch(n, C, D);
	Koch(n, D, E);
	Koch(n, E, B);
}

