class PointS : public Point {
public:
	PointS(Point *p1, Point *p2);
};

PointS::PointS(Point *p1, Point *p2)
{
	x = calc13(p1->x, p2->x);
	y = calc13(p1->y, p2->y);
}

//////
class PointT : public Point {
public:
	PointT(Point *p1, Point *p2);
};

PointT::PointT(Point *p1, Point *p2)
{
	x = calc23(p1->x, p2->x);
	y = calc23(p1->y, p2->y);
}

//////
class PointU : public Point {
public:
	PointU(Point *p1, Point *p2);
};

PointU::PointU(Point *p1, Point *p2)
{
	if (p1->y == p2->y && p1->x < p2->x) {
		x = calc12(p1->x, p2->x);
		y = (p2->x - p1->x) / 2 * tan(M_PI / 6);
	}
	else if (p1->y > p2->y && p1->x < p2->x) {
		x = p2->x;
		y = calc23(p2->y, p1->y);
	}
	else if (p1->y > p2->y && p1->x > p2->x) {
		x = p1->x;
		y = calc13(p2->y, p1->y);
	}
	else if (p1->y == p2->y && p1->x > p2->x) {
		x = calc12(p2->x, p1->x);
		y = (p1->x - p2->x) / 2 * (-tan(M_PI / 6));
	}
	else if (p1->y < p2->y && p1->x > p2->x) {
		x = p2->x;
		y = calc13(p1->y, p2->y);
	}
	else if (p1->y < p2->y && p1->x < p2->x) {
		x = p1->x;
		y = calc23(p1->y, p2->y);
	}
}

