void drawKochCurve(Point *p1, Point *p2, int n, int cnt)
{
	if (cnt >= n) return;

	PointS *ps = new PointS(p1, p2);
	PointU *pu = new PointU(p1, p2);
	PointT *pt = new PointT(p1, p2);
	p1->p_next = ps;
	ps->p_next = pu;
	pu->p_next = pt;
	pt->p_next = p2;

	cnt++;

	drawKochCurve(p1, ps, n, cnt);
	drawKochCurve(ps, pu, n, cnt);
	drawKochCurve(pu, pt, n, cnt);
	drawKochCurve(pt, p2, n, cnt);
}

