const double th = M_PI * 60.0 / 180.0;	// 夹角 
const double cs = cos(th), sn = sin(th);// 弧度 
// http://judge.u-aizu.ac.jp/onlinejudge/description.jsp?id=ALDS1_5_C

typedef struct {double x, y;} P; // point

void Koch(int n, P a, P b)
{
	if (n)
	{
		P s = {0}, t = {0}, u = {0};

		// 计算的通式要写对。 
		s.x = (2.0*a.x + 1.0*b.x) / 3.0; 
		s.y = (2.0*a.y + 1.0*b.y) / 3.0;
		t.x = (1.0*a.x + 2.0*b.x) / 3.0;
		t.y = (1.0*a.y + 2.0*b.y) / 3.0;
		u.x = (t.x - s.x)*cs - (t.y - s.y)*sn + s.x;
		u.y = (t.x - s.x)*sn + (t.y - s.y)*cs + s.y;

		Koch(n-1, a, s);
		printf("%.8f %.8f\n", s.x, s.y);
		Koch(n-1, s, u);
		printf("%.8f %.8f\n", u.x, u.y);
		Koch(n-1, u, t);
		printf("%.8f %.8f\n", t.x, t.y);
		Koch(n-1, t, b);		
	}
}

