#include<vector>
#include<algorithm>
#include<math.h>
using namespace std;

const double PI = 3.1415;

struct Point {
	double x;
	double y;
};

void solve(Point begin, Point end,int depth,vector<Point>& result) {
	if (depth == 0) {
		result.push_back(end);
		return;
	}
	Point p1, p2, p3;
	Point be, eb;
	double len;

	be.x = (end.x - begin.x) / 3.0;
	be.y = (end.y - begin.y) / 3.0;

	eb.x = (begin.x - end.x) / 3.0;
	eb.y = (begin.y - end.y) / 3.0;

	p1 = begin;
	p1.x += be.x;
	p1.y += be.y;

	p3 = end;
	p3.x += eb.x;
	p3.y += eb.y;

	len = sqrt(pow(be.x, 2) + pow(be.y, 2));
	p2.x = cos(60.0 * PI / 180) * len + p1.x;
	p2.y = sin(60.0 * PI / 180) * len + p1.y;

	depth--;
	solve(begin, p1, depth, result);
	solve(p1, p2, depth, result);
	solve(p2, p3, depth, result);
	solve(p3, end, depth, result);
}

int main() {
	vector<Point>result;
	Point begin = { 0,0 };
	Point end = { 100,0 };

	int n;
	cin >> n;

	solve(begin, end, n, result);

	cout << begin.x << " " << begin.y << endl;
	for (int i = 0; i < result.size(); i++) {
		cout << result[i].x << " " << result[i].y << endl;
	}
	return 0;
}

