void koch(double x0, double y0, double x1, double y1, int n) {
	//3等分する点をだす
	double x2 = (2 * x0 + x1) / 3;
	double y2 = (2 * y0 + y1) / 3;
	double x3 = (x0 + 2 * x1) / 3;
	double y3 = (y0 + 2 * y1) / 3;
	//正三角形の残りの頂点を出す(これ面倒...)
	double dx = x3 - x2;
	double dy = y3 - y2;
	double x4 = (x0 + x1) / 2 - dy * sqrt(3) / 2;
	double y4 = (y0 + y1) / 2 + dx * sqrt(3) / 2;
	//座標の描画
	if (n == 0) {
		//cout << x0 << " " << y0 << endl;
		show_vertex(x0, y0);
	} else {
		koch(x0, y0, x2, y2, n-1);
		koch(x2, y2, x4, y4, n-1);
		koch(x4, y4, x3, y3, n-1);
		koch(x3, y3, x1, y1, n-1);
	}
