struct Point {
	double x;
	double y;
};

void printPoint(Point p) {
	printf("%.8lf %.8lf\n", p.x, p.y);
}

void Koch_Curve(int n, Point p1, Point p2) {
	if (n == 0) return;
	Point s, u, t;
	double dx, dy, r, theta;

	if (p1.x > p2.x) {
		dx = p1.x - p2.x;
		s.x = p2.x + dx / 3;
		t.x = p2.x + 2 * dx / 3;
	}
	else {
		dx = p2.x - p1.x;
		s.x = p1.x + dx / 3;
		t.x = p1.x + 2 * dx / 3;
	}

	if (p1.y > p2.y) {
		dy = p1.y - p2.y;
		s.y = p2.y + dy / 3;
		t.y = p2.y + 2 * dy / 3;
	}
	else {
		dy = p2.y - p1.y;
		s.y = p1.y + dy / 3;
		t.y = p1.y + 2 * dy / 3;
	}

	r = sqrt((s.x - t.x) * (s.x - t.x) + (s.y - t.y) * (s.y - t.y));
	theta = atan((t.y - s.y) / (t.x - s.x));

	u.x = s.x + r * cos(theta - asin(sqrt(3) / 2.0));
	u.y = s.y - r * sin(theta - asin(sqrt(3) / 2.0));

	Koch_Curve(n - 1, p1, s);
	printPoint(s);
	Koch_Curve(n - 1, s, u);
	printPoint(u);
	Koch_Curve(n - 1, u, t);
	printPoint(t);
	Koch_Curve(n - 1, t, p2);
}

