void kochCurve(int n, std::pair<double, double> start, std::pair<double, double> end)
{
    if (n == 0)
    {
        std::cout << std::fixed << std::setprecision(5) << end.first   << " " << end.second   << std::endl;
        return;
    }

    std::pair<double, double> base = std::make_pair((end.first - start.first) / 3.0, (end.second - start.second) / 3.0);
    std::pair<double, double> s = std::make_pair(start.first + base.first, start.second + base.second);
    std::pair<double, double> t = std::make_pair(s.first + base.first, s.second + base.second);

    std::pair<double, double> st = std::make_pair(t.first - s.first, t.second - s.second);
    std::pair<double, double> u  = std::make_pair(s.first + st.first * cos(M_PI/3) - st.second * sin(M_PI/3), s.second + st.first * sin(M_PI/3) + st.second * cos(M_PI/3));

    //std::cout << "start:" << start.first << " " << start.second  << " end:" << end.first << " " << end.second << " ";
    //std::cout << "s:" << s.first << " " << s.second  << " u:" << u.first << " " << u.second  << " t:" << t.first << " " << t.second << std::endl;

    kochCurve(n-1, start, s);
    kochCurve(n-1, s, u);
    kochCurve(n-1, u, t);
    kochCurve(n-1, t, end);
}

