struct Point{
  double x;
  double y;
};

double Xcoordinate(Point s,Point t,double ratio){
  return (t.x-s.x)*ratio+s.x;
}

double Middlecoordinate(Point s,Point t,double ratio){
  return (t.x-s.x)*ratio+s.y;
}

double Ycoordinate(Point s,Point t,double ratio){
  if(s.y<=t.y){
    return (t.y-s.y)*ratio+s.y;
  }else{
    return s.y-(s.y-t.y)*ratio;
  }
}


Point knock(int n,Point s,Point t){
  if(n==0){
    return t;
  }
  Point a,b,c;
  a.x=Xcoordinate(s,t,1.0/3.0);
  a.y=Ycoordinate(s,t,1.0/3.0);
  c.x=Xcoordinate(s,t,2.0/3.0);
  c.y=Ycoordinate(s,t,2.0/3.0);
  if(((t.y-s.y)/(t.x-s.x))>0){
    b.x=s.x;
    b.y=c.y;
  }else if(s.y==t.y){
    b.x=Xcoordinate(s,t,1.0/2.0);
    b.y=Middlecoordinate(s,t,(sqrt(3)/6));
  }else{
    b.x=t.x;
    b.y=a.y;
  }

  knock(n-1,s,a);
  std::cout<<std::fixed<<std::setprecision(8)<<a.x<<' '<<a.y<<'\n';
  knock(n-1,a,b);
  std::cout<<std::fixed<<std::setprecision(8)<<b.x<<' '<<b.y<<'\n';
  knock(n-1,b,c);
  std::cout<<std::fixed<<std::setprecision(8)<<c.x<<' '<<c.y<<'\n';
  knock(n-1,c,t);
}

