using namespace std;
int depth;
const double cos_60 = cos(M_PI / 3.0);
const double sin_60 = sin(M_PI / 3.0);
vector<pair<double, double>> endpoints;

inline pair<double, double> midpoint(pair<double, double> origin, pair<double, double> object)
{
	pair<double, double> tmp_pair;
	tmp_pair.first = object.first - origin.first;
	tmp_pair.second = object.second - origin.second;
	return make_pair(origin.first + tmp_pair.first * cos_60 - tmp_pair.second * sin_60, origin.second + tmp_pair.first * sin_60 + tmp_pair.second * cos_60);
}

void koch(pair<double, double> start, pair<double, double> end, int n) //从左往右
{
	if (n == 0){
        endpoints.push_back(start);
        return;
    }
    pair<double, double> p1, p2, p3;
	p1 = make_pair(start.first + (end.first - start.first) / 3.0, start.second + (end.second - start.second) / 3.0);
	p3 = make_pair(start.first + (end.first - start.first) / 3.0 * 2.0, start.second + (end.second - start.second) / 3.0 * 2.0);
	p2 = midpoint(p1, p3);
	if (n == 1)
	{
		endpoints.push_back(start);
		endpoints.push_back(p1);
		endpoints.push_back(p2);
		endpoints.push_back(p3);
		return;
	}
	koch(start, p1, n - 1);
	koch(p1, p2, n - 1);
	koch(p2, p3, n - 1);
	koch(p3, end, n - 1);
	return;
}

