	koch(make_pair(0.0, 0.0), make_pair(100.0, 0.0), depth);
	endpoints.push_back(make_pair(100.0, 0.0));
	for (auto pair : endpoints)
	{
		printf("%lf %lf\n", pair.first, pair.second);
	}
}

