void drawKochCurve(Point *p1, Point *p2, int n, int cnt)
{
	if (cnt >= n) return;

	PointS *ps = new PointS(p1, p2);
	PointU *pu = new PointU(p1, p2);
	PointT *pt = new PointT(p1, p2);
	p1->p_next = ps;
