    valarray<double> s, t, u(2);
    s = (p1 * 2.0 + p2) / 3.0;
    t = (p1 + p2 * 2.0) / 3.0;
    auto vec = (t - s);
    u[0] = std::cos(M_PI / 3) * vec[0] - std::sin(M_PI / 3) * vec[1] + s[0];
