void rec(int level, complex<double> s, complex<double> e) {
	if (level >= n)return;
	complex<double> p1, p2, p3;
	p1 = s + (e - s) / 3.0;
	p3 = s + (e - s) * 2.0 / 3.0;
	p2 = p1 + (p3 - p1)*exp(complex<double>(.0, 60.0 * PI / 180.0));
	rec(level + 1, s, p1);
	printcomp(p1);
	rec(level + 1, p1, p2);
	printcomp(p2);
	rec(level + 1, p2, p3);
	printcomp(p3);
	rec(level + 1, p3, e);
}

