double theta = acos(-1) / 3;

struct Point
{
	double x;
	double y;
};

void Curve(Point *A, int a)
{
	Point pa = A[a], pb = A[a + 4];
	Point v;

	v.x = (pb.x - pa.x) / 3;
	v.y = (pb.y - pa.y) / 3;

	A[a + 1].x = A[a].x + v.x;
	A[a + 1].y = A[a].y + v.y;

	A[a + 2].x = A[a + 1].x + v.x * cos(theta) - v.y * sin(theta);
	A[a + 2].y = A[a + 1].y + v.x * sin(theta) + v.y * cos(theta);

	A[a + 3].x = A[a].x + v.x * 2;
	A[a + 3].y = A[a].y + v.y * 2;
}

void Koch(Point *A, int n)
{
	int len = (1 << (2 * n)) + 1;
	for(int i = len - 1; i > 0; i -= 4)
	{
		A[i] = A[i / 4];
	}

	for(int i = 0; i < len; i += 4)
	{
		Curve(A, i);
	}
}

