void solve(int n, double lx, double ly, double rx, double ry)
{
    if (!n)
    {
        printf("%.8f %.8f\n", rx, ry);
        return;
    }
    double tx = (rx - lx)/3.0, ty = (ry - ly)/3.0;
    double mx = lx+tx + tx * cos(PI/3) - ty * sin(PI/3);
    double my = ly+ty + tx * sin(PI/3) + ty * cos(PI/3);
    solve(n-1, lx, ly, lx+tx, ly+ty);
    solve(n-1, lx+tx, ly+ty, mx, my);
    solve(n-1, mx, my, rx-tx, ry-ty);
    solve(n-1, rx-tx, ry-ty, rx, ry);
}

