	ret[4] = t;
	return ret;
}

vector<vector<float>> Koch(vector<vector<float>>p) {
	int num = p.size(),k=0;
	vector<vector<float>> q;
	vector<vector<float>>K(num + (num - 1) * 3);
	for (int i = 0; i < num - 1; i++) {
		q = minKoch(p[i], p[i + 1]);
		for (int j = 0; j < 4; j++) {
			K[k] = q[j];
			k++;
		}
	}
	K[k] = q[4];
	return K;
}

