const int PREC = 8;
int n;

void koch(int k, double px, double py, double qx, double qy)
{
  if (k == n) {
    cout << fixed << setprecision(PREC) << px << " " << py << endl;
  } else {
    double sx = px + (qx - px) / 3;
    double sy = py + (qy - py) / 3;

    double tx = px + (qx - px) * 2 / 3;
    double ty = py + (qy - py) * 2 / 3;

    double upx = sx - px;
    double upy = sy - py;
    double r = DEG2RAD(60);
    double ux = sx + (upx * cos(r) - upy * sin(r));
    double uy = sy + (upx * sin(r) + upy * cos(r));

    koch(k+1, px, py, sx, sy);
    koch(k+1, sx, sy, ux, uy);
    koch(k+1, ux, uy, tx, ty);
    koch(k+1, tx, ty, qx, qy);
  }
  if (k == 0) {
    cout << fixed << setprecision(PREC) << qx << " " << qy << endl;
  }
}

