using namespace std;

struct Node {
    double x;
    double y;

    Node add(const Node& target)
    {
        return {x + target.x, y + target.y};
    }

    Node dist(const Node& target)
    {
        return {target.x - x, target.y - y};
    }

    void print()
    {
        printf("%.8f %.8f\n", x, y);
    }
};

const double PI = 3.14159265358979;
const double SIN_60 = sin(PI / 3);
const double COS_60 = cos(PI / 3);

void koch_curve(list<Node> nodes, list<Node>::iterator head, list<Node>::iterator tail, int count_down)
{
    if (count_down <= 0) return;

    Node all_diff = head->dist(*tail);
    Node diff = {all_diff.x / 3, all_diff.y / 3};
    Node b_diff;
    b_diff.x = diff.x * COS_60 - diff.y * SIN_60;
    b_diff.y = diff.x * SIN_60 + diff.y * COS_60;

    Node a = head->add(diff);
    Node b = a.add(b_diff);
    Node c = a.add(diff);

    nodes.insert(tail, a);
    nodes.insert(tail, b);
    nodes.insert(tail, c);

    list<Node>::iterator next_head, next_tail;
    next_head = head;
    next_tail = head;
    next_tail++;
    while (next_head != tail){
        koch_curve(nodes, next_head, next_tail, count_down - 1);

        next_head = next_tail++;
    }
}

int main()
{
    int n;

    cin >> n;

    list<Node> nodes{{0.0, 0.0}, {100.0, 0.0}};

    koch_curve(nodes, nodes.begin(), --nodes.end(), n);

    for (Node node : nodes){
        node.print();
    }

    return 0;
}

