		x = x2;
		y = y2 + (y1 - y2) / 3.0 * 2.0;
	}
	Korch(x1, y1, s_x, s_y, n - 1);
	Korch(s_x, s_y, x, y, n - 1);
	Korch(x, y, t_x, t_y, n - 1);
	Korch(t_x, t_y, x2, y2, n - 1);
