using point = pair<double, double>;

point protate90(point v) {
    return point(-v.second, v.first);
}

point pplus(point v1, point v2) {
    return point(v1.first + v2.first, v1.second + v2.second);
}

point pminus(point v1, point v2) {
    return point(v1.first - v2.first, v1.second - v2.second);
}

point pmult(point v, double c) {
    return point(v.first * c, v.second * c);
}

void computeKoch(point p1, point p2, vector<pair<point, point>> &edges) {
    point s, t, u;
    point v = pminus(p2, p1);
    s = pplus(p1, pmult(v, 1.0 / 3.0));
    t = pplus(p1, pmult(v, 2.0 / 3.0));
    u = pplus(p1, pplus(pmult(v, 1.0 / 2.0), protate90(pmult(v, sqrt(3) / 6.0))));
    edges.push_back(pair<point, point>(p1, s));
    edges.push_back(pair<point, point>(s, u));
    edges.push_back(pair<point, point>(u, t));
    edges.push_back(pair<point, point>(t, p2));
}

void koch(vector<pair<point, point>> &edges, int n) {
    int i, j;
    rep(i, n) {
        vector<pair<point, point>> new_edges;
        rep(j, edges.size()) {
            computeKoch(edges[j].first, edges[j].second, new_edges);
        }
        edges = new_edges;
    }
}

