std::vector< std::pair<float,float> > Koch_Curve(std::pair <float,float> Ps, std::pair <float,float> Pe, int N){
	std::vector< std::pair<float,float> > ans;
	ans.push_back(Ps);
	std::vector< std::pair<float,float> > buff = Koch_Curve(Ps,Pe,N,0);
	ans.insert(ans.end(),buff.begin(),buff.end());
	ans.push_back(Pe);
	return ans;
}

std::vector< std::pair<float,float> > Koch_Curve(std::pair <float,float> Ps, std::pair <float,float> Pe, int N, int n){
	double dx = Pe.first - Ps.first;
	double dy = Pe.second - Pe.second;
	std::pair<float,float> mid_0,mid_1,top;
	std::vector< std::pair<float,float> > buff,ans;

	mid_0 = std::make_pair(Ps.first+dx*1.0/3.0,Ps.second+dy*1.0/3.0);
	mid_1 = std::make_pair(Ps.first+dx*2.0/3.0,Ps.second+dy*2.0/3.0);

	if(n<N){
		ans = Koch_Curve(Ps,mid_0,N,n+1);
		ans.push_back(mid_0);

		float angle = 60.0*DEG2EAD;
		top = std::make_pair(Ps.first+dx*cos(angle)-dy*sin(angle),Ps.second+dx*sin(angle)+dy*cos(angle));

		buff = Koch_Curve(mid_0,top,N,n+1);
		ans.insert(ans.end(),buff.begin(),buff.end());

		ans.push_back(top);

		buff = Koch_Curve(top,mid_1,N,n+1);
		ans.insert(ans.end(),buff.begin(),buff.end());

		ans.push_back(mid_1);

		buff = Koch_Curve(mid_1,Pe,N,n+1);
		ans.insert(ans.end(),buff.begin(),buff.end());	
	}
	return ans;
}

