template <class T>
class Vector2 {
 public:
  T x;
  T y;

  Vector2(T init_x, T init_y) : x(init_x), y(init_y){};

  Vector2 &operator+=(const Vector2 &B) {
    x += B.x;
    y += B.y;
    return (*this);
  }

  Vector2 &operator-=(const Vector2 &B) {
    x -= B.x;
    y -= B.y;
    return (*this);
  }

  Vector2 &operator*=(const T &value) {
    x *= value;
    y *= value;
    return (*this);
  }

  Vector2 &operator/=(const T &value) {
    x /= value;
    y /= value;
    return (*this);
  }

  Vector2 operator+(const Vector2 &B) const { return Vector2(*this) += B; }
  Vector2 operator-(const Vector2 &B) const { return Vector2(*this) -= B; }

  Vector2 operator+(const T &value) const {
    return Vector2(x + value, y + value);
  }
  Vector2 operator-(const T &value) const {
    return Vector2(x - value, y - value);
  }

  Vector2 operator*(const T &value) const { return Vector2(*this) *= value; }
  Vector2 operator/(const T &value) const { return Vector2(*this) /= value; }

  void rotate(const double &angle) {
    T temp_x = x * cos(angle) - y * sin(angle);
    y = x * sin(angle) + y * cos(angle);
    x = temp_x;
  }
};

template <class T>
const Vector2<T> operator+(const T &value, const Vector2<T> &A) {
  return Vector2<T>(value + A.x, value + A.y);
}

template <class T>
const Vector2<T> operator-(const T &value, const Vector2<T> &A) {
  return Vector2<T>(value - A.x, value - A.y);
}

template <class T>
const Vector2<T> operator*(const T &value, const Vector2<T> &A) {
  return Vector2<T>(value * A.x, value * A.y);
}

template <class T>
const Vector2<T> operator/(const T &value, const Vector2<T> &A) {
  return Vector2<T>(value / A.x, value / A.y);
}

double lerp(const double &a, const double &b, const double &f) {
  return (a * (1.0 - f)) + (b * f);
}

Vector2<double> lerp(const Vector2<double> &a, const Vector2<double> &b,
                     const double &f) {
  double x = lerp(a.x, b.x, f);
  double y = lerp(a.y, b.y, f);
  return Vector2<double>(x, y);
}

