void KochCurve(point p1, point p2, int depth, int limit)
{
	point s, t, u;

	depth++;

	s.x = p1.x + (p2.x - p1.x) / 3;
	s.y = p1.y + (p2.y - p1.y) / 3;

	t.x = p1.x + (p2.x - p1.x) * 2 / 3;
	t.y = p1.y + (p2.y - p1.y) * 2 / 3;

	u.x = s.x + (t.x - s.x) / 2 - (t.y - s.y) * sqrtf(3) / 2;
	u.y = s.y + (t.x - s.x) * sqrtf(3) / 2 + (t.y - s.y) / 2;

	if (depth <= limit) {
		KochCurve(p1, s, depth, limit);
		KochCurve(s, u, depth, limit);
		KochCurve(u, t, depth, limit);
		KochCurve(t, p2, depth, limit);
	}
	else print_point(p2);
}

