};

double point::sin60 = std::sin(M_PI*60.0/180.0);
double point::cos60 = std::cos(M_PI*60.0/180.0);

point point::rotate_m60() const {
  return point(x_*cos60 - y_*sin60,
               x_*sin60 + y_*cos60);
}

point operator +(const point& p, const point& q) { return point(p.x_+q.x_, p.y_+q.y_); }
point operator -(const point& p, const point& q) { return point(p.x_-q.x_, p.y_-q.y_); }
point operator *(const double m, const point& p) { return point(m*p.x_, m*p.y_); }
point operator /(const point& p, const double d) { return point(p.x_/d, p.y_/d); }

