#include <cstdio>
#include <cmath>

#define PI_ 60*M_PI/180

struct P{
  double x,y;

  P (double x = 0 ,double y = 0) : x(x), y(y) {}

  P operator + (P p){
    return P(x + p.x , y + p.y);
  }

  P operator - (P p){
    return P(x - p.x , y - p.y);
  }

  P operator * (double k){
    return P(x * k , y * k);
  }

  P operator / (double k){
    return P(x / k , y / k);
  }
};

void solve(P p1,P p2,int end){
  if(end == 0){
    printf("%.8f %.8f\n" ,fabs(p1.x) ,fabs(p1.y));
    return;
  }

  P c = (p2 - p1) / 3, d = c * 2;
  P s = p1 + c , t = p1 + d;
  P u;

  u.x = s.x + (t.x - s.x) * cos(PI_) - (t.y - s.y) * sin(PI_);
  u.y = s.y + (t.x - s.x) * sin(PI_) + (t.y - s.y) * cos(PI_);

  solve(p1,s,end-1);
  solve(s,u,end-1);
  solve(u,t,end-1);
  solve(t,p2,end-1);

}

