void kochCurve(Point p1, Point p2, int n) {
	if(n == 0) {
		printf("%f %f\n", p1.x, p1.y);
		return;
	}
	double dx = p2.x - p1.x;
	double dy = p2.y - p1.y;
	Point s = {p1.x + dx/3, p1.y + dy/3};
