DP subVec(DP a,DP b){
	DP ans;
	ans.first = a.first-b.first;
	ans.second = a.second-b.second;
	return ans; 
}
DP addVec(DP a,DP b){
	DP ans;
	ans.first = a.first+b.first;
	ans.second = a.second+b.second;
	return ans; 
}
DP devVec(DP a,int x){
	DP ans;
	ans.first = a.first / (double)x;
	ans.second = a.second / (double)x;
	return ans;
}
DP rot60deg(DP x){
	DP ans;
	ans.first = x.first*cos(M_PI/3.0)-x.second*sin(M_PI/3.0);
	ans.second = x.first*sin(M_PI/3.0)+x.second*cos(M_PI/3.0);
	return ans;
}



