		FOR(j,1,point.size()){
			next = point[j];
			DP vec = subVec(next,now);
			vec = devVec(vec,3);
			nextpoint.push_back(addVec(now,vec));
			nextpoint.push_back(addVec(addVec(now,vec),rot60deg(vec)));
			nextpoint.push_back(addVec(now,addVec(vec,vec)));
			nextpoint.push_back(next);
			now = next;
		}
		point = nextpoint;
	}
