using namespace std;

double th = M_PI * 60.0 / 180.0; //度からラジアン

struct Point {
    double x;
    double y;
};

void printP(Point p){
    cout << fixed << setprecision(8) << p.x << " ";
    cout << fixed << setprecision(8) << p.y << endl;
}

void koch(int n, Point p1, Point p2){
    /*第一引数：再帰の深さ
      第二引数：線分の始点
      第三引数：線分の終点*/

    if(n == 0) return;

    Point s, t, u;

    //線分p1p2を三等分するような点s,tの座標と正三角形のもう一つの頂点uの座標を求める
    s.x = (2.0 * p1.x + 1.0 * p2.x) / 3.0;
    s.y = (2.0 * p1.y + 1.0 * p2.y) / 3.0;
    t.x = (1.0 * p1.x + 2.0 * p2.x) / 3.0;
    t.y = (1.0 * p1.y + 2.0 * p2.y) / 3.0;
    u.x = (t.x - s.x) * cos(th) - (t.y - s.y) * sin(th) + s.x;
    u.y = (t.x - s.x) * sin(th) + (t.y - s.y) * cos(th) + s.y;

    koch(n - 1, p1, s);
    printP(s);
    koch(n - 1, s, u);
    printP(u);
    koch(n - 1, u, t);
    printP(t);
    koch(n - 1, t, p2);
}

int main(){
    int n; //再帰の深さ
    cin >> n;

    Point p1, p2;
    p1.x = 0;
    p1.y = 0;
    p2.x = 100;
    p2.y = 0;

    printP(p1);
    koch(n, p1, p2);
    printP(p2);

    return 0;
}

