void koch(int d, Point p1, Point p2) {
    double th = M_PI * 60.0 / 180.0;

    if (d == 0) return;
    Point p12 = p2 - p1;
    Point s = p1 + p12 / 3;
    Point t = p1 + p12 * 2 / 3;
    Point st = t - s;
    Point u = s + Point(st.x * cos(th) - st.y * sin(th), st.x * sin(th) + st.y * cos(th));
    koch(d-1, p1, s);
    s.print();
    koch(d-1, s, u);
    u.print();
    koch(d-1, u, t);
    t.print();
    koch(d-1, t, p2);
}

