void KochCurve(int n, Comp_d p1, Comp_d p2) {
	if (n == 0) { return; }
	Comp_d s = p1 + (p2 - p1) / 3.;
	Comp_d t = p1 + 2.*(p2 - p1) / 3.;
	Comp_d u = s + (t - s)*std::polar(1., M_PI / 3.);
	KochCurve(n - 1, p1, s);
	std::cout << std::fixed << std::setprecision(8) << s.real() << "," << s.imag() << std::endl;;
