      this -> y = y;
  }
  CD2D operator -(CD2D *obj){
      CD2D  return_CD2D  (
          (this -> x) - (obj -> x),
          (this -> y) - (obj -> y)
      );
      return return_CD2D;
  }
  void print(){printf("%lf %lf\n",this -> x,this -> y);}


};

void AskKoch(int n,CD2D p1,CD2D p2){
    CD2D s(0,0),t (0,0),u (0,0);
    if(n <= 0) return ;
    s.x = (2*p1.x + 1*p2.x) / (1 + 2);
    s.y = (2*p1.y + 1*p2.y) / (1 + 2);
    u.x = (1*p1.x + 2*p2.x) / (2 + 1);
    u.y = (1*p1.y + 2*p2.y) / (2 + 1);
    t.x = (u.x - s.x)*cos(M_PI/3) - (u.y - s.y)*sin(M_PI/3) + (s.x);
    t.y = (u.x - s.x)*sin(M_PI/3) + (u.y - s.y)*cos(M_PI/3) + (s.y);
    AskKoch(n-1,p1,s);
    s.print();
    AskKoch(n-1,s,t);
    t.print();
    AskKoch(n-1,t,u);
    u.print();
    AskKoch(n-1,u,p2);
}

