void Koch(double p1x, double p1y, double p2x, double p2y, int n)
{
	if (n <= 0)return;
	double sx = (2 * p1x + 1 * p2x) / 3;
	double sy = (2 * p1y + 1 * p2y) / 3;
	double tx = (1 * p1x + 2 * p2x) / 3;
	double ty = (1 * p1y + 2 * p2y) / 3;
	double ux = (tx - sx) * cos(3.1415926 * 60.0 / 180.0) - (ty - sy) * sin(3.1415926 * 60.0 / 180.0) + sx;
	double uy = (tx - sx) * sin(3.1415926 * 60.0 / 180.0) + (ty - sy) * cos(3.1415926 * 60.0 / 180.0) + sy;
