#define csb ((sqrt(3))/2.0)

struct zb{
	double x;
	double y;
};

void cpt(double x,double y,double *px,double *py){
	double x1 = x/2.0 - y*csb;
	double y1 = x*csb + y/2.0;
	*px=x1;
	*py=y1;
}

void pr(zb s){
	printf("%.8f",s.x);
	printf(" %.8f\n",s.y);
}

void koch(int d,zb p1,zb p2){
	zb s,u,t;
	if(d==0) return;
	s.x=(p2.x-p1.x)/3.0+p1.x;
	t.x=(p2.x-p1.x)/3.0*2.0+p1.x;
	s.y=(p2.y-p1.y)/3.0+p1.y;
	t.y=(p2.y-p1.y)/3.0*2.0+p1.y;
	cpt((t.x-(s.x)),(t.y-(s.y)),&(u.x),&(u.y));
	u.x+=s.x;
	u.y+=s.y;
	koch(d-1,p1,s);
	pr(s);koch(d-1,s,u);
	pr(u);koch(d-1,u,t);
	pr(t);koch(d-1,t,p2);
}

int main(){
	zb p1;
	zb p2;
	p1.x=0;p1.y=0;
	p2.x=100.0;p2.y=0;
	int d;
	scanf("%d",&d);
	pr(p1);
	koch(d,p1,p2);
	pr(p2);
}

#include<stdio.h>
#include<math.h>
#define pi 3.14159265359

void koch(double p1x, double p1y, double p2x, double p2y, int n) {

	if (n == 0) return;

	double sx, sy, ux, uy, tx, ty, lx, ly;

	if (p1x > p2x)
	{
		lx = p1x - p2x;
		tx = p2x + lx/3.0;
		sx = p2x + 2.0*lx/3.0;
		if (p1y > p2y)
		{
			ly = p1y - p2y;
			ty = p2y + ly/3.0;
			sy = p2y + 2.0*ly/3.0;
			ux = (sx - tx)*cos(pi/3.0) - (sy - ty)*sin(pi/3.0) + sx;
			uy = (sx - tx)*sin(pi/3.0) - (sy - ty)*cos(pi/3.0) + sy;
		}
		else
		{
			ly = p2y - p1y;
			sy = p1y + ly/3.0;
			ty = p1y + 2.0*ly/3.0;
			ux = (sx - tx)*cos(pi/3.0) - (ty - sy)*sin(pi/3.0) + sx;
			uy = (sx - tx)*sin(pi/3.0) - (ty - sy)*cos(pi/3.0) + sy;
		}
	}
	else
	{
		lx = p2x - p1x;
		sx = p1x + lx/3.0;
		tx = p1x + 2.0*lx/3.0;
		if (p1y > p2y)
		{
			ly = p1y - p2y;
			ty = p2y + ly/3.0;
			sy = p2y + 2.0*ly/3.0;
			ux = (tx - sx)*cos(pi/3.0) - (sy - ty)*sin(pi/3.0) + sx;
			uy = (tx - sx)*sin(pi/3.0) - (sy - ty)*cos(pi/3.0) + sy;
		}
		else
		{
			ly = p2y - p1y;
			sy = p1y + ly/3.0;
			ty = p1y + 2.0*ly/3.0;
			ux = (tx - sx)*cos(pi/3.0) - (ty - sy)*sin(pi/3.0) + sx;
			uy = (tx - sx)*sin(pi/3.0) - (ty - sy)*cos(pi/3.0) + sy;
		}
	}
	koch(p1x, p1y, sx, sy, n - 1);
	printf("%.8f %.8f\n", sx, sy);
	koch(sx, sy, ux, uy, n - 1);
	printf("%.8f %.8f\n", ux, uy);
	koch(ux, uy, tx, ty, n - 1);
	printf("%.8f %.8f\n", tx, ty);
	koch(tx, ty, p2x, p2y, n - 1);
}

int main(void) {
	double p1x = 0.0, p1y = 0.0, p2x = 100.0, p2y = 0.0;
	int n;
	scanf("%d", &n);

	printf("%.8f %.8f\n", p1x, p1y);
	koch(p1x, p1y, p2x, p2y, n);
	printf("%.8f %.8f\n", p2x, p2y);

