vector<double> rotate(int x0, int y0, int x1,int y1, int a){
    double x = cos(a)*(x1-x0)+sin(a)*(y1-y0) + x0;
    double y = -sin(a)*(x1-x0)+cos(a)*(y1-y0) + y0;
    vector<double> r(2);
    r[0] = x;
    r[1] = y;
    return r;
}
