vector<vector<double> > koch(int x0, int y0, int x1,int y1, int n){
    vector<vector<double> > t(5, vector<double>(2));
    t[0][0] = x0;
    t[0][1] = y0;
    t[1][0] = x0+(x1-x0)/3;
    t[1][1] = y0+(y1-y0)/3;
    t[2][0] = x0+rotate(x0+(x1-x0)/3,y0+(y1-y0)/3,(x0+(x1-x0))*2/3,(y0+(y1-y0))*2/3,-M_PI/3)[0];
    t[2][1] = y0+rotate(x0+(x1-x0)/3,y0+(y1-y0)/3,(x0+(x1-x0))*2/3,(y0+(y1-y0))*2/3,-M_PI/3)[1];
    t[3][0] = (x0+(x1-x0))*2/3;
    t[3][1] = (y0+(y1-y0))*2/3;
    t[4][0] = x1;
    t[4][1] = y1;
    if(n==1){
        return t;
    }else{
        vector<vector<double> > ta(0);
        for(int i = 0; i < 4; i++){
            vector<vector<double> > tb;
            tb = koch(t[i][0],t[i][1],t[i+1][0],t[i+1][1],n-1);
            ta.insert(ta.end(),tb.begin(),tb.end());
            ta.pop_back();
        }
        ta.insert(ta.end(),t.end(),t.end());
        return ta;
    }
}

