const double def = 60.0 * 2* M_PI / 360.0;


int kohho( int n, pair<double, double> start, pair<double, double> end ){

  pair<double, double>  s, u, t;

  if( n == 0  ) return 0;

  double diffx = end.first - start.first;
  double diffy = end.second - start.second;

  s.first = ( diffx / 3.0) +  start.first;
  s.second = ( diffy / 3.0) +  start.second;
  t.first = ( diffx * 2.0 / 3.0) +  start.first;
  t.second = ( diffy * 2.0 / 3.0) +  start.second;
  u.first = cos(def) * ( diffx / 3.0) - sin(def) * ( diffy / 3.0) + s.first;
  u.second = sin(def) * ( diffx / 3.0) + cos(def) * ( diffy / 3.0) + s.second;

  kohho( n-1, start, s );

  printf("%.8f %.8f\n", s.first, s.second );

  kohho( n-1, s, u );

  printf("%.8f %.8f\n", u.first, u.second );

  kohho( n-1, u, t );

  printf("%.8f %.8f\n", t.first, t.second );

  kohho( n-1, t, end );

  return 0;
}

int main(){

  int n;
  pair<double, double> start, end;

  start.first = 0.0;
  start.second = 0.0;
  end.first = 100.0;
  end.second = 0.0;

  cin >> n;

  printf("%.8f %.8f\n", start.first, start.second );

  kohho( n, start, end );

  printf("%.8f %.8f\n", end.first, end.second );

  return 0;

}
