void solve(double px, double py, double qx, double qy, int n) {
  if (n == 0) return;

  double sx, sy, tx, ty, ux, uy;
  sx = px + (qx-px)/3; sy = py + (qy-py)/3;
  tx = px + 2*((qx-px)/3); ty = py + 2*((qy-py)/3);

  ux = (tx-sx)*cos(M_PI/3) - (ty-sy)*sin(M_PI/3) + sx;
  uy = (tx-sx)*sin(M_PI/3) + (ty-sy)*cos(M_PI/3) + sy;

  solve(px, py, sx, sy, n-1);
  cout << sx << " " << sy << endl;
  solve(sx, sy, ux, uy, n-1);
  cout << ux << " " << uy << endl;
  solve(ux, uy, tx, ty, n-1);
  cout << tx << " " << ty << endl;
  solve(tx, ty, qx, qy, n-1);
}

