struct Point{
    double x, y;
    Point(): x(0), y(0){};
    Point(double X, double Y): x(X), y(Y){};
};


void koch(int n, Point s, Point g){
    if(!n) return;
    double angle = M_PI * 60.0 / 180;
    // s -> p -> q -> r -> g
    Point p, q, r;
    p.x = (2*s.x + g.x) / 3;
    p.y = (2*s.y + g.y) / 3;
    r.x = (s.x + 2*g.x) / 3;
    r.y = (s.y + 2*g.y) / 3;
    q.x = (r.x - p.x)*cos(angle) - (r.y - p.y)*sin(angle) + p.x;
    q.y = (r.x - p.x)*sin(angle) + (r.y - p.y)*cos(angle) + p.y;

    koch(n-1, s, p);
    cout << fixed << setprecision(8) << p.x << " " << p.y << "\n";
    koch(n-1, p, q);
    cout << fixed << setprecision(8) << q.x << " " << q.y << "\n";
    koch(n-1, q, r);
    cout << fixed << setprecision(8) << r.x << " " << r.y << "\n";
    koch(n-1, r, g);
    return;
}

