    Point a(0, 0), b(100, 0);
    int n; cin >> n;
    cout << fixed << setprecision(8) << a.x << " " << a.y << "\n";
    koch(n, a, b);
    cout << fixed << setprecision(8) << b.x << " " << b.y << "\n";
    return 0;
}

