    kochCurve(make_pair(0., 0.), make_pair(100., 0.), n, koch);
    koch.push_back(make_pair(100., 0.));

    for (auto e : koch)
    {
        cout << fixed << setprecision(10) << e.first
             << " " << fixed << setprecision(10) << e.second << endl;
    }
    return 0;
}

