    s[1] = (2 * p1[1] + 1 * p2[1]) / 3;
    //tのx座標、y座標を計算する
    t[0] = (1 * p1[0] + 2 * p2[0]) / 3;
    t[1] = (1 * p1[1] + 2 * p2[1]) / 3;
    //uのx座標、y座標を計算する
    u[0] = (t[0] - s[0]) * cos(pi/3) - (t[1] - s[1]) * sin(pi/3) + s[0];
    u[1] = (t[0] - s[0]) * sin(pi/3) + (t[1] - s[1]) * cos(pi/3) + s[1];

