void koch(int depth, double x1, double x2, double y1, double y2){
  double si60 = sqrt(3) / 2.0;
  double co60 = 0.5;

  double sx = (x1 * 2.0 + x2) / 3.0;
  double sy = (y1 * 2.0 + y2) / 3.0;
  double tx = (x1 + x2 * 2.0) / 3.0;
  double ty = (y1 + y2 * 2.0) / 3.0;

  double vx = tx-sx;
  double vy = ty-sy;

  double ux = sx + co60*vx - si60*vy;
  double uy = sy + si60*vx + co60*vy;

  if(depth == n){
    printf("%.8f %.8f\n", sx, sy);
