    printf("%.8f %.8f\n", tx, ty);
    return;
  }
  koch(depth + 1, x1, sx, y1, sy);
  koch(depth + 1, sy, ux, sy, uy);
  koch(depth + 1, ux, tx, uy, ty);
  koch(depth + 1, tx, x2, ty, y2);
}

