#define PI 3.14159265359
using namespace std;

void koch(vector<vector<pair<double, double>>> &vertex_point, int N, int depth) {

	if (depth > N)return;
	vertex_point[depth].push_back(make_pair(0, 0));
	for (int i = 0; i < vertex_point[depth - 1].size() - 1; ++i) {
		double p1x = vertex_point[depth - 1][i].first;
		double p1y = vertex_point[depth - 1][i].second;
		double p5x = vertex_point[depth - 1][i + 1].first;
		double p5y = vertex_point[depth - 1][i + 1].second;

		double p2x = p1x + (p5x - p1x) / 3.0;
		double p2y = p1y + (p5y - p1y) / 3.0;
		double p4x = p1x + 2.0 * (p5x - p1x) / 3.0;
		double p4y = p1y + 2.0 * (p5y - p1y) / 3.0;

		double length = sqrt(pow(p4x - p2x, 2) + pow(p4y - p2y, 2));
		double theta = atan2(p4y - p2y, p4x - p2x) + PI / 3.0;

		double p3x = p2x + length * cos(theta), p3y = p2y + length * sin(theta);


		vertex_point[depth][vertex_point[depth].size() - 1] = make_pair(p1x, p1y);
		vertex_point[depth].push_back(make_pair(p2x, p2y));
		vertex_point[depth].push_back(make_pair(p3x, p3y));
		vertex_point[depth].push_back(make_pair(p4x, p4y));
		vertex_point[depth].push_back(make_pair(p5x, p5y));
	}
	////
	koch(vertex_point, N, depth+1);
	return;
}

int main() {
	int N;
	cin >> N;
	vector<vector<pair<double, double>>> vertex_point(7);

	vertex_point[0].push_back(make_pair(0, 0));
	vertex_point[0].push_back(make_pair(100, 0));

	koch(vertex_point, N, 1);

	for (int j = 0; j < vertex_point[N].size(); ++j) {
		printf("%lf %lf\n", vertex_point[N][j].first, vertex_point[N][j].second);
	}
	return 0;
}

