struct P {
	double x, y;
	P() :x(0), y(0) {}
	P(double _x, double _y) :x(_x), y(_y) {}

	P operator+(P p) { return { x + p.x,y + p.y }; }
	P operator-(P p) { return { x - p.x,y - p.y }; }
	P operator*(P p) { return { x * p.x,y * p.y }; }
	P operator/(P p) { return { x / p.x,y / p.y }; }
	P operator*(double d) { return { x * d,y * d }; }
	P operator/(double d) { return { x / d,y / d }; }
	double dist(P p) { return hypot(x - p.x, y - p.y); }
};

vector<P> p;

void solve() {
	vector<P> p2; p2.pb(p[0]);
	rep(i, sz(p) - 1) {
		P P1 = p[i], P2 = p[i + 1];
		P P1_, P2_, P3_;
		double dist = P1.dist(P2);
		P1_ = P1 + (P2 - P1) / 3;
		P3_ = P1 + (P2 - P1) / 3 * 2;

		if (P1.y == P2.y && P1.x < P2.x) {
			P2_.x = P1.x + dist / 2;
			P2_.y = P2.y + dist / 6 * sqrt(3);
		}
		else if (P1.y == P2.y && P1.x > P2.x) {
			P2_.x = P1.x - dist / 2;
			P2_.y = P2.y - dist / 6 * sqrt(3);
		}
		else {
			bool FlagX = P1.x < P2.x, FlagY = P1.y < P2.y;
			if (FlagX && FlagY)P2_ = { P1.x,P3_.y };
			else if (FlagX && !FlagY)P2_ = { P2.x,P1_.y };
			else if (!FlagX && FlagY)P2_ = { P2.x,P1_.y };
			else if (!FlagX && !FlagY)P2_ = { P1.x,P3_.y };
		}

		p2.pb(P1_); p2.pb(P2_); p2.pb(P3_); p2.pb(P2);
	}
	p = p2;
}

int main() {
	p.pb({ 0,0 });
	p.pb({ 100,0 });
	int n = ini;
	rep(i, n)solve();
	for (auto pp : p) {
		out, pp.x, pp.y, out;
	}
}

