	pair<double,double> a,b,c;

	a.first=(x[s]*2+x[g])/3;//s寄り
	a.second=(y[s]*2+y[g])/3;
	b.first=(x[s]+x[g]*2)/3;//g寄り
	b.second=(y[s]+y[g]*2)/3;
	double xx=x[g]-x[s],yy=y[g]-y[s];
	double dis=sqrt(xx*xx+yy*yy);
	if(yy==0){
		c.first=(x[s]+x[g])/2;
		c.second=(sqrt(3)*dis/3)/2+y[s];
	}
	else if(xx>=0){
		c.first=x[s];
		if(yy>0)	c.second=b.second;
		else 		c.second=a.second;
	}
	else{
		c.first=x[g];
		if(yy>0)	c.second=b.second;
		else 		c.second=a.second;
	}
	vector<double>::iterator ix=x.begin(),iy=y.begin();
	for(int i=0;i!=g;i++){
		ix++;	iy++;
	}
	ix=x.insert(ix,b.first);	ix=x.insert(ix,c.first);	x.insert(ix,a.first);
	iy=y.insert(iy,b.second);	iy=y.insert(iy,c.second);	y.insert(iy,a.second);
}

