float seisankakux(float x0,float x1,float y0,float y1){
  float vx,vy,x3;
  vx = (x1-x0)/3;
  vy = (y1-y0)/3;
  x3 = vx * 0.5 + vy * -1 * sqrt(3)/2 + x0 + vx;
  return x3;
}
float seisankakuy(float x0,float x1,float y0,float y1){
  float vx,vy,y3;
  vx = (x1-x0)/3;
  vy = (y1-y0)/3;
  y3 = vx * sqrt(3)/2 + vy * 0.5 + y0 + vy;
  return y3;
}

