        double x = (2*a.x + b.x)/3;
        double y = (2*a.y + b.y)/3;
        return {x,y};
    }else{
        double x = (a.x + 2*b.x)/3;
        double y = (a.y + 2*b.y)/3;
        return {x,y};
    }
}

vec2 tri(vec2& a,vec2& b){
    double dx = b.x - a.x;
    double dy = b.y - a.y;

    double nx = dx*cos(PI/3) - dy * sin(PI/3) + a.x;
    double ny = dx*sin(PI/3) + dy * cos(PI/3) + a.y;

    return {nx,ny};

}


