using namespace std;

class Vertex {
  double x;
  double y;

public:
  Vertex() : x(0.0), y(0.0) {};
  Vertex(double _X, double _Y) : x(_X), y(_Y) {};
  void setVertex(double _X, double _Y) { x = _X; y = _Y; }
  void getVertex() { printf("%.8f %.8f\n", x, y); }
  double getX() { return x; }
  double getY() { return y; }

  friend class Graph;
};

class Graph {
  list<Vertex> v_list;
  int count;

public:
  Graph(int c);
  void Koch_Curve() { koch_curve(*v_list.begin(), *--v_list.end()); }
  void koch_curve(Vertex v1, Vertex v2);
  void PrintList();
};

Graph::Graph(int c) {
  count = c;
  v_list.push_back(Vertex(0.0, 0.0));
  v_list.push_back(Vertex(100.0, 0.0));
}

void Graph::koch_curve(Vertex v1, Vertex v2) {
  static int c = 0;
  if(c == count) return;
  double pi = M_PI;

  Vertex s(v1.getX()+(v2.getX()-v1.getX())/3, v1.getY()+(v2.getY()-v1.getY())/3);
  Vertex t(v2.getX()-(v2.getX()-v1.getX())/3, v2.getY()-(v2.getY()-v1.getY())/3);
  Vertex u;
  if(s.getY() == 0.0) u.setVertex((s.getX()-v1.getX())*cos(pi/3)+s.getX(), (s.getX()-v1.getX())*sin(pi/3));
  else if(v1.getY() < v2.getY()) u.setVertex(v1.getX(), t.getY());
  else u.setVertex(v2.getX(), s.getY());

  list<Vertex>::iterator itr;
  for(itr = v_list.begin(); itr != v_list.end(); itr++)
    if(itr->getX() == v2.getX() && itr->getY() == v2.getY()) break;

  itr = v_list.insert(itr, s); itr++;
  itr = v_list.insert(itr, u); itr++;
  itr = v_list.insert(itr, t);

  int _c = ++c;
  koch_curve(v1, s);
  c = _c;
  koch_curve(s, u);
  c = _c;
  koch_curve(u, t);
  c = _c;
  koch_curve(t, v2);

  return;
}

void Graph::PrintList() {
  list<Vertex>::iterator itr;
  for(itr = v_list.begin(); itr != v_list.end(); itr++)
    itr->getVertex();
}

int main() {
  int N;
  cin >> N;

  Graph g(N);
  g.Koch_Curve();
  g.PrintList();

  return 0;
}

