Point middle(Point p1, Point p2) {
  Point p(p1.x, p1.y);
  double theta = M_PI/3;
  p.x += cos(theta)*(p2.x-p1.x)-sin(theta)*(p2.y-p1.y);
  p.y += sin(theta)*(p2.x-p1.x)+cos(theta)*(p2.y-p1.y);
  return p; 
}

Point left(Point p1, Point p2) {
  Point p(p1.x, p1.y);
  p.x += (p2.x - p1.x)/3;
  p.y += (p2.y - p1.y)/3;
  return p;
}

Point right(Point p1, Point p2) {
  Point p(p1.x, p1.y);
  p.x += (p2.x - p1.x)*2/3;
  p.y += (p2.y - p1.y)*2/3;
  return p;
}

void Print(Point p) {
  cout << fixed << p.x << " " << p.y << endl;
}

