Point Tru(Point A, Point B) {
    Point Res;
    Res.x = A.x - B.x;
    Res.y = A.y - B.y;
    return Res;
}
Point Cong(Point A, Point B) {
    Point Res;
    Res.x = A.x + B.x;
    Res.y = A.y + B.y;
    return Res;
}
Point TinhTien(Point A, double k) {
    Point Res;
    Res.x = A.x * k;
    Res.y = A.y * k;
    return Res;
}
double Dist(Point A, Point B) {
    double x = A.x - B.x;
    double y = A.y - B.y;
    return sqrt(x * x + y * y);
}
void Print(Point A) {
    cout << fixed << setprecision(10) << A.x << " " << A.y << '\n';
}
Point DinhGiua(Point A, Point B) {
    Point AB = Tru(B, A);
    Point nAB = Point(0.0 - AB.y, AB.x);
    Point MedianAB = Point((A.x + B.x) / 2.0, (A.y + B.y) / 2.0);
    double D = Dist(A, B);
    D = D * sqrt(3.0) / 2.0;
    double K = (D * D) / (nAB.x * nAB.x + nAB.y * nAB.y);
    K = sqrt(K);
    return Cong(MedianAB, TinhTien(nAB, K));
}
void Get(Point A, Point B, int n) {
    if (n == 0) {
        Print(A);
        return;
    }
    Point AB = Tru(B, A);
    Point S = Cong(A, TinhTien(AB, 1.0 / 3.0));
    Point T = Cong(A, TinhTien(AB, 2.0 / 3.0));
    Point U = DinhGiua(S, T);
    Get(A, S, n - 1);
    Get(S, U, n - 1);
    Get(U, T, n - 1);
    Get(T, B, n - 1);
}
