	}

	double lx;
	double ly;
	lx = p2.x - p1.x;
	ly = p2.y - p1.y;
	Point s(p1.x + lx / 3, p1.y + ly / 3);
	Point t(p1.x+lx/3*2,p1.y+ly/3*2);
	Point u;
	if (p1.y == p2.y) {
		u.setPoint(p1.x + lx / 2, (lx / 6 )* ROOT3);
	}
	else if (lx*ly>0) {
		u.setPoint(p1.x, p1.y + (ly / 3) * 2);
	}
	else if (lx*ly < 0) {
		u.setPoint(p2.x,p1.y+(ly/3));
	}

	kochCurve(n - 1, p1, s);
	kochCurve(n - 1, s, u);
	kochCurve(n - 1, u, t);
	kochCurve(n - 1, t, p2);

}


