	dot A(0,0);
	dot B(100,0);

	cin >>n;

	if(n == 0){
		cout <<"0.00000000 0.00000000" <<endl;
		cout <<"100.00000000 0.00000000" <<endl;
	}
	makeDots(A,B,0);

	cout <<100 <<" " <<0 <<endl;
	return 0;
}

