void koch(vector<pair<double, double>>::iterator begin, vector<pair<double, double>>::iterator end) {
	pair<double, double> s, u, t;
	s.first = 2 * begin->first / 3 + end->first / 3;
	s.second = 2 * begin->second / 3 + end->second / 3;
	t.first = begin->first / 3 + 2 * end->first / 3;
	t.second = begin->second / 3 + 2 * end->second / 3;
	u.first = (t.first - s.first) / 2 - (t.second - s.second) * sqrt(3) / 2 + s.first;
	u.second = (t.first - s.first) * sqrt(3) / 2 + (t.second - s.second) / 2 + s.second;
	vector<pair<double, double>> tmp;
	tmp.push_back(s);
	tmp.push_back(u);
	tmp.push_back(t);
	v.insert(++begin, tmp.begin(), tmp.end());
}

