void Koch(int n,double sx,double sy,double gx,double gy){
	if(n==0)	return;
	double ax,ay,bx,by,cx,cy;//sに近い順にa,b,c
	ax=(sx*2+gx)/3;	ay=(sy*2+gy)/3;
	cx=(sx+gx*2)/3;	cy=(sy+gy*2)/3;
	double xx=gx-sx,yy=gy-sy;
	if(yy==0){
		bx=(sx+gx)/2;
		by=sy+fabs(gx-sx)/3*sqrt(3)/2;
	}
	else if(xx>0){
		if(yy>0){
			bx=sx;	by=cy;
		}
		else{ 	
			bx=gx;	by=ay;
		}
	}
	else{
		if(yy>0){
			bx=gx;	by=ay;
		}
		else{
			bx=sx;	by=cy;
		}
	}
	Koch(n-1,sx,sy,ax,ay);
	printf("%.8lf %.8lf\n",ax,ay);
	Koch(n-1,ax,ay,bx,by);
	printf("%.8lf %.8lf\n",bx,by);
	Koch(n-1,bx,by,cx,cy);
	printf("%.8lf %.8lf\n",cx,cy);
	Koch(n-1,cx,cy,gx,gy);
	return;
}

