               unsigned short n) {
  if (n == 0) {
    return;
  }
  const double cos60 = 1 / 2;
  const double sin60 = sqrt(3) / 2;
  std::vector<double> s = {(2 * p1[0] + p2[0]) / 3, (2 * p1[1] + p2[1]) / 3};
  std::vector<double> t = {(p1[0] + 2 * p2[0]) / 3, (p1[1] + 2 * p2[1]) / 3};
