    Point(double d1, double d2): x{d1}, y{d2} {};
};

vector<Point> split(vector<Point> & vecP){
    vector<Point> result;
    bool is_first = true;
    Point p1{0, 0};
    for (auto & p2 : vecP){
        if (is_first){
            result.push_back(p2);
            p1 = p2;
            is_first = false;
            continue;
        }
        Point s{(2.0 * p1.x + p2.x) / 3.0, (2.0 * p1.y + p2.y) / 3.0};
        Point t{(2.0 * p2.x + p1.x) / 3.0, (2.0 * p2.y + p1.y) / 3.0};
        Point u{0, 0};
        u.x = s.x + (t.x - s.x) / 2.0 - sqrt(3) * (t.y - s.y) / 2.0;
        u.y = s.y + (t.y - s.y) / 2.0 + sqrt(3) * (t.x - s.x) / 2.0;
        result.push_back(s);
        result.push_back(u);
        result.push_back(t);
        result.push_back(p2);
        p1 = p2;
    }
    return result;
}

