    vector<Point> vecP;
    vecP.push_back(Point{0, 0});
    vecP.push_back(Point{100, 0});
    for (int i = 0; i != n; ++i) vecP = split(vecP);
    cout.precision(12);
    cout << fixed;
    for (auto p : vecP) cout << p.x << ' ' << p.y << endl;
    return 0;
}

