#define vdd vector<pair<double, double>>
#define PI 3.141592653589793

vdd get_points(vdd& A) {
    vdd B;
    double sx, sy;
    double lx, ly;
    for (int i = 0; i < A.size() - 1; i++) {
        B.push_back(A[i]);
        sx = A[i].first;
        sy = A[i].second;
        lx = (A[i+1].first  - A[i].first)  / 3;
        ly = (A[i+1].second - A[i].second) / 3;
        B.push_back(make_pair(sx + lx, sy + ly));
        B.push_back(make_pair(sx + lx + cos(PI/3) * lx - sin(PI/3) * ly,
                              sy + ly + sin(PI/3) * lx + cos(PI/3) * ly));
        B.push_back(make_pair(sx + lx * 2, sy + ly * 2));
    }
    B.push_back(A[A.size()-1]);
    return B;
}

