    A.push_back(make_pair(0.0, 0.0));
    A.push_back(make_pair(100.0, 0.0));

    for (int i = 0; i < N; i++) {
        A = get_points(A);
    }

    std::cout << std::fixed;
    for (int i = 0; i < A.size(); i++) {
        cout << std::setprecision(8) << A[i].first << " " << A[i].second << endl;
