void co(int N, point stt, point end) {
	if (N == 0) return;
	point right, left, mid;
	right.x = (stt.x + 2.0 * end.x) / 3.0;
	right.y = (stt.y + 2.0 * end.y) / 3.0;
	left.x  = (2.0 * stt.x + end.x) / 3.0;
	left.y  = (2.0 * stt.y + end.y) / 3.0;
	mid.x = (right.x - left.x) * cos(ANGLE)
		- (right.y - left.y) * sin(ANGLE) + left.x;
	mid.y = (right.x - left.x) * sin(ANGLE)
		+ (right.y - left.y) * cos(ANGLE) + left.y;

	co(N - 1, stt, left);
	printf("%.8lf %.8lf\n", left.x, left.y);
	co(N - 1, left, mid);
	printf("%.8lf %.8lf\n", mid.x, mid.y);
	co(N - 1, mid, right);
	printf("%.8lf %.8lf\n", right.x, right.y);
	co(N - 1, right, end);
	return;
}

