void solve( int n, int d, Pos start, Pos end ) {

	Pos p[5];

	p[0].x = start.x;
	p[1].x = ( end.x - start.x ) / 3;
	p[3].x = ( end.x - start.x ) / 3 * 2;
	p[4].x = end.x;

	p[0].y = start.y;
	p[1].y = (end.y - start.y) / 3;
	p[3].y = (end.y - start.y) / 3 * 2;
	p[4].y = end.y;

	p[2].x = (p[3].x - p[1].x)*cos(rad60) - (p[3].y - p[1].y)*sin(rad60) + p[1].x;
	p[2].y = (p[3].x - p[1].x)*sin(rad60) - (p[3].y - p[1].y)*cos(rad60) + p[1].y;

	if (n == d + 1) {
		for (int i = 0; i < 4; i++) {
			cout << p[i].x << " " << p[i].y << endl;
		}
	}
	else {
		for (int i = 0; i < 4; i++) {
			solve(n, d + 1, p[i], p[i + 1]);
		}
	}

}

