{
	int n;
	cin >> n;
	list<TCoordinate> Point;
	TCoordinate Start = {  0, 0};
	TCoordinate End   = {100, 0};
	Point.push_back(Start);
	Point.push_back(End);
	auto itr = Point.end();
	itr--;
	Koch(Point, n, Point.begin(), itr);
	Output(Point);
	return 0;
}

