void kochCurve(int n, Point p1, Point p2) {

	if (n == 0) {
		cout << p1.x << " " << p1.y << endl;
		if (p2.x == 100) {
			cout << p2.x << " " << p2.y << endl;
		}
		return;
	}

	double lx;
	double ly;
	lx = p2.x - p1.x;
	ly = p2.y - p1.y;
	Point s(p1.x + lx / 3, p1.y + ly / 3);
	Point t(p1.x+lx/3*2,p1.y+ly/3*2);
