void koch(double p1x, double p1y, double p2x, double p2y, int n) {

	if (n == 0) return;

	double sx, sy, ux, uy, tx, ty, lx, ly;

	if (p1x > p2x)
	{
		lx = p1x - p2x;
		tx = p2x + lx/3.0;
		sx = p2x + 2.0*lx/3.0;
		if (p1y > p2y)
		{
			ly = p1y - p2y;
			ty = p2y + ly/3.0;
			sy = p2y + 2.0*ly/3.0;
			ux = (sx - tx)*cos(M_PI/3.0) - (sy - ty)*sin(M_PI/3.0) + sx;
			uy = (sx - tx)*sin(M_PI/3.0) - (sy - ty)*cos(M_PI/3.0) + sy;
		}
		else
		{
			ly = p2y - p1y;
			sy = p1y + ly/3.0;
			ty = p1y + 2.0*ly/3.0;
			ux = (sx - tx)*cos(M_PI/3.0) - (ty - sy)*sin(M_PI/3.0) + sx;
			uy = (sx - tx)*sin(M_PI/3.0) - (ty - sy)*cos(M_PI/3.0) + sy;
		}
	}
	else
	{
		lx = p2x - p1x;
		sx = p1x + lx/3.0;
		tx = p1x + 2.0*lx/3.0;
		if (p1y > p2y)
		{
			ly = p1y - p2y;
			ty = p2y + ly/3.0;
			sy = p2y + 2.0*ly/3.0;
			ux = (tx - sx)*cos(M_PI/3.0) - (sy - ty)*sin(M_PI/3.0) + sx;
			uy = (tx - sx)*sin(M_PI/3.0) - (sy - ty)*cos(M_PI/3.0) + sy;
		}
		else
		{
			ly = p2y - p1y;
			sy = p1y + ly/3.0;
			ty = p1y + 2.0*ly/3.0;
			ux = (tx - sx)*cos(M_PI/3.0) - (ty - sy)*sin(M_PI/3.0) + sx;
			uy = (tx - sx)*sin(M_PI/3.0) - (ty - sy)*cos(M_PI/3.0) + sy;
		}
	}
	koch(p1x, p1y, sx, sy, n - 1);
	printf("%.8f %.8f\n", sx, sy);
	koch(sx, sy, ux, uy, n - 1);
	printf("%.8f %.8f\n", ux, uy);
	koch(ux, uy, tx, ty, n - 1);
	printf("%.8f %.8f\n", tx, ty);
	koch(tx, ty, p2x, p2y, n - 1);
}

