	if(fabs(k-sqrt(3))<eps) u=(pos){xa,yb-tmp2};
	if(fabs(k+sqrt(3))<eps) u=(pos){xb,yb-2*tmp2};

	solve(from,s,step-1);
	solve(s,u,step-1);
	solve(u,t,step-1);
	solve(t,to,step-1);
}
