using namespace std;

typedef complex<double> Comp;
void koch(Comp left, Comp right, vector<Comp> &v, int i,int n) {
	if (i == n) return;
	double r = sqrt(((conj(right - left)*(right - left)).real()))/3;
	Comp nextr = (left + Comp(2) * right) / Comp(3),
		nextl = (Comp(2)*left + right) / Comp(3),
		next;
	if (nextl.imag() == nextr.imag()) {
		next = { nextl.real() + r * 1 / 2 ,nextl .imag() + r*sqrt(3) / 2 };
	}
	else if (nextl.real() < nextr.real()) {
		if(nextl.imag() < nextr.imag())	next = { nextr.real() - r,nextr.imag() };
		else next = { nextl.real() + r,nextl.imag() };
	}
	else {
		if (nextl.imag() < nextr.imag()) next = { nextl.real() - r,nextr.imag() };
		else next = { nextr.real() + r,nextr.imag() };
	}
	auto p = find(ALL(v),left);
	v.insert(p + 1, nextl);
	p = find(ALL(v), left);
	v.insert(p + 2, next);
	p = find(ALL(v), left);
	v.insert(p + 3, nextr);
	koch(left, nextl, v, i + 1, n);
	koch(nextl, next, v, i + 1, n);
	koch(next, nextr, v, i + 1, n);
	koch(nextr, right, v, i + 1, n);
}

