        for(int i=1; i<5; i++){
            printf("%.8f %.8f\n", newx[i], newy[i]);
        }
        return;
    }
    for(int i=0; i<4; i++){
        make_fractal(n-1, newx[i], newy[i], newx[i+1], newy[i+1]);
    }
}

