void print_koch(unsigned int n, const point& p1, const point& p2) {
  if (n == 0) return;
  point s = (2*p1 + p2)/3;
  point t = (p1 + 2*p2)/3;
  point u = (t-s).rotate_m60() + s;

  print_koch(n-1, p1, s);
  print_point(s);
  print_koch(n-1, s, u);
  print_point(u);
  print_koch(n-1, u, t);
  print_point(t);
  print_koch(n-1, t, p2);
  print_point(p2);
}

