        points.push( make_pair( x , y ) );

        x = left[0] + ( ( right[0] - left[0] ) / 3.0 ) * cos( pi / 3 ) - ( ( right[1] - left[1] ) / 3.0 ) * sin( pi / 3 ) + ( right[0] - left[0] ) / 3.0;
