        return;
    P p3,p4,p5;
    double dx,dy,a,b;
    p3.x = 2./3*p1.x+p2.x/3;
    p3.y = 2./3*p1.y+p2.y/3;
    p4.x = 1./3*p1.x+p2.x*2/3;
