using namespace std;

const double sqrt3 = sqrt(3);

struct point {
    double x;
    double y;
    point(double _x, double _y) : x(_x), y(_y) {}

    point operator+(point a) const {
        return point(this->x + a.x, this->y + a.y);
    }

    point operator-(point a) const {
        return point(this->x - a.x, this->y - a.y);
    }
};

point operator*(double t, point p) {
    return point(t * p.x, t * p.y);
}

point rotate60(point p) {
    return point((p.x - sqrt3 * p.y)/2, (sqrt3 * p.x + p.y)/2);
}

vector<point> koch(int n) {
    vector<point> ps;
    ps.push_back(point(0, 0));
    ps.push_back(point(100, 0));
    for(int i=0; i<n; i++) {
        vector<point> nxt;
        nxt.push_back(ps[0]);
        for(int j=1; j<ps.size(); j++) {
            point dir = ps[j] - ps[j-1];
            point fst = (1/3.0) * dir;
            point trd = (2/3.0) * dir;
            point snd = rotate60(trd - fst) + fst;
            nxt.push_back(ps[j-1] + fst);
            nxt.push_back(ps[j-1] + snd);
            nxt.push_back(ps[j-1] + trd);
            nxt.push_back(ps[j]);
        }
        ps = nxt;
    }
    return ps;
}


int main() {
    int n;
    cin >> n;
    vector<point> ps = koch(n);
    for(auto&& p : ps) {
        cout << fixed << setprecision(10) << p.x << " " << p.y << endl;
    }
}

