typedef pair<double, double> Point;

Point splitMN(Point p1, Point p2, double m, double n){
  Point result;
  result.first = (n*p1.first+m*p2.first)/(m+n);
  result.second = (n*p1.second+m*p2.second)/(m+n);
  return result;
}

Point rot60ClockWise(Point p1, Point p2){
  constexpr double sqrt3=1.7320508075688772935274463;
  constexpr double sin60=sqrt3/2;
  constexpr double cos60=1/2.0;
  Point result;
  result.first = (p2.first - p1.first)*cos60 - (p2.second - p1.second)*sin60 + p1.first;
  result.second = (p2.first - p1.first)*sin60 + (p2.second - p1.second)*cos60 + p1.second;
  return result;
}

void kochCurve(Point l, Point r, int n){
  if (n==0) return;
  Point s= splitMN(l, r, 1, 2);
  Point t= splitMN(l, r, 2, 1);
  Point u= rot60ClockWise(s, t);

  kochCurve(l, s, n-1);
  cout << s.first << " " << s.second << endl;

  kochCurve(s, u, n-1);
  cout << u.first << " " << u.second << endl;

  kochCurve(u, t, n-1);
  cout << t.first << " " << t.second << endl;

  kochCurve(t, r, n-1);
}

