int N;
class Point{
public:
	double x,y;
	Point()=default;
	Point(double u,double v):x(u),y(v){}
};

using PIter = list<Point>::iterator;

void Koch(list<Point>& P,PIter start,PIter end,int depth){
	if(depth==N) return;
	Point s,t,u;
	double dx = end->x-start->x;
	double dy = end->y-start->y;
	s.x = start->x+dx/3.0, s.y = start->y+dy/3.0;
	t.x = start->x+2.0*dx/3.0, t.y = start->y+2.0*dy/3.0;

	double nx = -dy, ny = dx;
	double norm = hypot(dx,dy);
	nx /= norm;
	ny /= norm;

	double l = norm*sin(4.0*atan(1.0)/3.0)/3.0;
	u.x = start->x+dx/2.0+nx*l, u.y = start->y+dy/2.0+ny*l;

	PIter si = P.insert(end,s);
	PIter ui = P.insert(end,u);
	PIter ti = P.insert(end,t);

	Koch(P,start,si,depth+1);
	Koch(P,si,ui,depth+1);
	Koch(P,ui,ti,depth+1);
	Koch(P,ti,end,depth+1);
}

