static void CreateTriangle(const Point& p1, const Point& p2, int n) {
  if (n <= 0)
    return;

  static const double kCos60 = cos(60.0 * M_PI / 180.0);
  static const double kSin60 = sin(60.0 * M_PI / 180.0);

  const double dx = (p2.x - p1.x) / 3.f;
  const double dy = (p2.y - p1.y) / 3.f;

  Point ps;
  ps.x = p1.x + dx;
  ps.y = p1.y + dy;

  Point pt;
  pt.x = p2.x - dx;
  pt.y = p2.y - dy;

  Point pu;
  pu.x = ps.x + (pt.x - ps.x) * kCos60 + (pt.y - ps.y) * kSin60;
  pu.y = ps.y + (pt.x - ps.x) * kSin60 + (pt.y - ps.y) * kCos60;

  CreateTriangle(p1, ps, n - 1);
  printf("%f %f\n", ps.x, ps.y);
  CreateTriangle(ps, pu, n - 1);
  printf("%f %f\n", pu.x, pu.y);
  CreateTriangle(pu, pt, n - 1);
  printf("%f %f\n", pt.x, pt.y);
  CreateTriangle(pt, p2, n - 1);
}

