void kofh(int n, vector<pair<double, double>> &points)
{
    vector<pair<double, double>> new_points;
    double x1, y1, x2, y2, dx, dy, rx, ry;
    double x3, y3, x4, y4, x5, y5;
    for (int i = 0; i < n - 1; i++)
    {
        x1 = points[i].first, y1 = points[i].second;
        x2 = points[i + 1].first, y2 = points[i + 1].second;

        dx = (x2 - x1) / 3, dy = (y2 - y1) / 3;
        rx = (dx - sqrt(3) * dy) / 2, ry = (sqrt(3) * dx + dy) / 2;
        x3 = x1 + dx, y3 = y1 + dy;
        x4 = x3 + rx, y4 = y3 + ry;
        x5 = x2 - dx, y5 = y2 - dy;

        new_points.push_back(make_pair(x1, y1));
        new_points.push_back(make_pair(x3, y3));
        new_points.push_back(make_pair(x4, y4));
        new_points.push_back(make_pair(x5, y5));
    }
    new_points.push_back(make_pair(points[n - 1].first, points[n - 1].second));
    points.clear();
    points = new_points;
    new_points.clear();
}

