void koch(Pd x1, Pd x2, int n){
  if(n == 0){
    cout << x1.FI << " " << x1.SE << endl;
    return;
  }
  Pd t1, t2, t3;
  t1.FI = (2. * x1.FI + x2.FI) / 3.;
  t1.SE = (2. * x1.SE + x2.SE) / 3.;
  t3.FI = (2. * x2.FI + x1.FI) / 3.;
  t3.SE = (2. * x2.SE + x1.SE) / 3.;
  t2.FI = (0.5 * (x2.FI - x1.FI) - 0.5 * sqrt(3.) * (x2.SE - x1.SE)) / 3.;
  t2.SE = (0.5 * sqrt(3.) * (x2.FI - x1.FI) + 0.5 * (x2.SE - x1.SE)) / 3.;
  t2.FI += t1.FI;
  t2.SE += t1.SE;

  koch(x1, t1, n - 1);
  koch(t1, t2, n - 1);
  koch(t2, t3, n - 1);
  koch(t3, x2, n - 1);
}

