void SolveKochCurvePoint(V<CD> *vec, int depth, const CD &first, const CD &last) {
	// 呼び出し回数
	if (depth-- <= 0)
		return;
	V<CD> &v = *vec;
	// 計算と追加
	CD dist = last - first;
	CD diff = CD(dist.real() / 3.0, dist.imag() / 3.0);
	CD s = first + diff;
	CD t = s + diff;
	double u_x = diff.real() * cos(kPI / 3) - diff.imag() * sin(kPI / 3) + s.real();
	double u_y = diff.real() * sin(kPI / 3) + diff.imag() * cos(kPI / 3) + s.imag();
	CD u = CD(u_x, u_y);
	// 呼び出し
	SolveKochCurvePoint(&v, depth, first, s);
	v.PB(s);
	SolveKochCurvePoint(&v, depth, s, u);
	v.PB(u);
	SolveKochCurvePoint(&v, depth, u, t);
	v.PB(t);
	SolveKochCurvePoint(&v, depth, t, last);
	return;
}

