vector<pair<double, double> > koch(vector<pair<double, double> > p){
    vector<pair<double, double> >ret;
    for(int i = 0;i < (p.size() - 1);i++){
        pair<double, double> p1 = p[i];
        pair<double, double> p2 = p[i+1];

        double xsabun = p2.first - p1.first;
        double ysabun = p2.second - p1.second;
        pair<double, double> s ( p1.first+(xsabun/3), p1.second+(ysabun/3));
        pair<double, double> t ( p2.first-(xsabun/3), p2.second-(ysabun/3));

        pair<double, double> u;
        double distance=sqrt(xsabun*xsabun+ysabun*ysabun)/sqrt(3);
        if(xsabun>=0){
            double angle1=atan(ysabun/xsabun)+(M_PI/6); 
            u.first = p1.first+(distance*cos(angle1));
            u.second = p1.second+(distance*sin(angle1));
        } else {
            double angle2=atan(ysabun/xsabun)-M_PI/6;
            u.first = p2.first+(distance*cos(angle2));
            u.second = p2.second+(distance*sin(angle2));
        }
        ret.push_back(p1);
        ret.push_back(s);
        ret.push_back(u);
        ret.push_back(t);
    }

    ret.push_back(p.back());
    return ret;
}

