        {pt1[0],pt1[1]},
        {pt3[0],pt3[1]},
        {pt2[0],pt2[1]},
        {g[0],g[1]}
    };
    if(n == 0){
        ans[0][0] = s[0];
        ans[0][1] = s[1];
