  mid.x = (next_e.x - next_s.x) * cos(th) - (next_e.y -next_s.y) * sin(th) + next_s.x;
  mid.y = (next_e.x - next_s.x) * sin(th) + (next_e.y -next_s.y) * cos(th) + next_s.y;

