void printver(double s[], double e[], int n)
{
    if (n == 0) {
        printf("%f %f\n", s[0], s[1]);
        return ;
    }
    double left[2], right[2], center[2];

    left[0] = s[0] + (e[0] - s[0]) / 3;
    left[1] = s[1] + (e[1] - s[1]) / 3;

    right[0] = e[0] - (e[0] - s[0]) / 3;
    right[1] = e[1] - (e[1] - s[1]) / 3;

    center[0] = (right[0] - sqrt(3) * right[1] + left[0] + sqrt(3) * left[1]) / 2;
    center[1] = (sqrt(3) * right[0] + right[1] - sqrt(3) * left[0] + left[1]) / 2;

    printver(s, left, n - 1);
    printver(left, center, n - 1);
    printver(center, right, n - 1);
    printver(right, e, n - 1);
}

