  return Point(p1.x - p2.x, p1.y - p2.y);
}

const double PI = 4.0 * atan(1.0);
auto rotate60 = bind(&Point::rotate, placeholders::_1, PI / 3.0);

void koch(int n, Point p1, Point p2) {
