void koch(int num, Point p1, Point p2){
  Point s,t,u;
  double theta=M_PI*60/180;  /*convert degree into radian*/
  if(num==0) return;
  s.x=(2*p1.x+p2.x)/3;
  s.y=(2*p1.y+p2.y)/3;

  t.x=(p1.x+2*p2.x)/3;
  t.y=(p1.y+2*p2.y)/3;

  u.x=(t.x-s.x)*cos(theta)-(t.y-s.y)*sin(theta)+s.x;
  u.y=(t.x-s.x)*sin(theta)+(t.y-s.y)*cos(theta)+s.y;

  koch(num-1,p1,s);
  printf("%.8f %.8f\n",s.x,s.y);

  koch(num-1,s,u);
  printf("%.8f %.8f\n",u.x,u.y);

  koch(num-1,u,t);
  printf("%.8f %.8f\n",t.x,t.y);

  koch(num-1,t,p2);
}

