void koch( int num , Point a , Point b ){
  if( num == 0 ){return ; }

  Point c,d,e;


  c.x = ( 2.0 * a.x + 1.0 * b.x ) / 3.0;
  c.y = ( 2.0 * a.y + 1.0 * b.y ) / 3.0;
  d.x = ( 1.0 * a.x + 2.0 * b.x ) / 3.0;
  d.y = ( 1.0 * a.y + 2.0 * b.y ) / 3.0;
  e.x = ( d.x - c.x ) * cos( M_PI/3 ) - (d.y - c.y ) * sin( M_PI/3 ) + c.x;
  e.y = ( d.x - c.x ) * sin( M_PI/3 ) + (d.y - c.y ) * cos( M_PI/3 ) + c.y;

  koch( num - 1 , a , c );
  printf("%.8f %.8f\n" , c.x , c.y );
  koch( num - 1 , c , e );
  printf("%.8f %.8f\n" , e.x , e.y );
  koch( num - 1 , e , d );
  printf("%.8f %.8f\n" , d.x , d.y );
  koch( num - 1 , d , b );
}

#include<stdio.h>
