void fractal(int, koch, koch);

int main()
{    
  koch p1, p2;
  int n;

  p1.x = 0;
  p2.x = 100;
  p1.y = 0;
  p2.y = 0;

  scanf("%d", &n);

  printf("%f %f\n", p1.x, p1.y);
  fractal(n, p1, p2);
  printf("%f %f\n", p2.x, p2.y);

  return 0;
