	int n;
	Point left, right;

	left.x = 0.0;
	left.y = 0.0;
	right.x = 100.0;
	right.y = 0.0;

	scanf("%d", &n);

	printf("%f %f\n", left.x, left.y);
	koch(left, right, n);

	return 0;
}

