void koch(int n, Point a, Point b)
{
  if(n == 0)return;

  Point s, t, u;
  double th = M_PI * 60.0 / 180.0;/*th = (π/3)*/

  s.x = (2.0 * a.x + 1.0 * b.x) / 3.0;/*内分点sのx座標*/
  s.y = (2.0 * a.y + 1.0 * b.y) / 3.0;/*内分点sのy座標*/
  t.x = (1.0 * a.x + 2.0 * b.x) / 3.0;/*内分点tのx座標*/
  t.y = (1.0 * a.y + 2.0 * b.y) / 3.0;/*内分点tのy座標*/
  u.x = (t.x - s.x) * cos(th) - (t.y - s.y) * sin(th) + s.x;/*点tのx座標を60°回転*/
  u.y = (t.x - s.x) * sin(th) + (t.y - s.y) * cos(th) + s.y;/*点tのy座標を60°回転*/

  koch(n - 1, a, s);                 /*線分asについて上記と同じ処理をする*/
  printf("%.8f %.8f\n",s.x,s.y);    
  koch(n - 1, s, u);                 /*線分suについて上記と同じ処理をする*/
  printf("%.8f %.8f\n",u.x,u.y);
  koch(n - 1, u ,t);                 /*線分utについて上記と同じ処理をする*/
  printf("%.8f %.8f\n",t.x,t.y);    
  koch(n - 1, t, b);                 /*線分tbについて上記と同じ処理をする*/
}

