typedef struct Coordinate{
    double x, y;
}cd;


void kock(int n, cd p1, cd p2){
    if(n==0) return;
    cd s, t, u;
    /*p1、p2、からs、t、uを計算*/
    s.x = (2.0*p1.x + p2.x) / 3.0;
    s.y = (2.0*p1.y + p2.y) / 3.0;
    t.x = (2.0*p2.x + p1.x) / 3.0;
    t.y = (2.0*p2.y + p1.y) / 3.0;
    u.x = (t.x - s.x) * cos(M_PI/3.0) - (t.y - s.y) * sin(M_PI/3.0) + s.x;
    u.y = (t.x - s.x) * sin(M_PI/3.0) + (t.y - s.y) * cos(M_PI/3.0) + s.y;

    kock(n-1, p1, s);
    printf("%.8f %.8f\n", s.x, s.y);
    kock(n-1, s, u);
    printf("%.8f %.8f\n", u.x, u.y);
    kock(n-1, u, t);
    printf("%.8f %.8f\n", t.x, t.y);
    kock(n-1, t, p2);
}

