typedef struct box{//頂点のx,y座標をメンバとした構造体
	double x;
	double y;
} point;

void kock(int n,point p1,point p2)//p1-p2間で正三角形を形成し、各頂点座標を出力しながら各辺に置いて再帰
{
	point s,t,u;
	if(n==0) return;
	s.x=(2*p1.x+p2.x)/3;//内分の性質を利用
	s.y=(2*p1.y+p2.y)/3;
	t.x=(p1.x+2*p2.x)/3;
	t.y=(p1.y+2*p2.y)/3;
	u.x=(t.x-s.x)*cos(M_PI*1/3)-(t.y-s.y)*sin(M_PI*1/3)+s.x;//回転行列を利用
	u.y=(t.x-s.x)*sin(M_PI*1/3)+(t.y-s.y)*cos(M_PI*1/3)+s.y;
	//ここまでで正三角形の頂点座標を計算
	kock(n-1,p1,s);//左端に近い辺から再帰
	printf("%.8f %.8f\n",s.x,s.y);//頂点座標を出力
	kock(n-1,s,u);
	printf("%.8f %.8f\n",u.x,u.y);
	kock(n-1,u,t);
	printf("%.8f %.8f\n",t.x,t.y);
	kock(n-1,t,p2);
}


