	r.y=p.y+q.y;
	return r;
}

point scal(double a,point p){
	point r;
	r.x=a*p.x;
	r.y=a*p.y;
	return r;
}


point minus(point p){
	return scal(-1,p);
}


point calcU(point s,point t){
	point half,u,delta,delta2;
	half=scal(1/2.0,plus(s,t));
	delta=plus(t,minus(s));
	delta2.y=delta.x;
	delta2.x=-delta.y;
	delta2=scal(sqrt(3)/2.0,delta2);
	u=plus(half,delta2);
	return u;
}

