void kock(int n, Point p1, Point p2) {
  Point s, t, u;
  if ( n == 0 ) return;

  s.x = (2.0 * p1.x + p2.x) / 3.0;
  s.y = (2.0 * p1.y + p2.y) / 3.0;
  t.x = (p1.x + 2.0 * p2.x) / 3.0;
  t.y = (p1.y + 2.0 * p2.y) / 3.0;

  u.x = (t.x - s.x) * cos(PI/3.0) - (t.y - s.y) * sin(PI/3.0) + s.x;
  u.y = (t.x - s.x) * sin(PI/3.0) - (t.y - s.y) * cos(PI/3.0) + s.y;

  kock(n - 1, p1, s);
  printf("%.8f %.8f\n", s.x, s.y);
  kock(n - 1, s, u);
  printf("%.8f %.8f\n", u.x, u.y);
  kock(n - 1, u, t);
  printf("%.8f %.8f\n", t.x, t.y);
  kock(n - 1, t, p2);

}

