} point_t;

#define PI 3.14159265

static point_t calc_internally_dividing(point_t a, point_t b, int32_t n, int32_t m)
{
  point_t ret = {.x = (n * a.x + m * b.x) / (n + m), .y = (n * a.y + m * b.y) / (n + m)};
  return ret;
}

static point_t add_vector(point_t vec1, point_t vec2)
{
  point_t ret = {.x = vec1.x + vec2.x, .y = vec1.y + vec2.y};
  return ret;
}

static point_t sub_vector(point_t vec1, point_t vec2)
{
  point_t ret = {.x = vec1.x - vec2.x, .y = vec1.y - vec2.y};
  return ret;
}

static point_t rotate_vector(point_t vec, double rad)
{
  point_t ret = {.x = vec.x * cos(rad) - vec.y * sin(rad), .y = vec.y * sin(rad) + vec.y * cos(rad)};
  return ret;
}

size_t koch_curve(uint32_t n, point_t a, point_t b, point_t data[])
{
  size_t len = ((int)pow(4, n)) + 1;

  if (n == 0) {
    data[0] = a;
    data[1] = b;
  } else {
    int32_t data_size = koch_curve(n - 1, a, b, data);

    size_t tmpbuf_size = sizeof(point_t) * len;
    point_t *tmpbuf = (point_t *)malloc(tmpbuf_size);

    if (tmpbuf == NULL) {
      perror("malloc error");
      exit(1);
    }

    for (int32_t i = 0; i < (data_size - 1); i++) {
      point_t s = calc_internally_dividing(data[i], data[i + 1], 2, 1);
      point_t t = calc_internally_dividing(data[i], data[i + 1], 1, 2);
      point_t u = add_vector(rotate_vector(sub_vector(t, s), PI / 3), s);

      tmpbuf[5 * i] = data[i];
      tmpbuf[5 * i + 1] = s;
      tmpbuf[5 * i + 2] = u;
      tmpbuf[5 * i + 3] = t;
      tmpbuf[5 * i + 4] = data[i + 1];
    }
    memcpy(data, tmpbuf, tmpbuf_size);
    free(tmpbuf);
  }

  return len;
}

