  tx = (p1x + 2*p2x) / 3;
  ty = (p1y + 2*p2y) / 3;
  ux = (tx - sx)*cos(rad) - (ty - sy)*sin(rad) + sx;
  uy = (tx - sx)*sin(rad) + (ty - sy)*cos(rad) + sy;

