  kock(n - 1, sx, sy, ux, uy);
  printf("%f %f\n", ux, uy);
  kock(n - 1, ux, uy, tx, ty);
  printf("%f %f\n", tx, ty);
  kock(n - 1, tx, ty, p2x, p2y);
}

