/*
整数 n を入力し、深さ n の再帰呼び出しによって作成されるコッホ曲線の頂点の座標を出力するプログラム
*/
#include <stdio.h>
#include <math.h>

#define PI 3.1415926535897932     /*　円周率　*/

/* ある点のx座標、y座標を記憶する構造体　*/
typedef struct{

  double x;
  double y;

}XY;

void koch(int, XY, XY);

int main()
{
  int n;
  XY p1 = {0.0, 0.0}, p2 = {100.0, 0.0};

  scanf("%d", &n);

  /* コッホ曲線の各頂点の座標(x,y)を計算し、出力　端点は(0,0) , (100,0) */
  printf("%.8f %.8f\n", p1.x, p1.y);
  koch(n, p1, p2);
  printf("%.8f %.8f\n", p2.x, p2.y);

  return 0;
}

/* 深さnの再帰呼び出しによって作成されるコッホ曲線の頂点を出力する関数　*/
void koch(int n, XY p1, XY p2)
{
  XY s, t, u;

  if( n == 0 )
    return;

  /* 線分 p1 -> p2 を３等分する２点 s,t　とs,tを頂点とする正三角形の残りの頂点uを求める */
  s.x = ( 2*p1.x + p2.x )/3;
  s.y = ( 2*p1.y + p2.y )/3;
  t.x = ( p1.x + 2*p2.x )/3;
  t.y = ( p1.y + 2*p2.y )/3;
  u.x = (t.x - s.x)*cos(PI/3) - (t.y - s.y)*sin(PI/3) + s.x;
  u.y = (t.x - s.x)*sin(PI/3) + (t.y - s.y)*cos(PI/3) + s.y;

  koch(n-1, p1, s);
  printf("%.8f %.8f\n", s.x, s.y);
  koch(n-1, s, u);
  printf("%.8f %.8f\n", u.x, u.y);
  koch(n-1, u, t);
  printf("%.8f %.8f\n", t.x, t.y);
  koch(n-1, t, p2);

}

