Point data[N], tmp[N];
int size;

void MergeSort(Point data[], int left, int right){
  int mid, i, j, k;
  if(left >= right) return;
  mid = (left + right) / 2;
  MergeSort(data, left, mid);
  MergeSort(data, mid+1, right);
  for(i=left;i<=mid;i++) tmp[i] = data[i];
  for(i=mid+1,j=right;i<=right;i++,j--) tmp[i] = data[j];
  i = left;
  j = right;
  for(k=left;k<=right;k++){
    if(tmp[i].x <= tmp[j].x) data[k] = tmp[i++];
    else data[k] = tmp[j--];
  }
}

void kochCurve(Point a, Point b, int n, int p){
  Point o = (Point){(b.x-a.x)/3.0, (b.y-a.y)/3.0};
  Point s = (Point){o.x+a.x, o.y+a.y};
  Point u = (Point){s.x + o.x / 2.0 - sqrt(3.0) * o.y / 2.0, s.y + sqrt(3.0) * o.x / 2.0 + o.y / 2.0};
  Point t = (Point){(b.x-a.x)*2.0/3.0+a.x, (b.y-a.y)*2.0/3.0+a.y};
  if(p == n) return;
  data[size++] = s;
  data[size++] = t;
  data[size++] = u;
  kochCurve(a, s, n, p+1);
  kochCurve(s, u, n, p+1);
  kochCurve(u, t, n, p+1);
  kochCurve(t, b, n, p+1);
}

