void func(point p1,point p2,double tilt){
  int bcnt=0;
  double len_x,len_y,splen;
  point p3,p4,newp;

  //make vertex
  len_x=p2.x-p1.x;
  len_y=p2.y-p1.y;
  splen=sqrt((len_y*len_y)+(len_x*len_x))/3;
  len_x/=3;
  len_y/=3;
  p3.x=p1.x+len_x;
  p3.y=p1.y+len_y;
  p4.x=p3.x+len_x;
