int koch(int n , Point p1 , Point p2){

  Point s,t,u;

  if(n==0) return 0;


  s.x=(p2.x+2*p1.x)/3.0;
  s.y=(p2.y+2*p1.y)/3.0;

  t.x=(p1.x+2*p2.x)/3.0;
  t.y=(p1.y+2*p2.y)/3.0;

  u.x=(t.x-s.x)/2-(t.y-s.y)*(sqrt(3)/2)+s.x;
  u.y=(t.x-s.x)*(sqrt(3)/2)+(t.y-s.y)/2+s.y;


 koch(n-1, p1, s);
  printf("%f %f\n",s.x,s.y);

  koch(n-1, s, u);
  printf("%f %f\n",u.x,u.y);

  koch(n-1, u, t);
  printf("%f %f\n",t.x,t.y);

  koch(n-1, t, p2);
}

