void kock(int n,Point p1,Point p2)
{
  Point s,t,u;
  if(n == 0) return;

  /* p1,p2からs, t, uを計算 */
  s.x = (2 * p1.x + 1 * p2.x) / 3.0;
  s.y = (2 * p1.y + 1 * p2.y) / 3.0;
  t.x = (1 * p1.x + 2 * p2.x) / 3.0;
  t.y = (1 * p1.y + 2 * p2.y) / 3.0;
  u.x = ((t.x - s.x) * cos(60 * M_PI/180.0)) - ((t.y - s.y) * (sin(60 * M_PI/180.0))) + s.x;
  u.y = ((t.x - s.x) * sin(60 * M_PI/180.0)) - ((t.y - s.y) * (cos(60 * M_PI/180.0))) + s.y;

  /* 再帰的に呼び出し、出力 */
  kock(n-1,p1,s);
  printf("%f %f\n",s.x,s.y);

  kock(n-1,s,u);
  printf("%f %f\n",u.x,u.y);

  kock(n-1,u,t);
  printf("%f %f\n",t.x,t.y);
  kock(n-1,t,p2);

}

