	g_cos_pi_3 = cos(M_PI / 3.0);
	g_sin_pi_3 = sin(M_PI / 3.0);
	scanf("%d", &n);
	koch_curve(0.0, 0.0, 100.0, 0.0, n);
	return 0;
}

