void KOHHO(int n,TEN p,TEN q)
{
  TEN s,t,u;

  if(n==0)return;

  s.x=( (2*p.x) + q.x )/3;
  s.y=( (2*p.y) + q.y )/3;
  t.x=( p.x + (2*q.x) )/3;
  t.y=( p.y + (2*q.y) )/3;
  u.x=(t.x-s.x)*cos(M_PI/3) - (t.y-s.y)*sin(M_PI/3) + s.x;
  u.y=(t.x-s.x)*sin(M_PI/3) + (t.y-s.y)*cos(M_PI/3) + s.y;

  KOHHO(n-1,p,s);
  printf("%f %f\n",s.x,s.y);
  KOHHO(n-1,s,u);
  printf("%f %f\n",u.x,u.y);
  KOHHO(n-1,u,t);
  printf("%f %f\n",t.x,t.y);
  KOHHO(n-1,t,q);

}

