double d; int a;
double vcos[6], vsin[6];
double x, y;

void koch_curve(int k)
{
	if (k == 0) {
		x += d*vcos[a % 6], y += d*vsin[a%6];
		printf("%.8lf %.8lf\n", x, y);
	} else {
		d /= 3;
		koch_curve(k-1), a++, koch_curve(k-1);
		a += 4;
		koch_curve(k-1), a++, koch_curve(k-1);
		d *= 3;
	}
}

int main()
{
