  a.y += b.y;
  return a;
}

Vector subtract(Vector a, Vector b) {
  a.x -= b.x;
  a.y -= b.y;
  return a;
}

Vector multiply(Vector a, double b) {
  a.x *= b;
  a.y *= b;
  return a;
}

Vector divide(Vector a, double b) {
  a.x /= b;
  a.y /= b;
  return a;
}

Vector rotate(Vector v, double angle) {
  Vector nv;
  nv.x = v.x * cos(angle) - v.y * sin(angle);
  nv.y = v.x * sin(angle) + v.y * cos(angle);
  return nv;
}

Point rec(int n, Point a, Point b) {
  Vector v,u;
  Point c,d,e;
  if(n == 0) {
    printf("%.8f %.8f\n", a.x, a.y);
