  v = subtract(b,a);
  u = divide(v,3.0);
  c = add(a,u);
  d = add(c,u);
  e = add(c,rotate(u,M_PI/3.0));
  rec(n-1, a, c);
  rec(n-1, c, e);
  rec(n-1, e, d);
  rec(n-1, d, b);
}

