  s.x = ( (2 * p1.x) + (1 * p2.x) ) / 3;
  s.y = ( (2 * p1.y) + (1 * p2.y) ) / 3;

  /* calculate t */
  t.x = ( (1 * p1.x) + (2 * p2.x) ) / 3;
  t.y = ( (1 * p1.y) + (2 * p2.y) ) / 3;

