Point getPoint(Point s, Point t, double len){
  Point u;

  if(s.x < t.x){
    if(s.y == t.y){
      u.x = s.x + (t.x - s.x)/2.0;
      u.y = s.y + sin(M_PI/3) * len;
    }
    else if(s.y < t.y){
      u.x = t.x -  len;
      u.y = t.y;
    }
    else if(s.y > t.y){
      u.x = s.x + len;
      u.y = s.y;
    }
  }
  else if(s.x > t.x){
    if(s.y == t.y){
      u.x = s.x - (t.x - s.x)/2.0;
      u.y = s.y - sin(M_PI/3) * len;
    }
    else if(s.y < t.y){
      u.x = s.x - len;
      u.y = s.y;
    }
    else if(s.y > t.y){
      u.x = t.x + len;
      u.y = t.y;
    }
  }

  return u;
}

