void Print_Kock_Curve(int n, POINT p1, POINT p2)
{
    POINT s, t, u;

    if(n == 0)
    {
        return;
    }



    s.x = (2 * p1.x + 1 * p2.x) / 3;
    s.y = (2 * p1.y + 1 * p2.y) / 3;
    t.x = (1 * p1.x + 2 * p2.x) / 3;
    t.y = (1 * p1.y + 2 * p2.y) / 3;
    u.x = (t.x - s.x) * cos(rad(60)) - (t.y - s.y) * sin(rad(60)) + s.x;
    u.y = (t.x - s.x) * sin(rad(60)) - (t.y - s.y) * cos(rad(60)) + s.y;


    Print_Kock_Curve(n - 1, p1, s);
