void kock(int n,point p1,point p2){

  double rad = 60.0 * M_PI / 180.0;
  point a, b, c;

  if(n==0) return;

  a.x = (2*p1.x + p2.x) / 3;
  a.y = (2*p1.y + p2.y) / 3;
  b.x = (p1.x+2 * p2.x) / 3;
  b.y = (p1.y+2 * p2.y) / 3;
  c.x = (b.x-a.x) * cos(rad) - (b.y-a.y) * sin(rad) + a.x;
  c.y = (b.x-a.x) * sin(rad) + (b.y-a.y) * cos(rad) + a.y;

  kock(n-1, p1, a);
  printf("%.8f %.8f\n", a.x, a.y);
  kock(n-1, a, c);
  printf("%.8f %.8f\n", c.x, c.y);
  kock(n-1, c, b);
  printf("%.8f %.8f\n", b.x, b.y);
  kock(n-1, b, p2);
}

#include<stdio.h>
#include<math.h>

void getCurve(double l[2], double r[2], int i){
	if( i <= 0 ){ return; }
	double s[2], t[2], u[2];
	s[0] = l[0] + (r[0]-l[0])/3;
	s[1] = l[1] + (r[1]-l[1])/3;
	t[0] = l[0] + (r[0]-l[0])*2/3;
	t[1] = l[1] + (r[1]-l[1])*2/3;
	double dx = t[0]-s[0], dy = t[1]-s[1];
	u[0] = s[0] + dx * cos(M_PI/3) - dy * sin(M_PI/3);
	u[1] = s[1] + dx * sin(M_PI/3) + dy * cos(M_PI/3); 
	getCurve(l, s, i-1);
	printf("%.8lf %.8lf\n", s[0], s[1]);
	getCurve(s, u, i-1);
	printf("%.8lf %.8lf\n", u[0], u[1]);
	getCurve(u, t, i-1);
	printf("%.8lf %.8lf\n", t[0], t[1]);
	getCurve(t, r, i-1);
	return;
}

int main(){
	double l[2] = {0.0, 0.0}, r[2] = {100.0, 0.0};
	int n;
	scanf("%d", &n);
	printf("%.8lf %.8lf\n", l[0], l[1]);
	getCurve(l, r, n);
	printf("%.8lf %.8lf\n", r[0], r[1]);
	return 0;
}

