		r = w*M_PI/180.0;
		x1 = x + d * cos(r);
		y1 = y + d * sin(r);
		printf("%.8lf %.8lf\n", x1, y1);
		return;
	}

	d /= 3;
	koch(n - 1, d, x, y, w);

	r = w*M_PI/180.0;
	x = x + d * cos(r);
	y = y + d * sin(r);

	w += 60;
	koch(n - 1, d, x, y, w);

	r = w*M_PI/180.0;
	x = x + d * cos(r);
	y = y + d * sin(r);

	w += -120;
	koch(n - 1, d, x, y, w);

	r = w*M_PI/180.0;
	x = x + d * cos(r);
	y = y + d * sin(r);

	w += 60;
	koch(n - 1, d, x, y, w);

	return;
}

