void rec(Point p1,Point p2,int depth){
  if(depth == 0){ return; }
  Point s = {p1.x+(p2.x-p1.x)/3.0,p1.y+(p2.y-p1.y)/3.0};
  Point t = {p1.x+(p2.x-p1.x)*2.0/3.0,p1.y+(p2.y-p1.y)*2.0/3.0};
  Point u = rotate(s,t);
  rec(p1,s,depth-1);
  printf("%.10f %.10f\n",s.x,s.y);
  rec(s,u,depth-1);
  printf("%.10f %.10f\n",u.x,u.y);
  rec(u,t,depth-1);
  printf("%.10f %.10f\n",t.x,t.y);
  rec(t,p2,depth-1);
}

