double root(double d, int q) {
	double p1 = 0;
	double p2 = d;
	double m, p;

	do {
		m = ((p2 - p1) / 2.0) + p1;
		p = m * m;
		if (p > d) {
			p2 = m;
		} else if (p < d) {
			p1 = m;
		} else {
			return m;
		}
		--q;
	} while (q > 0);

	return m;
}

