void calc(float** vertex, int deep, int min, int max) {
	int s, t, u;
	if (deep <= 0) {
		return;
	}

	s = (max - min) / 3;
	vertex[s][0] = (vertex[max][0] - vertex[min][0]) / 3.0;
	vertex[s][1] = (vertex[max][1] - vertex[min][1]) / 3.0;
	t = (max - min) * 2 / 3;
	vertex[t][0] = (vertex[max][0] - vertex[min][0]) * 2.0 / 3.0;
	vertex[t][1] = (vertex[max][1] - vertex[min][1]) * 2.0 / 3.0;
	u = (max - min) / 2;
	vertex[u][0] = (vertex[t][0] - vertex[u][0]) / 2.0;
	vertex[u][1] = (vertex[t][0] - vertex[u][0]) * sin(60.0);

	calc(vertex, deep - 1, min, s);
	calc(vertex, deep - 1, s, u);
	calc(vertex, deep - 1, u, t);
	calc(vertex, deep - 1, t, max);
}

