void koch( int n, int ax, int ay, int bx, int by) {
  double M_PI = 3.14159263;
  if ( n == 0 ){
    return;
  }
  int sx, sy, tx, ty, ux, uy;
  double th = M_PI * 60.0 / 180.0;

  sx = (2.0 * ax + 1.0 * bx) / 3.0;
  sy = (2.0 * ay + 1.0 * by) / 3.0;
  tx = (1.0 * ax + 2.0 * bx) / 3.0;
  ty = (1.0 * ay + 2.0 * by) / 3.0;
  ux = (tx - sx) * cos(th) - (ty - sy) * sin(th) + sx;
  uy = (tx - sx) * sin(th) + (ty - sy) * cos(th) + sy;

  koch(n - 1, ax, ay, sx, sy);
  printf("%.8f %.8f\n", sx, sy);
  koch(n - 1, sx, sy, ux, uy);
  printf("%.8f %.8f\n", ux, uy);
  koch(n - 1, ux, uy, tx, ty);
  printf("%.8f %.8f\n", tx, ty);
  koch(n - 1, tx, ty, bx, by);
}

