  u.x = (t.x - s.x) * cos - (t.y - s.y) * sin + s.x;
  u.y = (t.x - s.x) * sin + (t.y - s.y) * cos + s.y;

  // p1, p2 から s, t, u を計算
  koch(n-1, p1, s);
