  struct P a, b, c;
  double rad=M_PI/3;

  a.x=(2*p1.x+p2.x)/3;
  a.y=(2*p1.y+p2.y)/3;
  b.x=(p1.x+2*p2.x)/3;
  b.y=(p1.y+2*p2.y)/3;
  c.x=(b.x-a.x)*cos(rad)-(b.y-a.y)*sin(rad)+a.x;
  c.y=(b.x-a.x)*sin(rad)+(b.y-a.y)*cos(rad)+a.y;

  kohho(p1,a,n-1);
  printf("%.8f %.8f\n", a.x, a.y);
  kohho(a,c,n-1);
  printf("%.8f %.8f\n", c.x, c.y);
  kohho(c,b,n-1);
  printf("%.8f %.8f\n", b.x, b.y);
  kohho(b,p2,n-1);  
}

