  // (n:+p:p) = 0:0:2, 1:3:5, 2:12:17, 3:48:65
  // +p(n) = (p(n-1) - 1) * 3
  // p(n) = +p(n) + p(n-1)

  // calculate {s, t, u}
  double rad = 60 * M_PI / 180.0;
  point_t s, t, u;
  s.x = (2 * ps.x + 1 * pe.x) / 3;
  s.y = (2 * ps.y + 1 * pe.y) / 3;
  t.x = (1 * ps.x + 2 * pe.x) / 3;
  t.y = (1 * ps.y + 2 * pe.y) / 3;
  u.x = (t.x - s.x) * cos(rad) - (t.y - s.y) * sin(rad) + s.x;
  u.y = (t.x - s.x) * sin(rad) + (t.y - s.y) * cos(rad) + s.y;

