fun koch(begin: Point, end: Point, depth: Int) {
    if (depth == 0) {
        return
    }
    val s = (begin * 2 + end) / 3
    val t = (begin + end * 2) / 3
    val u = Point((t - s).x * Math.cos(Math.PI / 3) - (t - s).y * Math.sin(Math.PI / 3) + s.x,
        (t - s).x * Math.sin(Math.PI / 3) + (t - s).y * Math.cos(Math.PI / 3) + s.y)
    koch(begin, s, depth - 1)
    println(s.toStr())
    koch(s, u, depth - 1)
    println(u.toStr())
    koch(u, t, depth - 1)
    println(t.toStr())
    koch(t, end, depth - 1)
}

