import java.util.NoSuchElementException;

public class Main {
	private static FastScanner sc = new FastScanner();

	public static void main(String[] args) {
		int n = sc.nextInt();

		kochCurve(0, 0, 100, 0, 0, n);
		System.out.println(100.0 + " " + 0.0);
	}

	static void kochCurve(double x1, double y1, double x2, double y2 ,int k , int n) {
		if(k == n) {
			System.out.println(x1 + " " + y1);
			return;
		}

		double l = 100 / Math.pow(3, k+1);

		double xs = (x2 - x1) / 3 + x1;
		double ys = (y2 - y1) / 3 + y1;
		double xt = (x2 - x1) * 2 / 3 + x1;
		double yt = (y2 - y1) * 2 / 3 + y1;

		double dif = 0;
		double xu;
		double yu;
		dif = (-1) / ((y2 - y1) / (x2 - x1));
		if((dif > 0 && x1 < x2) || (dif < 0 && x1 > x2)) {
			xu = ((x1 + x2) / 2) + (Math.sqrt(3) * l) / (2 * Math.sqrt(dif * dif + 1));
		} else {
			xu = ((x1 + x2) / 2) - (Math.sqrt(3) * l) / (2 * Math.sqrt(dif * dif + 1));
		}
		if(x1 < x2) {
			yu = ((y1 + y2) / 2) + (Math.sqrt(3) * l) / (2 * Math.sqrt((1/dif) * (1/dif) + 1));
		} else {
			yu = ((y1 + y2) / 2) - (Math.sqrt(3) * l) / (2 * Math.sqrt((1/dif) * (1/dif) + 1));
		}

		k++;

		kochCurve(x1, y1, xs, ys, k, n);
		kochCurve(xs, ys, xu, yu, k, n);
		kochCurve(xu, yu, xt, yt, k, n);
		kochCurve(xt, yt, x2, y2, k, n);
	}

	static class FastScanner {
	    private final InputStream in = System.in;
	    private final byte[] buffer = new byte[1024];
	    private int ptr = 0;
	    private int buflen = 0;
	    private boolean hasNextByte() {
	        if (ptr < buflen) {
	            return true;
	        }else{
	            ptr = 0;
	            try {
	                buflen = in.read(buffer);
	            } catch (IOException e) {
	                e.printStackTrace();
	            }
	            if (buflen <= 0) {
	                return false;
	            }
	        }
	        return true;
	    }
	    private int readByte() { if (hasNextByte()) return buffer[ptr++]; else return -1;}
	    private static boolean isPrintableChar(int c) { return 33 <= c && c <= 126;}
	    private void skipUnprintable() { while(hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++;}
	    public boolean hasNext() { skipUnprintable(); return hasNextByte();}
	    public String next() {
	        if (!hasNext()) throw new NoSuchElementException();
	        StringBuilder sb = new StringBuilder();
	        int b = readByte();
	        while(isPrintableChar(b)) {
	            sb.appendCodePoint(b);
	            b = readByte();
	        }
	        return sb.toString();
	    }
	    public long nextLong() {
	        return Long.parseLong(next());
	    }
	    public int nextInt(){
	    	return Integer.parseInt(next());
	    }
	}

}

import java.util.Scanner;

class Vector {
    double x, y;

    public Vector(double x, double y) {
        this.x = x;
        this.y = y;
    }

    @Override
    public String toString() {
        return
                (Math.abs(this.x) < 0000.1 ? "0.00000000" : this.x) +
                        " " +
                        (Math.abs(this.y) < 0000.1 ? "0.00000000" : this.y);
    }

    public Vector unit(Vector that) {
        return new Vector((that.x - this.x) / 3, (that.y - this.y) / 3);
    }

    public Vector plus(Vector that) {
        return new Vector(this.x + that.x, this.y + that.y);
    }

    public Vector rotate(double radians) {
        return new Vector(
                this.x * Math.cos(radians) - this.y * Math.sin(radians),
                this.x * Math.sin(radians) + this.y * Math.cos(radians)
        );
    }
}

public class Main {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        Vector left = new Vector(0, 0);
        Vector right = new Vector(100, 0);
        System.out.println(left.toString());
        printKochPoints(
                left,
                right,
                0,
                n
        );
        System.out.println(right.toString());
    }

    static void printKochPoints(Vector l, Vector r, int i, int n) {
        if (i >= n) {
            return;
        }

        Vector unit = l.unit(r);

        Vector p1 = l.plus(unit);
        Vector p1p2 = unit.rotate(Math.PI / 3);
        Vector p2 = p1.plus(p1p2);
        Vector lp3 = unit.rotate(Math.PI);
        Vector p3 = r.plus(lp3);

        printKochPoints(l, p1, i + 1, n);
        System.out.println(p1.toString());
        printKochPoints(p1, p2, i + 1, n);
        System.out.println(p2.toString());
        printKochPoints(p2, p3, i + 1, n);
        System.out.println(p3.toString());
        printKochPoints(p3, r, i + 1, n);
    }
}

