		kock(n - 1, sx, sy, ux, uy);
		System.out.print(ux);
		System.out.print(" ");
		System.out.println(uy);

		kock(n - 1, ux, uy, tx, ty);
		System.out.print(tx);
		System.out.print(" ");
		System.out.println(ty);

		kock(n - 1, tx, ty, p2x, p2y);
	}
