    koch(d-1, pu, pt); System.out.println(String.valueOf(pt.x) + ' ' + String.valueOf(pt.y));
    koch(d-1, pt, pr);
  }

  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int n = Integer.parseInt(sc.next());
