		Point u;
		if (p1.y == p2.y) {
			u = new Point(p1.x + (p2.x - p1.x) / 2.0, p1.y + (p2.x - p1.x) / 6.0 * Math.sqrt(3.0));
		}
		else if (p1.y < p2.y) {
			u = new Point(p1.x, t.y); 
		}
		else {
			u = new Point(p2.x, s.y);
		}

		kock(n-1, p1, s);
		System.out.println(s);
		kock(n-1, s, u);
		System.out.println(u);
		kock(n-1, u, t);
		System.out.println(t);
		kock(n-1, t, p2);
	}

