				yobi.setPoint(koch[j].getX(), koch[j].getY());
				koch[j].setPoint(koch[j+1].getX(), koch[j+1].getY());
				koch[j+1].setPoint(yobi.getX(), yobi.getY());

				m=kochLength[j];
				kochLength[j]=kochLength[j+1];
				kochLength[j+1]=m;
			    }
		    }


	    }

	for(i=0; i<length; i++)
	    {
		System.out.printf("%.8f %.8f\n", Math.abs(koch[i].getX()), Math.abs(koch[i].getY()));
	    }
    }
