	 * @param n　	コッホ曲線の数
	 * @param p1　	始点座標
	 * @param p2　	終点座標
	 */
	public static void kock(int n, Point2D.Double p1, Point2D.Double p2) {
		if (n == 0) {
			return;
		}
		Point2D.Double s = new Point2D.Double();
