class Main {
    static void drawCoch(int depth, Vector start, Vector goal) {
        if (depth == 0) {
            return;
        }

        Vector s = new Vector(2.0 / 3.0 * start.x + 1.0 / 3.0 * goal.x, 2.0 / 3.0 * start.y + 1.0 / 3.0 * goal.y);
