			System.out.printf("%.8f %.8f\n", x3_1, y3_1);
			System.out.printf("%.8f %.8f\n", x3_f, y3_f);
			System.out.printf("%.8f %.8f\n", x3_2, y3_2);
			//System.out.printf("%.8f %.8f\n",   x2,   y2);
