			KochCurve(deep + 1, n, x1, y1, x3_1, y3_1);
			KochCurve(deep + 1, n, x3_1, y3_1, x3_f, y3_f);
			KochCurve(deep + 1, n, x3_f, y3_f, x3_2, y3_2);
			KochCurve(deep + 1, n, x3_2, y3_2, x2, y2);
		}
