	   }
    }

    static Point getKoch(Point s, Point t)
    {
	double x = t.x - s.x;
	double y = t.y - s.y;

	double moveX = (Math.cos(Math.PI/3)*x - Math.sin(Math.PI/3)*y)+s.x;
	double moveY = (Math.sin(Math.PI/3)*x + Math.cos(Math.PI/3)*y)+s.y;

	Point u = new Point(moveX, moveY);
	return u;
    }

