		t[1] = (1.0 * a[1] + 2.0 * b[1]) / 3.0;
		u[0] = (t[0] - s[0]) * Math.cos(th) - (t[1] - s[1]) * Math.sin(th) + s[0];
		u[1] = (t[0] - s[0]) * Math.sin(th) + (t[1] - s[1]) * Math.cos(th) + s[1];

		koch(n - 1, a, s);
		System.out.printf("%.8f %.8f", s[0], s[1]);
