			s[j] = (2*start[j]+end[j])/3.0;
			t[j] = (start[j]+2*end[j])/3.0;
		}
		u[0]=(s[0]+t[0])/2 + Math.sqrt(3.0)*(s[1]-t[1])/2.0;
		u[1]=Math.sqrt(3.0)*(-s[0]+t[0])/2.0 +(s[1]+t[1])/2.0;
		koch(i-1, start,s);
