        if (call < n) {
            koch(ax, ay, x1, y1, call + 1, n);
        }
        System.out.println(x1 + " " + y1);
        if (call < n) {
            koch(x1, y1, x2, y2, call + 1, n);
        }
        System.out.println(x2 + " " + y2);
        if (call < n) {
            koch(x2, y2, x3, y3, call + 1, n);
        }
        System.out.println(x3 + " " + y3);
        if (call < n) {
            koch(x3, y3, bx, by, call + 1, n);
        }
    }
