public class Main {
    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        int n = scan.nextInt();
        Point2D p = new Point2D.Double(0, 0);
        Point2D r = new Point2D.Double(100,0);
        System.out.printf("%.8f %.8f\n",p.getX(),p.getY());
        curve(n, p, r);
        System.out.printf("%.8f %.8f",r.getX(),r.getY());
    }
    private static void curve(int n, Point2D a, Point2D b) {
        if (n > 0) {
            Point2D s = new Point2D.Double();
            Point2D t = new Point2D.Double();
            Point2D u = new Point2D.Double();
            double th = (Math.PI / 180) * 60;
            s.setLocation(((2.0 * a.getX() + 1.0 * b.getX()) / 3.0), ((2.0 * a.getY() + 1.0 * b.getY()) / 3.0));
            t.setLocation(((1.0 * a.getX() + 2.0 * b.getX()) / 3.0), ((1.0 * a.getY() + 2.0 * b.getY()) / 3.0));
            u.setLocation(((t.getX() - s.getX()) * Math.cos(th) - (t.getY() - s.getY()) * Math.sin(th) + s.getX()),
                    ((t.getX() - s.getX()) * Math.sin(th) + (t.getY() - s.getY()) * Math.cos(th) + s.getY()));
            curve(n - 1, a, s);
            System.out.printf("%.8f %.8f\n",s.getX(),s.getY());
            curve(n - 1, s, u);
            System.out.printf("%.8f %.8f\n",u.getX(),u.getY());
            curve(n - 1, u, t);
            System.out.printf("%.8f %.8f\n",t.getX(),t.getY());
            curve(n - 1, t, b);
        }
    }
}

import java.util.Scanner;

public class Main {
    static StringBuilder sb = new StringBuilder();

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        recursive(0, 0, 100, 0.0, n);
        sb.append("100.00000000 0.00000000");
        System.out.println(sb.toString());
    }

    private static void recursive(double st1, double st2, double en1, double en2, int n) {
        if (n == 0) {
            sb.append(st1 + " ").append(st2 + "\n");
            return;
        }
        double h = Math.hypot(en1 - st1, en2 - st2);//+ (en2 - st2) / 2
        double k = Math.sqrt(3) / 2 * (h / 3);
        double v = k * (en1 - st1) / h;
        double a = Math.pow(k, 2);
        double b = Math.pow(v, 2);
        Double p = Math.sqrt(a -b);
        if (p.isNaN()) {
            p = 0.0;
        }
        if (b<a){
            p=0-p;
        }
        double point = (en1 + st1) / 2 - p;

        recursive(st1, st2, st1 + (en1 - st1) / 3, st2 + (en2 - st2) / 3, n - 1);
        recursive(st1 + (en1 - st1) / 3, st2 + (en2 - st2) / 3,point, v + (en2 + st2) / 2, n - 1);
        recursive(point, v + (en2 + st2) / 2, st1 + ((en1 - st1) / 3 * 2), st2 + ((en2 - st2) / 3 * 2), n - 1);
        recursive(st1 + ((en1 - st1) / 3 * 2), st2 + ((en2 - st2) / 3 * 2), en1, en2, n - 1);
    }
}

