        double[] U={(T[0]-S[0])*Math.cos(pi)-(T[1]-S[1])*Math.sin(pi)+S[0],(T[0]-S[0])*Math.sin(pi)+(T[1]-S[1])*Math.cos(pi)+S[1]};

