class Point {
    public double x, y;
    Point( double x, double y )
    {
        this.x = x;
        this.y = y;
    }
    public static void move( Point move, double mx, double my, double si, double co )
    {
        double[][] xy = { {move.x},
                            {move.y},
                            {1} };
        double[][] r = { { co, -si, 0 },
                        { si, co, 0 },
                        { 0, 0, 1 } };
        double[][] m = { { 1, 0, mx },
                        { 0, 1, my },
                        { 0, 0, 1 } };    
        int i,j,k;
        double[][] a = new double[3][3];
        for( i=0; i<3; i++ ) {
            for( j=0; j<3; j++ ) {
                for( k=0; k<3; k++ ) {
                    a[i][j] += m[i][k]*r[k][j];
                }
            }
        }
        double[][] b = new double[3][1];
        for( i=0; i<3; i++ ) {
            for( j=0; j<3; j++ ) {
                b[i][0] += a[i][j]*xy[j][0];
            }
        }

        move.x = b[0][0];
        move.y = b[1][0];
        return;
    }    
}

