		try {
			int nico = Integer.parseInt(in.readLine());
			x.add(0.0);
			x.add(100.0);
			y.add(0.0);
			y.add(0.0);

			draw(nico);

			for (int i = 0; i < x.size(); i++) {
				System.out.println(x.get(i) + " " + y.get(i));
			}
		} catch (NumberFormatException e) {
