	private void draw(int nico) {
		if (nico == 0) return;

		for (int i = 1; i < x.size(); i++) {
			double x0 = x.get(i - 1);
			double y0 = y.get(i - 1);

			double x1 = x.get(i);
			double y1 = y.get(i);

			double rad = Math.atan((y1 - y0) / (x1 - x0));
			rad = rad + (Math.PI / 3);

			double dx = (x1 - x0) / 3;
			double dy = (y1 - y0) / 3;

			x.add(i, x0 + dx);
			y.add(i, y0 + dy);
			i++;

			double rx = Math.cos(rad) * dx - Math.sin(rad) * dy;
			double ry = Math.sin(rad) * dx + Math.cos(rad) * dy;

			x.add(i, x0 + dx + rx);
			y.add(i, y0 + dy + ry);
			i++;

			x.add(i, x1 - dx);
			y.add(i, y1 - dy);
			i++;
		}
	}
}

