                (t.x - s.x) * Math.cos(th) - (t.y - s.y) * Math.sin(th) + s.x,
                (t.x - s.x) * Math.sin(th) - (t.y - s.y) * Math.cos(th) + s.y);

        koch(d - 1, p1, s);
        s.print();
        koch(d - 1, s, u);
        u.print();
        koch(d - 1, u, t);
        t.print();
        koch(d - 1, t, p2);

