class Solve {
	private int n;
	private final double cos = Math.cos(Math.toRadians(60));
	private final double sin = Math.sin(Math.toRadians(60));

	public Solve(final int n)
	{
		this.n = n;
	}

	public void solve()
	{
		final double p1x = 0.0;
		final double p1y = 0.0;
		final double p2x = 100.0;
		final double p2y = 0.0;

		System.out.println(p1x + " " + p1y);
		kock(n, p1x, p1y, p2x, p2y);
		System.out.println(p2x + " " + p2y);
	}

	public void kock(final int n, final double p1x, final double p1y, final double p2x, final double p2y)
	{
		if(n == 0) return;

		final double lx = p2x - p1x;
		final double ly = p2y - p1y;
		final double sx = lx / 3 + p1x;
		final double sy = ly / 3 + p1y;
		final double tx = lx * 2 / 3 + p1x;
		final double ty = ly * 2 / 3 + p1y;
		final double ux = sx + (tx - sx) * cos - (ty - sy) * sin;
		final double uy = sy + (tx - sx) * sin + (ty - sy) * cos;

		kock(n - 1, p1x, p1y, sx, sy);
		System.out.println(sx + " " + sy);
		kock(n - 1, sx, sy, ux, uy);
		System.out.println(ux + " " + uy);
		kock(n - 1, ux, uy, tx, ty);
		System.out.println(tx + " " + ty);
		kock(n - 1, tx, ty, p2x, p2y);
	}
}
class ContestScanner {
	BufferedReader reader;
	String[] line;
	int index;
	public ContestScanner() {
		reader = new BufferedReader(new InputStreamReader(System.in));
	}

	public ContestScanner(String filename) throws FileNotFoundException {
		reader = new BufferedReader(new InputStreamReader(new FileInputStream(filename)));
	}

	public static interface ICreator<T> {
		public T createFromToken(final ContestScanner scanner) throws IOException;
	}

	public static interface IArrayInitializer {
		public void initialize(final ContestScanner scanner, final int i) throws IOException;
	}

	public static interface IObjectInitializer<T> {
		public T initialValue(final ContestScanner scanner);
	}

	public static class ObjectArrayInitializer<T> implements IArrayInitializer {
		protected T[] arr;
		protected final IObjectInitializer<T> initializer;

		private ObjectArrayInitializer(T[] arr, final IObjectInitializer<T> initializer)
		{
			this.arr = arr;
			this.initializer = initializer;
		}

		public static <T> ObjectArrayInitializer<T> create(T[] arr, final IObjectInitializer<T> initializer)
		{
			return new ObjectArrayInitializer<T>(arr, initializer);
		}

		public void initialize(final ContestScanner scanner, final int i) throws IOException {
			this.arr[i] = initializer.initialValue(scanner);
		}

		public T[] getArray()
		{
			return this.arr;
		}
	}


	public static class ByteArrayInitializer implements IArrayInitializer {
		protected byte[] arr;

		private ByteArrayInitializer(final int n)
		{
			this.arr = new byte[n];
