        u[1] = (t[0] - s[0]) * Math.sin(Math.PI / 3) + (t[1] - s[1]) * Math.cos(Math.PI / 3) + s[1];

        koch(n - 1, p1, s);
        print(s);
        koch(n - 1, s, u);
        print(u);
        koch(n - 1, u, t);
        print(t);
        koch(n - 1, t, p2);
