        }
    }

    class Program
    {
        static void Main(string[] args)
        {
            var n = int.Parse(Console.ReadLine());
            var queue = new Queue<Point>();
            queue.Enqueue(new Point(0, 0));
            queue.Enqueue(new Point(100, 0));
            while (n-- != 0) Recursion(queue);
            foreach (var p in queue) Console.WriteLine("{0} {1}", p.x, p.y);
        }

        static void Recursion(Queue<Point> q)
        {
            var cos = Math.Cos(Math.PI / 3);
            var sin = Math.Sin(Math.PI / 3);
            var p1 = q.Dequeue();
            q.Enqueue(p1);
            while (true)
            {
                if (q.Peek().Equals(new Point(0, 0))) break;
                var p = q.Dequeue();

                var v = new Point((p.x - p1.x) / 3, (p.y - p1.y) / 3);
                var s = new Point(p1.x + v.x, p1.y + v.y);
                var t = new Point(p1.x + v.x * 2, p1.y + v.y * 2);
                var u = new Point(s.x + v.x * cos - v.y * sin, s.y + v.x * sin + v.y * cos);
                q.Enqueue(s);
                q.Enqueue(u);
                q.Enqueue(t);
                q.Enqueue(p);
                p1 = p;
            }
        }
    }
}

