namespace KochCurv
{
    internal class Program
    {
        private static List<Vector2> vertices;
        public static void Main(string[] args)
        {
            var n = int.Parse(ReadLine());
            vertices = new List<Vector2>();
            vertices.Add(new Vector2(0f));
            Koch(n, new Vector2(0f), new Vector2(100f, 0f));

            vertices.Add(new Vector2(100f, 0f));
            Output(vertices);
        }

        static Vector2 Koch(int n, Vector2 startPos, Vector2 endPos)
        {
            if (n == 0) return endPos;
            var s = new Vector2((2f * startPos.x + 1f * endPos.x) / 3f, (2f * startPos.y + 1f * endPos.y) / 3f);
            var t = new Vector2((1f * startPos.x + 2f * endPos.x) / 3f, (1f * startPos.y + 2f * endPos.y) / 3f);
            var u = t.Rotate(s, Radians(60));

            vertices.Add(Koch(n - 1, startPos, s));
            vertices.Add(Koch(n - 1, s, u));
            vertices.Add(Koch(n - 1, u, t));
            Koch(n - 1, t, endPos);
            // vertices.Add(Koch(n - 1, t, endPos));
            return endPos;
        }

        static double Radians(double angle)
        {
            return angle * (Math.PI / 180);
        }

        static void Output(IEnumerable<Vector2> list)
        {
            var sw = new StreamWriter(OpenStandardOutput()) {AutoFlush = false};
            SetOut(sw);
            foreach (var vec in list)
            {

                WriteLine(vec.x + " " + vec.y);

            }
            Out.Flush();

        }
    }

    public struct Vector2
    {
        #region Constructor
        public Vector2(double xy)
        {
            this.x = xy;
            this.y = xy;
        }
        public Vector2(double x, double y)
        {
            this.x = x;
            this.y = y;
        }
        #endregion

        public double x;
        public double y;

        /// <summary>
        /// pointsを起点にradiansだけ回転させる
        /// </summary>
        /// <param name="points"></param>
        /// <param name="radians"></param>
        /// <returns></returns>
        public Vector2 Rotate(Vector2 points, double radians)
        {
            var x = (this.x - points.x) * Math.Cos(radians) - (this.y - points.y) * Math.Sin(radians) + points.x;
            var y = (this.x - points.x) * Math.Sin(radians) + (this.y - points.y) * Math.Cos(radians) + points.y;
            return new Vector2(x, y);
        }
    }
}

