    {
        //var exStdIn = new System.IO.StreamReader( "input.txt" );
        //System.Console.SetIn( exStdIn );

        int n = int.Parse(Console.ReadLine());

        float px = 0f;
        float py = 0f;
        float qx = 100f;
        float qy = 0f;

        Console.WriteLine(String.Format("{0} {1}", px, py));
        Solve(n, 0f, 0f, 100f, 0f);
        Console.WriteLine(String.Format("{0} {1}", qx, qy));
    }

    private static void Solve(int n, float px, float py, float qx, float qy)
    {
        if (n == 0)
        {
            return;
        }

        var sx = px + (qx - px) / 3;
        var sy = py + (qy - py) / 3;

        var tx = px + (qx - px) / 3 * 2;
        var ty = py + (qy - py) / 3 * 2;

        var ux = (float)((tx - sx) * Math.Cos(Math.PI / 3f) - (ty - sy) * Math.Sin(Math.PI / 3f) + sx);
        var uy = (float)((tx - sx) * Math.Sin(Math.PI / 3f) + (ty - sy) * Math.Cos(Math.PI / 3f) + sy);

        Solve(n-1, px, py, sx, sy);
        Console.WriteLine(string.Format("{0} {1}", sx, sy));
        Solve(n-1, sx, sy, ux, uy);
        Console.WriteLine(string.Format("{0} {1}", ux, uy));
        Solve(n-1, ux, uy, tx, ty);
        Console.WriteLine(string.Format("{0} {1}", tx, ty));
        Solve(n-1, tx, ty, qx, qy);

    }
}

