            var points = new List<point>();
            koch = (p1, p2, rad, num) =>
             {
                 if (--num < 0) return;
                 var pl = new point() { x = p1.x + (p2.x - p1.x) / 3, y = p1.y + (p2.y - p1.y) / 3 };
                 var pr = new point() { x = p1.x + 2 * (p2.x - p1.x) / 3, y = p1.y + 2 * (p2.y - p1.y) / 3 };
                 var nrad = rad + rad60;
                 var len = Math.Sqrt(Math.Pow(p1.x - p2.x, 2) + Math.Pow(p1.y - p2.y, 2)) / 3;
                 var pm = new point()
                 {
                     x = pl.x + len * Math.Cos(nrad),
                     y = pl.y + len * Math.Sin(nrad)
                 };
                 koch(p1, pl, rad, num);
                 points.Add(pl);
