        static void WritePoint(Point p)
        {
            Console.WriteLine(string.Format("{0} {1}", p.X, p.Y));
        }

        static void Koch(int n, Point p1, Point p2)
        {
            if (n == 0)
            {
                return;
            }

            Point s = new Point();
            Point t = new Point();
            Point u = new Point();

            s.X = (2 * p1.X + p2.X) / 3.0;
            s.Y = (2 * p1.Y + p2.Y) / 3.0;
            t.X = (p1.X + 2 * p2.X) / 3.0;
            t.Y = (p1.Y + 2 * p2.Y) / 3.0;

            u.X = (t.X - s.X) * cos60 - (t.Y - s.Y) * sin60 + s.X;
            u.Y = (t.X - s.X) * sin60 + (t.Y - s.Y) * cos60 + s.Y;

            Koch(n - 1, p1, s);
            WritePoint(s);
            Koch(n - 1, s, u);
            WritePoint(u);
            Koch(n - 1, u, t);
            WritePoint(t);
            Koch(n - 1, t, p2);
