		public static void Koch(int i)
		{
			if (i == 0)
			{
				s[1].Enqueue(new Point(0, 0));
				s[1].Enqueue(new Point(100, 0));
				return;
			}
			Koch(i - 1);
			Point p1, p2, p3, p4, p5;
			p1 = s[i % 2].Dequeue();
			while (s[i % 2].Count != 0)
			{
				p5 = s[i % 2].Dequeue();
				p2 = new Point((2 * p1.x + p5.x) / 3, (2 * p1.y + p5.y) / 3);
				p4 = new Point((p1.x + 2 * p5.x) / 3, (p1.y + 2 * p5.y) / 3);
				p3 = new Point(((p2.x + p4.x) - (-p2.y + p4.y) * Math.Sqrt(3)) / 2, ((-p2.x + p4.x) * Math.Sqrt(3) + (p2.y + p4.y)) / 2);
				s[(i + 1) % 2].Enqueue(p1);
				s[(i + 1) % 2].Enqueue(p2);
				s[(i + 1) % 2].Enqueue(p3);
				s[(i + 1) % 2].Enqueue(p4);
				p1 = p5;
