	class Program
	{
		static void Main(string[] args)
		{
			var N = int.Parse(Console.ReadLine());
			var start = new Point { X = 0, Y = 0 };
			var end = new Point { X = 100, Y = 0 };
			var array = Div(start, end, 0, N);
			var list = new List<Point>();
			list.Add(start);
			list.AddRange(array);

			list.ForEach(p => System.Console.WriteLine($"{p.X} {p.Y}"));
		}

		static Point[] Div(Point left, Point right, int n, int maxN)
		{
			if (maxN <= n)
			{
				return new Point[1] { right };
			}
			var dx = right.X - left.X;
			var dy = right.Y - left.Y;
			var s = new Point()
			{
				X = left.X + dx / 3.0,
				Y = left.Y + dy / 3.0,
			};
			var t = new Point()
			{
				X = left.X + dx * 2.0 / 3.0,
				Y = left.Y + dy * 2.0 / 3.0,
			};
			var rad = 2.0 / 3.0 * Math.PI;
			var tmpU = new Point();
			tmpU.X = Math.Cos(rad) * (right.X - t.X) - Math.Sin(rad) * (right.Y - t.Y);
			tmpU.Y = Math.Sin(rad) * (right.X - t.X) + Math.Cos(rad) * (right.Y - t.Y);
			var u = new Point()
			{
				X = tmpU.X + t.X,
				Y = tmpU.Y + t.Y,
			};
			var list = new List<Point>();
			list.AddRange(Div(left, s, n + 1, maxN));
			list.AddRange(Div(s, u, n + 1, maxN));
			list.AddRange(Div(u, t, n + 1, maxN));
			list.AddRange(Div(t, right, n + 1, maxN));

			return list.ToArray();
		}
	}

