    public void Koch(int depth, PPoint p1, PPoint p2)
    {
        if(depth == 0)
        {
            return;
        }

        PPoint s = new PPoint(0, 0);
        PPoint t = new PPoint(0, 0);
        PPoint u = new PPoint(0, 0);
        double th = Math.PI * 60d / 180d;

        s.X = (2 * p1.X + 1 * p2.X) / 3d;
        s.Y = (2 * p1.Y + 1 * p2.Y) / 3d;
        t.X = (1 * p1.X + 2 * p2.X) / 3d;
        t.Y = (1 * p1.Y + 2 * p2.Y) / 3d;
        u.X = (t.X - s.X) * Math.Cos(th) - (t.Y - s.Y) * Math.Sin(th) + s.X;
        u.Y = (t.X - s.X) * Math.Sin(th) - (t.Y - s.Y) * Math.Cos(th) + s.X;

        Koch(depth - 1, p1, s);
        Console.WriteLine(s.X.ToString("0.00000000") + " " + s.Y.ToString("0.00000000"));
        Koch(depth - 1, s, u);
        Console.WriteLine(u.X.ToString("0.00000000") + " " + u.Y.ToString("0.00000000"));
        Koch(depth - 1, u, t);
        Console.WriteLine(t.X.ToString("0.00000000") + " " + t.Y.ToString("0.00000000"));
        Koch(depth - 1, t, p2);
    }

