        var pointArr = new Point[] { new Point(0, 0), new Point(100, 0) };

        for (int i = 0; i < n; i++) {
            pointArr = Sequence(pointArr);
        }

        foreach (var point in pointArr) {
            Console.WriteLine(point);
        }


        #region Flush
#if !DEBUG
        Console.Out.Flush();
        sw.Close();
#endif
        #endregion
    }

    struct Point {
        public double X { get; set; }
        public double Y { get; set; }

        public Point(double x, double y) {
            X = x;
            Y = y;
        }

        public override string ToString() {
            return X + " " + Y;
        }
    }

    static Point[] Sequence(Point[] raw) {
        var result = new List<Point>();
        for (int i = 1; i < raw.Length; i++) {
            if (i == 1) {
                result.Add(raw[i - 1]);
            }

            result.AddRange(GetNewPoint(raw[i - 1], raw[i]));
            result.Add(raw[i]);
        }
        return result.ToArray();
    }

    static Point[] GetNewPoint(Point From, Point To) {
        Point[] result = new Point[3];

        result[0] = new Point((From.X * 2 + To.X) / 3, (From.Y * 2 + To.Y) / 3);
        result[2] = new Point((From.X + To.X * 2) / 3, (From.Y + To.Y * 2) / 3);

        result[1] = GetRotate(result[0], result[2]);
        return result;
    }

    private static Point GetRotate(Point From, Point To) {
        var rad60 = Math.PI * 60d / 180d;
        var kX = Math.Cos(rad60) * (To.X - From.X) - Math.Sin(rad60) * (To.Y - From.Y) + From.X;
        var kY = Math.Sin(rad60) * (To.X - From.X) + Math.Cos(rad60) * (To.Y - From.Y) + From.Y;

        return new Point(kX, kY);
    }
}
