    class Koch_Curve
    {
        static void Main(string[] args)
        {
            var p1 = new Vec(0, 0);
            var p2 = new Vec(100, 0);
            var n = int.Parse(Console.ReadLine());

            var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
            Console.SetOut(sw);

            Console.WriteLine(0 + " " + 0);
            Draw(p1, p2, n);

            Console.Out.Flush();
        }

        static void Draw(Vec left, Vec right, int n)
        {
            if (n == 0)
            {
                right.Show();
                return;
            }

            var v = (1.0 / 3) * (right - left);
            var s = left + v;
            var t = s + v.Rot60();
            var u = t + v.RotInv60();

            Draw(left, s, n - 1);
            Draw(s, t, n - 1);
            Draw(t, u, n - 1);
            Draw(u, right, n - 1);
        }

        struct Vec
        {
            public double x;
            public double y;
            public Vec(double x, double y)
            {
                this.x = x;
                this.y = y;
            }

            public Vec Rot60()
            {
                return new Vec(x * 0.5 - Math.Sqrt(3) * 0.5 * y, Math.Sqrt(3) * 0.5 * x + y * 0.5);
            }

            public Vec RotInv60()
            {
                return new Vec(x * 0.5 + Math.Sqrt(3) * 0.5 * y, -Math.Sqrt(3) * 0.5 * x + y * 0.5);
            }

            public static Vec operator +(Vec v, Vec w)
            {
                return new Vec(v.x + w.x, v.y + w.y);
            }

            public static Vec operator -(Vec v, Vec w)
            {
                return new Vec(v.x - w.x, v.y - w.y);
            }
            public static Vec operator *(double k, Vec v)
            {
                return new Vec(v.x * k, v.y * k);
            }

            public void Show()
            {
                Console.WriteLine(x + " " + y);
            }
        }
    }
