class KochPoint
  attr_reader :x, :y

  def initialize(x,y)
    @x = x
    @y = y
  end

  def rot60
    return KochPoint.new( @x*cos(PI*1/3) - @y*sin(PI*1/3),
                          @x*sin(PI*1/3) + @y*sin(PI*1/3) )
  end

  def +(p)
    return KochPoint.new( @x + p.x, @y + p.y)
  end
  def -(p)
    return KochPoint.new( @x - p.x, @y - p.y)
  end
  def *(n)
    return KochPoint.new( @x*n,  @y*n)
  end
  def /(n)
    return KochPoint.new( @x/n,  @y/n)
  end

  def printp
    print "#{@x} #{@y}\n"
  end
end

