type point struct {
	x float64
	y float64
}

type line struct {
	start point
	end   point
}

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Split(bufio.ScanWords)
	n, err := nextInt(sc)
	if err != nil {
		panic(err)
	}
	lines := koch(n, []line{line{point{0, 0}, point{100, 0}}})
	fmt.Printf("%f %f\n", lines[0].start.x, lines[0].start.y)
	for i := 0; i < len(lines); i++ {
		fmt.Printf("%f %f\n", lines[i].end.x, lines[i].end.y)
	}
}

func koch(n int, lines []line) []line {
	if n == 0 {
		return lines
	} else {
		nextLines := make([]line, 0)
		for _, line := range lines {
			nextLines = append(nextLines, createKoch(line)...)
		}
		return koch(n-1, nextLines)
	}
}

func createKoch(l line) []line {
	midLeft := point{
		l.end.x/3 + l.start.x*2/3,
		l.end.y/3 + l.start.y*2/3,
	}
	midRight := point{
		l.end.x*2/3 + l.start.x/3,
		l.end.y*2/3 + l.start.y/3,
	}
	mid := rotate(midLeft, midRight)
	return []line{
		line{l.start, midLeft},
		line{midLeft, mid},
		line{mid, midRight},
		line{midRight, l.end},
	}
}

func rotate(o, p point) point {
	rad := math.Pi / 3
	moved := point{
		p.x - o.x,
		p.y - o.y,
	}
	moved = point{
		math.Cos(rad)*moved.x - math.Sin(rad)*moved.y,
		math.Sin(rad)*moved.x + math.Cos(rad)*moved.y,
	}
	return point{
		moved.x + o.x,
		moved.y + o.y,
	}
}

func nextInt(sc *bufio.Scanner) (int, error) {
	sc.Scan()
	return strconv.Atoi(sc.Text())
}

