/*
コッホ曲線
*/

import (
	"bufio"
	"bytes"
	"fmt"
	"log"
	"math"
	"os"
	"strconv"
	"strings"
)

// Point 座標
type Point struct {
	x, y float64
}

func (p Point) String() string {
	return fmt.Sprintf("%f %f", p.x, p.y)
}

func divide3(p, q Point) (Point, Point) {
	div3X := (q.x - p.x) / 3.0
	div3Y := (q.y - p.y) / 3.0
	return Point{p.x + div3X, p.y + div3Y}, Point{p.x + (div3X * 2), p.y + (div3Y * 2)}
}

// 座標上の点を回転する
func rotate(p1, p2 Point, angle float64) Point {
	sinT, cosT := math.Sincos(angle)
	newX := ((cosT * (p2.x - p1.x)) + (-sinT * (p2.y - p1.y))) + p1.x
	newY := ((sinT * (p2.x - p1.x)) + (cosT * (p2.y - p1.y))) + p1.y
	return Point{newX, newY}
}

// コッホ曲線を得る
func getKoch(p1, p2 Point) (Point, Point, Point) {
	// 線分を三分割する
	s, t := divide3(p1, p2)
	// s,tに対する頂点を求める
	u := rotate(s, t, math.Pi/3.0)
	// 3つの点がわかる.
	return s, u, t
}

func getKochNRec(p1, p2 Point, n int, result *[]Point) {
	if n == 0 {
		// 先頭だけ入れる
		*result = append(*result, p1)
	} else {
		s, u, t := getKoch(p1, p2)
		getKochNRec(p1, s, n-1, result)
		getKochNRec(s, u, n-1, result)
		getKochNRec(u, t, n-1, result)
		getKochNRec(t, p2, n-1, result)
	}
}
func getKochN(p1, p2 Point, n int) []Point {
	result := make([]Point, 0, int(math.Pow(4, float64(n)))+1)
	getKochNRec(p1, p2, n, &result)
	result = append(result, p2)
	return result
}

func main() {
	scanner := makeScanner(8192)
	n := eGetInt(scanner)
	result := getKochN(Point{0, 0}, Point{100, 0}, n)
	for _, p := range result {
		fmt.Printf("%v\n", p)
	}
}

