	d, _ := strconv.Atoi(scanner.Text())

	p1 := &Point{X: 0.0, Y: 0.0}
	p2 := &Point{X: 100.0, Y: 0.0}

	// 始点
	a.f(fmt.Sprintf("%f %f", p1.X, p1.Y))

	// コッホ曲線の内分点
	a.koch(d, p1, p2)

	// 終点
	a.f(fmt.Sprintf("%f %f", p2.X, p2.Y))
}

