package main

import (
	"bufio"
	"fmt"
	"io"
	"log"
	"math"
	"os"
	"strconv"
	"strings"
)

type point struct {
	x float64
	y float64
}

func (p point) String() string {
	return fmt.Sprintf("%.8f %.8f", p.x, p.y)
}

func (p point) add(o point) point {
	return point{p.x + o.x, p.y + o.y}
}

func divide3(p1, p2 point) (point, point) {
	lenX := (p2.x - p1.x) / 3.0
	lenY := (p2.y - p1.y) / 3.0
	return point{p1.x + lenX, p1.y + lenY}, point{p1.x + (lenX * 2), p1.y + (lenY * 2)}
}

// 座標上の点を回転する
func rotate(p1, p2 point, angle float64) point {
	sinT, cosT := math.Sincos(angle)
	newX := ((cosT * (p2.x - p1.x)) + (-sinT * (p2.y - p1.y))) + p1.x
	newY := ((sinT * (p2.x - p1.x)) + (cosT * (p2.y - p1.y))) + p1.y
	return point{newX, newY}
}

func getSummit(p1, p2 point) point {
	return rotate(p1, p2, math.Pi/3.0)
}

func getKochSummit(p1, p2 point) (point, point, point) {
	s, u := divide3(p1, p2)
	t := getSummit(s, u)
	return s, t, u
}

func getKochCurve(p1, p2 point, count int) []point {
	result := make([]point, 0, int(math.Pow(float64(4), float64(count)))+1)
	getKochCurveRec(p1, p2, count, &result)
	// 最後の頂点を追加
	result = append(result, p2)
	return result
}
func getKochCurveRec(p1, p2 point, count int, result *[]point) {
	if count == 0 {
		// 再帰終了.
		// 先頭の頂点だけ追加
		*result = append(*result, p1)
	} else {
		s, t, u := getKochSummit(p1, p2)
		getKochCurveRec(p1, s, count-1, result)
		getKochCurveRec(s, t, count-1, result)
		getKochCurveRec(t, u, count-1, result)
		getKochCurveRec(u, p2, count-1, result)
	}
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	n := eGetInt(reader)
	result := getKochCurve(point{0, 0}, point{100, 0}, n)
	for _, p := range result {
		fmt.Println(p)
	}
}
func eGetLine(r *bufio.Reader) string {
	s, err := r.ReadString(byte('\n'))
	if err != nil {
		if err != io.EOF {
			log.Fatal(err.Error())
		}
		return s
	}
	return strings.TrimRight(s, "\r\n")
}
func eGetInt(r *bufio.Reader) int {
	line := eGetLine(r)
	return eAtoi(line)
}
func eGetInts(r *bufio.Reader) []int {
	line := eGetLine(r)
	fields := strings.Split(line, " ")
	var ints []int
	for _, f := range fields {
		ints = append(ints, eAtoi(f))
	}
	return ints
}
func eAtoi(s string) int {
	n, err := strconv.Atoi(s)
	if err != nil {
		log.Fatal(err)
	}
	return n
}

