type Point struct {
	x float64
	y float64
}

func koch(n int, a Point, b Point) {
	//nが0になったら再帰処理から抜ける
	if n == 0 {
		return
	}
	var s, t, u Point
	cos60 := 1.0 / 2.0
	sin60 := (math.Sqrt(3)) / 2.0

	//線分abを1:2に内分する点s
	s.x = (2.0*a.x + 1.0*b.x) / 3.0
	s.y = (2.0*a.y + 1.0*b.y) / 3.0
	//線分abを2:1に内分する点t
	t.x = (1.0*a.x + 2.0*b.x) / 3.0
	t.y = (1.0*a.y + 2.0*b.y) / 3.0
	//tを起点に、sを反時計回りに60度回転した点u
	u.x = (t.x-s.x)*cos60 - (t.y-s.y)*sin60 + s.x
	u.y = (t.x-s.x)*sin60 + (t.y-s.y)*cos60 + s.y

	//再帰処理
