point[] koch(point s, point t, int r)
{
  if (r == 0) return [];
  --r;

  auto u = s + (t - s) * (1.0 / 3);
  auto v = s + (t - s) * (2.0 / 3);
  auto w = u + (v - u).rot60;

  auto su = koch(s, u, r);
  auto uw = koch(u, w, r);
  auto wv = koch(w, v, r);
  auto vt = koch(v, t, r);

  return su ~ u ~ uw ~ w ~ wv ~ v ~ vt;
}

point rot60(point s)
{
  auto cos60 = 1.0 / 2;
  auto sin60 = 3.0.sqrt / 2;
  return point(s.x * cos60 - s.y * sin60, s.x * sin60 + s.y * cos60);
}

