from math import pi, cos, sin

class Point:
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def __str__(self):
        return str(self.x) + " " + str(self.y)

    def __add__(self, p):
        return Point(self.x + p.x, self.y + p.y)

    def __sub__(self, p):
        return Point(self.x - p.x, self.y - p.y)

    def __mul__(self, scala):
        return Point(self.x * scala, self.y * scala)

    def __div__(self, scala):
        return Point(self.x / scala, self.y / scala)

    def __truediv__(self, scala):
        return self.__div__(scala)

    def rotate(self, theta: float, origin: "Point"):
        if origin == None:
            origin = Point(0, 0)
        _self = self - origin
        x = _self.x * cos(theta) - _self.y * sin(theta)
        y = _self.x * sin(theta) + _self.y * cos(theta)        
        return Point(x, y) + origin


def dump(points: [Point]):
