        print(p)


def koch(points: [Point], n: int) -> [Point]:
    if n <= 0: return points
    if len(points) <= 1: return points

    _points = __koch(points)
    return koch(_points[0:2], n - 1) + \
        koch(_points[1:3], n - 1)[1:] + \
        koch(_points[2:4], n - 1)[1:] + \
        koch(_points[3:5], n - 1)[1:]


def tertile(pair: [Point, Point]) -> [Point, Point, Point, Point]:
    t1 = pair[0] + (pair[1] - pair[0]) / 3;
    t2 = pair[0] + (pair[1] - pair[0]) * 2 / 3;
    return [pair[0], t1, t2, pair[1]];


def __koch(pair: [Point, Point]) -> [Point, Point, Point, Point, Point]:
    four = tertile(pair)
    mid = four[1].rotate(-pi/3, four[2])
    return four[:2] + [mid] + four[2:]

