import numpy as np

def koch_divide(p,q):
    v = q-p
    r = np.array([[np.sqrt(3)/2, 0.5],[-0.5, np.sqrt(3)/2]])
    s = p + v/3
    t = q - v/3
    u = p + np.dot(v,r)/np.sqrt(3)
    return [s,u,t,q]

def koch_curve(previous):
    vertices = [previous[0]]
    for p,q in zip(previous[:-1], previous[1:]):
        vertices.extend(koch_divide(p,q))
    return vertices

