def koch(n, left, right):
	vector = [(right[0] - left[0])/3, (right[1] - left[1])/3]
	vector_up = [-vector[1]*(3**0.5)/2, vector[0]*(3**0.5)/2]
	point1 = [left[0] + vector[0], left[1] + vector[1]]
	point2 = [left[0] + 2*vector[0], left[1] + 2*vector[1]]
