			  left[1] + vector[1]*3/2 + vector_up[1]]

	if n == 0:
		return [right]

	if n == 1:
		return [point1, middle, point2, right]

	return koch(n-1, left, point1) + koch(n-1, point1, middle)\
			+ koch(n-1, middle, point2) + koch(n-1, point2, right)

