#[derive(Debug)]
struct Cordinate{
    x: f64,
    y: f64,
}

fn kock(n: usize, p1: &Cordinate, p2: &Cordinate) {
    if n == 0 {
        return;
    }

    let s = cul_s(&p1, &p2);
    let t = cul_t(&p1, &p2);
    let u = cul_u(&t, &s);

    kock(n - 1, &p1, &s);
    println!("{:.8} {:.8}", s.x, s.y);
    kock(n - 1, &s, &u);
    println!("{:.8} {:.8}", u.x, u.y);
    kock(n - 1, &u, &t);
    println!("{:.8} {:.8}", t.x, t.y);
    kock(n - 1, &t, &p2);
}

fn cul_s(p1: &Cordinate, p2: &Cordinate) -> Cordinate {
    Cordinate { 
        x: (2.0 * p1.x + p2.x) / 3.0,
        y: (2.0 * p1.y + p2.y) / 3.0
    }
}

fn cul_t(p1: &Cordinate, p2: &Cordinate) -> Cordinate {
    Cordinate {
        x: (p1.x + 2.0 * p2.x) / 3.0,
        y: (p1.y + 2.0 * p2.y) / 3.0
    }
}

fn cul_u(t: &Cordinate, s: &Cordinate) -> Cordinate {
    let num = std::f64::consts::PI / 3.0;
    let cos60 = num.cos();
    let sin60 = num.sin();
    Cordinate {
        x: (t.x - s.x) * cos60 - (t.y - s.y) * sin60 + s.x,
        y: (t.x - s.x) * sin60 + (t.y - s.y) * cos60 + s.y
    }
}

