struct Complex<T> {
    pub re: T, pub im: T,
}

impl<T> Complex<T> {
    pub fn new(re: T, im: T) -> Complex<T> {
        Complex { re: re, im: im }
    }
}

impl Complex<f64> {
    pub fn norm(&self) -> f64 {
        self.re.hypot(self.im)
    }

    pub fn abs(&self) -> f64 {
        self.norm().sqrt()
    }

    pub fn len(&self) -> f64 {
        self.abs()
    }

    pub fn rot(&self, rad: f64) -> Complex<f64> {
        *self * Self::polar(1.0, rad)
    }

    pub fn polar(abs: f64, rad: f64) -> Complex<f64> {
        Complex::new(abs * rad.cos(), abs * rad.sin())
    }
}

trait Num<T> : Mul<Output=T> + Div<Output=T> + Add<Output=T> + Sub<Output=T> + Copy {}

macro_rules! forward_ref_ref_binop {
    (impl $imp:ident, $method:ident) => {
        impl<'a, 'b, T: Clone + Num<T>> $imp<&'b Complex<T>> for &'a Complex<T> {
            type Output = Complex<T>;

            #[inline]
            fn $method(self, other: &Complex<T>) -> Complex<T> {
                self.clone().$method(other.clone())
            }
        }
    }
}

macro_rules! forward_ref_val_binop {
    (impl $imp:ident, $method:ident) => {
        impl<'a, T: Clone + Num<T>> $imp<Complex<T>> for &'a Complex<T> {
            type Output = Complex<T>;

            #[inline]
            fn $method(self, other: Complex<T>) -> Complex<T> {
                self.clone().$method(other)
            }
        }
    }
}

macro_rules! forward_val_ref_binop {
    (impl $imp:ident, $method:ident) => {
        impl<'a, T: Clone + Num<T>> $imp<&'a Complex<T>> for Complex<T> {
            type Output = Complex<T>;

            #[inline]
            fn $method(self, other: &Complex<T>) -> Complex<T> {
                self.$method(other.clone())
            }
        }
    }
}

macro_rules! forward_all_binop {
    (impl $imp:ident, $method:ident) => {
        forward_ref_ref_binop!(impl $imp, $method);
        forward_ref_val_binop!(impl $imp, $method);
        forward_val_ref_binop!(impl $imp, $method);
    };
}

impl<T> Add<T> for Complex<T>
where T: Add<Output=T> + Copy {
    type Output = Complex<T>;
    fn add(self, other: T) -> Complex<T> {
