    }
}

impl<T> Mul<Complex<T>> for Complex<T>
where T: Mul<Output=T> + Add<Output=T> + Sub<Output=T> + Copy {
    type Output = Complex<T>;
    fn mul(self, other: Complex<T>) -> Complex<T> {
        Complex::new(self.re * other.re - self.im * other.im,
                     self.re * other.im + self.im * other.re)
    }
}

forward_all_binop!(impl Mul, mul);

impl<T> Div<T> for Complex<T>
where T: Div<Output=T> + Copy {
    type Output = Complex<T>;
    fn div(self, other: T) -> Complex<T> {
        Complex::new(self.re / other, self.im / other)
    }
}

impl<T> Div<Complex<T>> for Complex<T>
where T: Mul<Output=T> + Div<Output=T> + Add<Output=T> + Sub<Output=T> + Copy {
    type Output = Complex<T>;
    fn div(self, other: Complex<T>) -> Complex<T> {
        Complex::new((other.re*self.re + other.im*self.im) / (other.re*other.re + other.im*other.im),
                     (other.re*self.im - other.im*self.re) / (other.re*other.re + other.im*other.im))
    }
}

forward_all_binop!(impl Div, div);

