    let p = a + (b - a) / 3.0;
    let q = p + (p - a).rot(std::f64::consts::PI / 3.0);
    let r = p + (p - a);
    (p, q, r)
}

fn rec(n: usize, a: Point, b: Point, res: &mut Vec<Point>) {
    if n > 0 {
        let (p, q, r) = f(a, b);
        rec(n - 1, a, p, res);
        res.push(p);
        rec(n - 1, p, q, res);
        res.push(q);
        rec(n - 1, q, r, res);
        res.push(r);
        rec(n - 1, r, b, res);
    }
}

