#[derive(Debug,Copy,Clone)]
struct Point {
    x: f64,
    y: f64,
}

#[derive(Debug)]
struct Quiz {
    n: u32,      // 0 <= N <= 6
    p0: Point,
    p1: Point,
}

#[derive(Debug)]
struct Answer {
    v: Vec<Point>,
}

trait IntoQuiz {
    fn into_quiz(self) -> Quiz;
}

impl<I: Input> IntoQuiz for I {
    fn into_quiz(mut self) -> Quiz {
        let n  = self.parse_next().unwrap();
        let p0 = Point{ x:0.0, y:0.0 };
        let p1 = Point{ x:100.0, y:0.0 };
        Quiz { n, p0, p1 }
    }
}

impl Quiz {
    fn solve(self) -> Answer {
        let n = self.n;
        let ps = self.p0;
        let pe = self.p1;
        let mut v = Vec::new();

        v.push(ps);
        Quiz::koch_inter(n, ps, pe, &mut v); 
        v.push(pe);

        Answer{ v }
    }

    fn koch_inter(n: u32, ps: Point, pe: Point, out: &mut Vec<Point>) {
        if n == 0 {
            return;
        }

        let p1 = Point {
            x: (ps.x * 2.0 + pe.x * 1.0) /3.0,
            y: (ps.y * 2.0 + pe.y * 1.0) /3.0,
        };
        let p3 = Point {
            x: (ps.x * 1.0 + pe.x * 2.0) /3.0,
            y: (ps.y * 1.0 + pe.y * 2.0) /3.0,
        };
        let inrad60 = std::f64::consts::PI/3.0;
        let sin60 = inrad60.sin();
        let cos60 = inrad60.cos();
        // p2 : v(p3-p1) * rotate(60) + p1
        let vx = p3.x - p1.x;
        let vy = p3.y - p1.y;
        let p2 = Point {
            x: vx*cos60 - vy*cos60 + p1.x,
            y: vx*sin60 + vy*cos60 + p1.y,
        };

        Quiz::koch_inter(n-1, ps, p1, out);
        out.push(p1);
        Quiz::koch_inter(n-1, p1, p2, out);
        out.push(p2);
        Quiz::koch_inter(n-1, p2, p3, out);
        out.push(p3);
        Quiz::koch_inter(n-1, p3, pe, out);
    }
}

