    P.push(a.clone());
    P.push(Point{x:(2.0*a.x+b.x)/3.0,y:(2.0*a.y+b.y)/3.0});
    P.push(Point{x:(a.x+b.x)/2.0-(b.y-a.y)*d,y:(a.y+b.y)/2.0+(b.x-a.x)*d});
