fn koch(n: u8, x1: f64, y1: f64, x2: f64, y2: f64) {
    if n == 0 {
        println!("{:.8} {:.8}", x1, y1);
        return
    }

    let sx = (2. * x1 + 1. * x2) / 3.;
    let sy = (2. * y1 + 1. * y2) / 3.;

    let tx = (x1 + 2. * x2) / 3.;
    let ty = (y1 + 2. * y2) / 3.;

    let f = std::f64::consts::FRAC_PI_3;
    let ux = (tx - sx) * f.cos() - (ty - sy) * f.sin() + sx;
    let uy = (tx - sx) * f.sin() + (ty - sy) * f.cos() + sy;

    koch(n - 1, x1, y1, sx, sy);
    koch(n - 1, sx, sy, ux, uy);
    koch(n - 1, ux, uy, tx, ty);
    koch(n - 1, tx, ty, x2, y2);
}

use std::f32;

fn norm(x: (f32, f32)) -> f32 {
    (x.0.powi(2) + x.1.powi(2)).sqrt()
}

fn print_tuple(t: (f32, f32)) {
    println!("{} {}", t.0, t.1);
}

fn koch_curve(p1: (f32, f32), p2: (f32, f32), depth: i32) {
    if depth == 0 {
        return;
    }

    let l = ((p2.0 - p1.0) / 3.0, (p2.1 - p1.1) / 3.0);
    let s = (p1.0 + l.0, p1.1 + l.1);
    let t = (p2.0 - l.0, p2.1 - l.1);
    let c = 1.0 / (2.0 * (3.0_f32).sqrt()) * norm((p1.0 + p2.0, p1.1 + p2.1))
        / norm((p2.0 - p1.0, p2.1 - p1.1));
    let u = (
        (p1.0 + p2.0) / 2.0 - c * (p2.1 - p1.1),
        (p1.1 + p2.1) / 2.0 + c * (p2.0 - p1.0),
    );

    //    print_tuple(p1);
    koch_curve(p1, s, depth - 1);
    print_tuple(s);
    koch_curve(s, u, depth - 1);
    print_tuple(u);
    koch_curve(u, t, depth - 1);
    print_tuple(t);
    koch_curve(t, p2, depth - 1);
    //    print_tuple(p2);
}

