const BUF_SIZE: usize = 1024;

unsafe fn solve(io: &mut Io) {
    io.w("0 0");
    re(io.r(), (0.0, 0.0), (100.0, 0.0), io);
}
fn re(n: usize, p1: (f64, f64), p2: (f64, f64), io: &mut Io) {
    let sqrt3 = 3.0f64.sqrt();
    if n > 0 {
        let s = ((p1.0 * 2.0 + p2.0) / 3.0, (p1.1 * 2.0 + p2.1) / 3.0);
        let t = ((p1.0 + p2.0 * 2.0) / 3.0, (p1.1 + p2.1 * 2.0) / 3.0);
        let u = (
            (t.0 - s.0) / 2.0 - (t.1 - s.1) * sqrt3 / 2.0 + s.0,
            (t.0 - s.0) * sqrt3 / 2.0 + (t.1 - s.1) / 2.0 + s.1,
        );
        re(n - 1, p1, s, io);
        re(n - 1, s, u, io);
        re(n - 1, u, t, io);
        re(n - 1, t, p2, io);
    } else {
        io.wn(p2.0);
        io.wn(' ');
        io.w(p2.1);
    }
}

