#[allow(unused_macros)]
macro_rules! scan {
  ($e:expr; $t:ty) => {
    $e.get::<$t>()
  };
  ($e:expr; $($t:ty), *) => {
    ($($e.get::<$t>(),)*)
  };
  ($e:expr => $i:expr; $t:ty) => {
    (0..$i).map(|_| $e.get::<$t>()).collect::<Vec<$t>>()
  };
  ($e:expr => $row:expr, $col:expr; $t:ty) => {
    (0..$i).map(|_| scan!($e => $col; $t)).collect::<Vec<$t>>()
  }
}

struct Scanner<R: Read> {
  reader: R
}

#[allow(dead_code)]
impl<R: Read> Scanner<R> {
  fn new(reader: R) -> Scanner<R> {
    Scanner { reader: reader }
  }
  fn safe_get<T: FromStr>(&mut self) -> Option<T> {
    let token = self.reader.by_ref().bytes().map(|c| c.unwrap() as char)
      .skip_while(|c| c.is_whitespace())
      .take_while(|c| !c.is_whitespace())
      .collect::<String>();
    if token.is_empty() { None } else { token.parse().ok() }
  }
  fn get<T: FromStr>(&mut self) -> T {
    if let Some(v) = self.safe_get() { v } else {
      writeln!(stderr(), "Terminated with EOF").unwrap();
      std::process::exit(0);
    }
  }
}

fn sin_from_deg(degree: f64) -> f64 {
  (degree * std::f64::consts::PI / 180.0).sin()
}

fn cos_from_deg(degree: f64) -> f64 {
  (degree * std::f64::consts::PI / 180.0).cos()
}

fn koch_curve(points: &mut Vec<(f64, f64)>, depth: i32, p1: (f64, f64), p2: (f64, f64)) {
  if depth == 0 {
    return;
  }
  let s = ((2.0 * p1.0 + p2.0) / 3.0, (2.0 * p1.1 + p2.1) / 3.0);
  let t = ((p1.0 + 2.0 * p2.0) / 3.0, (p1.1 + 2.0 * p2.1) / 3.0);
  let u = (
    (t.0 - s.0) * cos_from_deg(60.0) - (t.1 - s.1) * sin_from_deg(60.0) + s.0,
    (t.0 - s.0) * sin_from_deg(60.0) + (t.1 - s.1) * cos_from_deg(60.0) + s.1
  );
  koch_curve(points, depth - 1, p1, s);
  points.push(s);
  koch_curve(points, depth - 1, s, u);
  points.push(u);
  koch_curve(points, depth - 1, u, t);
  points.push(t);
  koch_curve(points, depth - 1, t, p2);
} 

