#[derive(Debug)]
struct Point {
    x: f64,
    y: f64
}

impl Point {
    fn print(&self) {
        println!("{:.8} {:.8}", self.x, self.y);
    }
}

fn koch(n: usize, start: &Point, end: &Point) {
    if n == 0 {
        return;
    }

    let th = PI * 60.0 / 180.0;
    let p1 = Point {
        x: (2.0 * start.x + end.x) / 3.0,
        y: (2.0 * start.y + end.y) / 3.0,
    };
    let p3 = Point {
        x: (start.x + 2.0 * end.x) / 3.0,
        y: (start.y + 2.0 * end.y) / 3.0,
    };
    let p2 = Point {
        x: (p3.x - p1.x) * th.cos() - (p3.y - p1.y) * th.sin() + p1.x,
        y: (p3.x - p1.x) * th.sin() + (p3.y - p1.y) * th.cos() + p1.y,
    };

    koch(n - 1, start, &p1);
    p1.print();
    koch(n - 1, &p1, &p2);
    p2.print();
    koch(n - 1, &p2, &p3);
    p3.print();
    koch(n - 1, &p3, end);
}

use std::f32;

fn norm(x: (f32, f32)) -> f32 {
    (x.0.powi(2) + x.1.powi(2)).sqrt()
}
fn koch_curve(p1: (f32, f32), p2: (f32, f32), depth: i32) {
    if depth == 0 {
        return;
    }

    let l = ((p2.0 - p1.0) / 3.0, (p2.1 - p1.1) / 3.0);
    let s = (p1.0 + l.0, p1.1 + l.1);
    let t = (p2.0 - l.0, p2.1 - l.1);
    let c = 1.0 / (2.0 * (3.0_f32).sqrt()) * norm((p1.0 + p2.0, p1.1 + p2.1))
        / norm((p2.0 - p1.0, p2.1 - p1.1));
    let u = (
        (p1.0 + p2.0) / 2.0 - c * (p2.1 - p1.1),
        (p1.1 + p2.1) / 2.0 + c * (p2.0 - p1.0),
    );

    println!("{:?}", p1);
    koch_curve(p1, s, depth - 1);
    println!("{:?}", s);
    koch_curve(s, u, depth - 1);
    println!("{:?}", u);
    koch_curve(u, t, depth - 1);
    println!("{:?}", t);
    koch_curve(t, p2, depth - 1);
    println!("{:?}", p2);
}

fn main() {
    let mut line = String::new();
    std::io::stdin().read_line(&mut line).ok();
    let n = line.trim().parse::<i32>().unwrap();
    koch_curve((0.0, 0.0), (100.0, 0.0), n);
}

