use std::ops::Add;
use std::ops::Sub;

struct Point {
    x: f64,
    y: f64,
}

impl Point {
    fn new(x: f64, y: f64) -> Point {
        Point { x, y }
    }

    fn print(&self) {
        println!("{} {}", self.x, self.y);
    }

    fn rot(&self, theta: f64) -> Point {
        let c = theta.cos();
        let s = theta.sin();
        let x = c * self.x - s * self.y;
        let y = s * self.x + c * self.y;
        Point::new(x, y)
    }
}

impl Clone for Point {
    fn clone(&self) -> Point {
        Point::new(self.x, self.y)
    }
}

impl Add for Point {
    type Output = Point;

    fn add(self, other: Point) -> Point {
        Point::new(self.x + other.x, self.y + other.y)
    }
}

impl Sub for Point {
    type Output = Point;

    fn sub(self, other: Point) -> Point {
        Point::new(self.x - other.x, self.y - other.y)
    }
}

fn koch(n: u32, p1: &Point, p2: &Point) {
    if n == 0 {
        p1.print();
    } else {
        let sx = p1.x * 2.0 / 3.0 + p2.x / 3.0;
        let sy = p1.y * 2.0 / 3.0 + p2.y / 3.0;
        let tx = p1.x / 3.0 + p2.x * 2.0 / 3.0;
        let ty = p1.y / 3.0 + p2.y * 2.0 / 3.0;
        let s = Point::new(sx, sy);
        let t = Point::new(tx, ty);
        let tmp = t.clone() - s.clone();
        let u = s.clone() + tmp.rot(std::f64::consts::PI / 3.0);
        koch(n - 1, &p1, &s);
        koch(n - 1, &s, &u);
        koch(n - 1, &u, &t);
        koch(n - 1, &t, &p2);
    }
}

fn main() {
    let n: u32 = read();

    let p1 = Point::new(0.0, 0.0);
    let p2 = Point::new(100.0, 0.0);

    koch(n, &p1, &p2);
    p2.print();
}

use std::f64;

fn norm(x: (f64, f64)) -> f64 {
    (x.0.powi(2) + x.1.powi(2)).sqrt()
}

fn print_tuple(t: (f64, f64)) {
    println!("{} {}", t.0, t.1);
}

fn koch_curve(p1: (f64, f64), p2: (f64, f64), depth: i32) {
    if depth == 0 {
        return;
    }

    let l = ((p2.0 - p1.0) / 3.0, (p2.1 - p1.1) / 3.0);
    let s = (p1.0 + l.0, p1.1 + l.1);
    let t = (p2.0 - l.0, p2.1 - l.1);
    let c = 1.0 / (2.0 * (3.0_f64).sqrt()) * norm((p1.0 + p2.0, p1.1 + p2.1))
        / norm((p2.0 - p1.0, p2.1 - p1.1));
    let u = (
        (p1.0 + p2.0) / 2.0 - c * (p2.1 - p1.1),
        (p1.1 + p2.1) / 2.0 + c * (p2.0 - p1.0),
    );

    //    print_tuple(p1);
    koch_curve(p1, s, depth - 1);
    print_tuple(s);
    koch_curve(s, u, depth - 1);
    print_tuple(u);
    koch_curve(u, t, depth - 1);
    print_tuple(t);
    koch_curve(t, p2, depth - 1);
    //    print_tuple(p2);
}

fn main() {
    let mut line = String::new();
    std::io::stdin().read_line(&mut line).ok();
    let n = line.trim().parse::<i32>().unwrap();

    println!("0 0");
    koch_curve((0.0, 0.0), (100.0, 0.0), n);
    println!("100 0");
}

