fn readInt() -> i32 {
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).ok();
    s.trim().parse().ok().unwrap()
}

fn koch(depth: i32, p1: &Point, p2: &Point) {
    let r = std::f64::consts::PI / 3.0;
    let si = r.sin();
    let co = r.cos();

    if depth == 0 {
        return;
    } else {
        let d = depth - 1;
        let s = Point{ x: (2.0 * p1.x + p2.x) / 3.0, y: (2.0 * p1.y + p2.y) / 3.0 }; 
        let t = Point{ x: (p1.x + 2.0 * p2.x) / 3.0, y: (p1.y + 2.0 * p2.y) / 3.0 };
        let u = Point{
            x: (t.x - s.x) * co - (t.y - s.y) * si + s.x,
            y: (t.x - s.x) * si + (t.y - s.y) * co + s.y
        };
        koch(d, &p1, &s);
        println!("{}", s.toStr());
        koch(d, &s, &u);
        println!("{}", u.toStr());
        koch(d, &u, &t);
        println!("{}", t.toStr());
        koch(d, &t, &p2);
    }
}

use std::io::*;
use std::str::*;
use std::f64::consts::*;
use std::f64;

macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        input_inner!{iter, $($r)*}
    };
    ($($r:tt)*) => {
        let mut s = {
            use std::io::Read;
            let mut s = String::new();
            std::io::stdin().read_to_string(&mut s).unwrap();
            s
        };
        let mut iter = s.split_whitespace();
        input_inner!{iter, $($r)*}
    };
}

macro_rules! input_inner {
    ($iter:expr) => {};
    ($iter:expr, ) => {};

    ($iter:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($iter, $t);
        input_inner!{$iter $($r)*}
    };
}

macro_rules! read_value {
    ($iter:expr, ( $($t:tt),* )) => {
        ( $(read_value!($iter, $t)),* )
    };

    ($iter:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($iter, $t)).collect::<Vec<_>>()
    };

    ($iter:expr, chars) => {
        read_value!($iter, String).chars().collect::<Vec<char>>()
    };

    ($iter:expr, usize1) => {
        read_value!($iter, usize) - 1
    };

    ($iter:expr, $t:ty) => {
        $iter.next().unwrap().parse::<$t>().expect("Parse error")
    };
}

struct Point {
    x: f64,
    y: f64,
}

impl Point {
    fn new() -> Point {
        Point {
            x: 0.0,
            y: 0.0,
        }
    }
}

fn koch(n: u32, a: &Point, b: &Point) {
    if (n == 0) { return; }
    let mut s = Point::new();
    let mut t = Point::new();
    let mut u = Point::new();
    let th = PI * 60.0 / 180.0;

    s.x = (2.0 * a.x + 1.0 * b.x) / 3.0;
    s.y = (2.0 * a.y + 1.0 * b.y) / 3.0;
    t.x = (1.0 * a.x + 2.0 * b.x) / 3.0;
    t.y = (1.0 * a.y + 2.0 * b.y) / 3.0;
    u.x = (t.x - s.x) * th.cos() - (t.y - s.y) * th.sin() + s.x;
    u.y = (t.x - s.x) * th.sin() + (t.y - s.y) * th.cos() + s.y;

    koch(&n - 1, &a, &s);
    println!("{:.8} {:.8}", s.x, s.y);
    koch(&n - 1, &s, &u);
    println!("{:.8} {:.8}", u.x, u.y);
    koch(&n - 1, &u, &t);
    println!("{:.8} {:.8}", t.x, t.y);
    koch(&n - 1, &t, &b);
}

fn main() {
    let a = Point::new();
    let mut b = Point::new();

    input!{
        n: u32,
    }

    b.x = 100.0;

    println!("{:.8} {:.8}", a.x, a.y);
    koch(n, &a, &b);
    println!("{:.8} {:.8}", b.x, b.y);

    return;
}

// ALDS1_5_C: Koch Curve

use std::f32;

struct Point {
    x: f32,
    y: f32,
}

fn koch(n: usize, a: &Point, b: &Point) {
    if n == 0 {
        return;
    }
    let s = Point{
        x: (2.0 * a.x + 1.0 * b.x) / 3.0, 
        y: (2.0 * a.y + 1.0 * b.y) / 3.0,
    };
    let t = Point{
        x: (1.0 * a.x + 2.0 * b.x) / 3.0,
        y: (1.0 * a.y + 2.0 * b.y) / 3.0,
    };
    let th = f32::consts::PI * 60.0 / 180.0;
    let u = Point{
        x: (t.x - s.x) * th.cos() - (t.y - s.y) * th.sin() + s.x,
        y: (t.x - s.x) * th.sin() + (t.y - s.y) * th.cos() + s.y,
    };

    koch(n - 1, a, &s);
    println!("{:12.8} {:12.8}", s.x, s.y);
    koch(n - 1, &s, &u);
    println!("{:12.8} {:12.8}", u.x, u.y);
    koch(n - 1, &u, &t);
    println!("{:12.8} {:12.8}", t.x, t.y);
    koch(n - 1, &t, b);
}

fn main() {
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).unwrap();
    let n: usize = s.trim().parse().ok().unwrap();

    let a = Point{ x:   0.0, y: 0.0 };
    let b = Point{ x: 100.0, y: 0.0 };

    println!("{:12.8} {:12.8}", a.x, a.y);
    koch(n, &a, &b);
    println!("{:12.8} {:12.8}", b.x, b.y);
}
